insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$principal$q$,$q$مدير المدرسة$q$,null,array[$q$يرتبط مدير المدرسة (الابتدائية / المتوسطة / الثانوية) حسب مرحلتها، ب (مدير المرحلة) المعني في قسم الإدارة المدرسية بإدارة التعليم العامة.$q$,$q$ترتبط مديرة رياض الأطفال بمدير قسم رياض الأطفال في إدارة التعليم العامة.$q$,$q$ترتبط مديرة الحضانة بمدير قسم الحضانة في إدارة التعليم العامة.$q$,$q$يرتبط مدير مدرسة التعليم المستمر بمدير قسم التعليم المستمر في إدارة التعليم العامة.$q$,$q$يرتبط مدير مدرسة الطلاب ذوي الإعاقة (باستثناء مدارس الدمج) بمدير قسم ذوي الإعاقة بإدارة التعليم العامة (باستثناء المراكز أو المعاهد أو ما في حكمها المختصة بذوي الإعاقة والتي صدر بها تنظيم مستقل معتمد من صاحب الصلاحية).$q$,$q$يرتبط مدير مدرسة الموهوبين بمدير قسم الموهوبين بإدارة التعليم العامة.$q$]::text[],$q$الإشراف على المدرسة ومتابعة مستوى الأداء والتخطيط والتنظيم والتقويم لرعاية شؤون الطلاب في المدرسة ومعالجة جميع القضايا المتعلقة بهم تربوياً وتعليمياً لتحقيق الأهداف وتحسين نواتج التعلم$q$,array[$q$شهادة جامعية أو أعلى$q$,$q$الرخصة المهنية المطلوبة رتبة معلم ممارس فأعلى.$q$,$q$عضوية في اللجان ذات العلاقة بالوظيفة، أو ترأسه لفرق عمل ذات علاقة$q$,$q$خبرة 7 سنوات، منها 4 سنوات في التدريس.$q$,$q$خبرة 3 سنوات كوكيل مدرسة (باستثناء مديري المدارس الصغيرة)$q$]::text[],null,'{}'::text[],1) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$deputy_academic$q$,$q$وكيل المدرسة للشؤون التعليمية$q$,null,array[$q$يرتبط بمدير المدرسة$q$]::text[],$q$الإشراف على عمليات التعليم والتعلم، ومتابعة مستوى الأداء التعليمي ومراجعة التحصيل الدراسي للطلاب وتحليله بشكل دوري لتحسين مستوى أدائهم، ومتابعة أداء المعلمين وتطويرهم مهنياً.$q$,array[$q$شهادة جامعية$q$,$q$عضوية في اللجان ذات العلاقة بالوظيفة، أو ترأسه لفرق عمل ذات علاقة$q$,$q$إجمالي خبرة 8 سنوات$q$,$q$رتبة معلم ممارس بخبرة 4 سنوات فأعلى أو رتبة معلم متقدم أو معلم خبير$q$]::text[],null,'{}'::text[],2) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$deputy_students$q$,$q$وكيل المدرسة لشؤون الطلاب$q$,null,array[$q$يرتبط بمدير المدرسة$q$]::text[],$q$المشاركة في إدارة الشؤون الطلابية في المدرسة من حيث الإدارة، التسجيل، والأنشطة الطلابية بما يتوافق مع أهداف المدرسة ويحسن من نواتج التعلم.$q$,array[$q$شهادة جامعية (علم نفس/علم اجتماع أو بكالوريوس تربوي + دبلوم توجيه وإرشاد)$q$,$q$عضوية في اللجان ذات العلاقة بالوظيفة، أو ترأسه لفرق عمل ذات علاقة$q$,$q$إجمالي خبرة 8 سنوات$q$,$q$خبرة 3 سنوات في التوجيه الطلابي أو النشاط الطلابي.$q$,$q$رتبة معلم ممارس بخبرة 4 سنوات فأعلى أو رتبة معلم متقدم أو معلم خبير$q$]::text[],null,'{}'::text[],3) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$deputy_school_affairs$q$,$q$وكيل المدرسة للشؤون المدرسية$q$,null,array[$q$يرتبط بمدير المدرسة$q$]::text[],$q$الإشراف على الشؤون المتعلقة بالمدرسة لتوفير بيئة تعليمية مناسبة وآمنة، بما يحقق أهداف المدرسة ويحسن من نواتج التعلم$q$,array[$q$شهادة جامعية$q$,$q$عضوية في اللجان ذات العلاقة بالوظيفة، أو ترأسه لفرق عمل ذات علاقة.$q$,$q$إجمالي خبرة 8 سنوات$q$,$q$رتبة معلم ممارس بخبرة 4 سنوات فأعلى أو رتبة معلم متقدم أو معلم خبير.$q$]::text[],null,'{}'::text[],4) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$teacher$q$,$q$المعلم$q$,$q$يشمل المعلم الخبير والمتقدم والممارس$q$,array[$q$يرتبط بوكيل المدرسة للشؤون التعليمية$q$]::text[],$q$الإسهام في بناء شخصية الطالب بكافة جوانبها والارتقاء بمستواه التربوي والتعليمي من خلال توفير بيئة تعليمية وتعلمية محفزة -جميع الرتب التعليمية- ودعم المعلمين في تحسين عملية التعليم والتعلم -المعلم المتقدم والخبير- وتطوير الممارسات الإبداعية والمبتكرة التي تحسن من عملية التعليم والتعلم -المعلم الخبير.$q$,array[$q$شهادة تربوية جامعية أو أعلى تتناسب مع التخصص المطلوب$q$]::text[],$q$المهارات التقنية ، التفكير المرن ، الانتماء ، الإنجاز ، تطوير الذات$q$,'{}'::text[],5) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$teacher_assistant$q$,$q$مساعد معلم$q$,null,array[$q$يرتبط بوكيل المدرسة للشؤون التعليمية$q$]::text[],$q$مساعدة المعلم في إدارة عمليات التعليم والتعلم للطلاب، وضبط الفصل، بهدف تحسين نواتج التعلم، وتحقيق أهداف المدرسة.$q$,array[$q$ثانوية عامة فأعلى.$q$,$q$دبلوم لا تقل مدته عن عام دراسي واحد في أحد التخصصات المناسبة لمجال العمل في هذه الرتبة .$q$]::text[],null,'{}'::text[],6) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$sped_teacher$q$,$q$معلم ذوي الإعاقة$q$,$q$يشمل المعلم الخبير والمتقدم والممارس$q$,array[$q$يرتبط بوكيل المدرسة للشؤون التعليمية$q$]::text[],$q$الإسهام في بناء شخصية الطالب ذوي الإعاقة بكافة جوانبها والارتقاء بمستواه التربوي والتعليمي -جميع الرتب التعليمية- ودعم المعلمين في تحسين عملية التعليم والتعلم -المعلم المتقدم والخبير- وتطوير الممارسات الإبداعية والمبتكرة التي تحسن من عملية التعليم والتعلم -المعلم الخبير$q$,array[$q$شهادة جامعية أو أعلى في التربية الخاصة$q$]::text[],null,'{}'::text[],7) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$gifted_teacher$q$,$q$معلم الموهوبين$q$,$q$يشمل المعلم الخبير والمتقدم والممارس$q$,array[$q$يرتبط بوكيل المدرسة للشؤون التعليمية$q$]::text[],$q$الإسهام في بناء شخصية الطالب الموهوب بكافة جوانبها والارتقاء بمستواه التربوي والتعليمي من خلال توفير بيئة تعليمية وتعلمية محفزة -جميع الرتب التعليمية- ودعم المعلمين في تحسين عملية التعليم والتعلم -المعلم المتقدم والخبير- وتطوير الممارسات الإبداعية والمبتكرة التي تحسن من عملية التعليم والتعلم -المعلم الخبير.$q$,array[$q$شهادة جامعية (في التفوق والابتكار أو تخصص علمي +دورات في الموهبة والابتكار)$q$,$q$خبرة 5 سنوات فأكثر في التعليم$q$]::text[],null,'{}'::text[],8) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$kg_teacher$q$,$q$معلمة رياض الأطفال$q$,$q$يشمل المعلم الخبير والمتقدم والممارس$q$,array[$q$ترتبط بوكيلة المدرسة للشؤون التعليمية$q$]::text[],$q$الإسهام في بناء شخصية الطفل بكافة جوانبها والارتقاء بمستواه التربوي والتعليمي من خلال توفير بيئة تعليمية وتعلمية محفزة -جميع الرتب التعليمية- ودعم المعلمين في تحسين عملية التعليم والتعلم -المعلم المتقدم والخبير- وتطوير الممارسات الإبداعية والمبتكرة التي تحسن من عملية التعليم والتعلم -المعلم الخبير.$q$,array[$q$شهادة جامعية تخصص رياض أطفال$q$]::text[],$q$المهارات الوظيفية التقنية ، التفكير المرن ، الانتماء ، الإنجاز ، تطوير الذات ، ضبط النفس$q$,array[$q$ورد الاسم في الدليل بصيغتي «معلمة رياض أطفال» و«معلمة رياض الأطفال».$q$]::text[],9) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$sped_teacher_assistant$q$,$q$مساعد معلم (ذوي الإعاقة)$q$,null,array[$q$يرتبط بوكيل المدرسة للشؤون التعليمية$q$]::text[],$q$مساعدة معلم ذوي الإعاقة في إدارة عمليات التعليم والتعلم للطلاب ذوي الإعاقة وضبط الفصل، بهدف تحسين نواتج التعلم، وتحقيق أهداف المدرسة.$q$,array[$q$ثانوية عامة فأعلى (يُفضل دبلوم جامعي أو أعلى في ذوي الإعاقة (لمدة عام على الأقل)$q$,$q$المعرفة بلغة الإشارة لتخصصات الإعاقة السمعية (فئة: الصم).$q$,$q$اُلمعرّفة بطريقة برايل لتخصصات الإعاقة البصرية (فئة: المكفوفين).$q$,$q$يُفضّل من لديه دورة تدريبية في التعامل مع ذوي الإعاقة.$q$,$q$يفضل من لديه دورة تدريبية في دعم السلوك الإيجابي (PBS).$q$]::text[],null,'{}'::text[],10) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$activity_leader$q$,$q$رائد النشاط$q$,null,array[$q$يرتبط بوكيل المدرسة للشؤون الطلاب$q$]::text[],$q$تنفيذ خطة النشاط الطلابي واكتشاف قدرات الطلاب وميولهم والاسهام في بناء شخصية الطلبة المتكاملة ليكونوا فاعلين في مجتمعهم من خلال التدريب على المهارات الحياتية ومن خلال الأنشطة (الفنية ، الاجتماعية ، الثقافية ، الرياضية ، العلمية ، الكشفية ...)$q$,array[$q$شهادة جامعية$q$]::text[],null,'{}'::text[],11) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$student_counselor$q$,$q$الموجه الطلابي$q$,null,array[$q$يرتبط بوكيل المدرسة للشؤون الطلاب$q$]::text[],$q$تقديم الدعم النفسي والاجتماعي للطالب، ليفهم ذاته ويعرف قدراته وينمي إمكاناته، ويتمكن من حل مشكلاته بما يحقق له التوافق النفسي والاجتماعي والمهني والتربوي، بما يعزز أهداف التعليم والتعلم ويحسن نواتجها.$q$,array[$q$شهادة جامعية (علم نفس/علم اجتماع / خدمة اجتماعية) أو بكالوريوس تربوي + دبلوم توجيه وإرشاد أو ماجستير فأعلى في التخصص$q$]::text[],null,'{}'::text[],12) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$health_counselor$q$,$q$الموجه الصحي$q$,null,array[$q$يرتبط بوكيل المدرسة للشؤون الطلاب$q$]::text[],$q$العمل على إيجاد بيئة صحية مناسبة في المدرسة، من خلال توعية الطلاب صحيًا، وتقديم الإسعافات الأولية اللازمة لهم، بهدف توفير بيئة صحية تعزز تحقيق أهداف المدرسة وتحسين نواتج التعلم.$q$,array[$q$شهادة جامعية (دورات إسعافات أولية متقدمة)$q$]::text[],null,'{}'::text[],13) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$learning_resources_keeper$q$,$q$أمين مصادر التعلّم (مسؤول معامل الحاسب الآلي وغرف مصادر التعلم)$q$,null,array[$q$يرتبط بوكيل الشؤون المدرسية$q$]::text[],$q$الإشراف على جميع العمليات والخدمات الخاصة بالمصادر لضمان تقديم الخدمات الخاصة بالبحث والدراسات والمراجع المناسبة لجميع المستفيدين لدعم جميع البرامج والتخصصات بالمدرسة$q$,array[$q$شهادة جامعية (تقني/ (إداري + دورات تقنية متقدمة)$q$]::text[],null,'{}'::text[],14) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$lab_technician$q$,$q$محضر مختبر$q$,null,array[$q$يرتبط بوكيل الشؤون المدرسية$q$]::text[],$q$الإشراف على إعداد وتشغيل الأجهزة والمواد التعليمية في المختبرات المستخدمة في المدرسة لضمان توفر الدعم اللازم للقيام بمهام التدريس العملي أو أي أنشطة مدرسية أخرى تتم داخل المختبر.$q$,array[$q$دبلوم تحضير مختبرات أو بكالوريوس علوم/ إداري ودورات في المختبرات$q$]::text[],null,'{}'::text[],15) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$admin_assistant$q$,$q$المساعد الإداري (سكرتير)$q$,null,array[$q$يرتبط بمدير/وكيل المدرسة حسب موقعه التنظيمي$q$]::text[],$q$تقديم الدعم الإداري للمدير/الوكيل، وأداء المهام الإدارية والمساندة في المدرسة.$q$,array[$q$دبلوم بعد الثانوي أو أعلى شهادة حاسب آلي (تقنية) والمتعلقة بالبرامج المكتبية$q$]::text[],$q$إدارة الوقت ، الاتصال الفعال، المهارات التقنية .$q$,'{}'::text[],16) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$registrar$q$,$q$مسجل معلومات$q$,null,array[$q$يرتبط بوكيل المدرسة لشؤون الطلاب$q$]::text[],$q$إدخال وحفظ واسترجاع جميع البيانات والمعلومات المتعلقة بالمدرسة عبر الأنظمة الحاسوبية المستخدمة$q$,array[$q$شهادة ثانوية + دبلوم في الحاسب الآلي$q$]::text[],null,'{}'::text[],17) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$guard$q$,$q$حارس المدرسة$q$,null,array[$q$يرتبط بوكيل الشؤون المدرسية$q$]::text[],$q$الحفاظ على مبنى المدرسة وموجوداته.$q$,array[$q$شهادة ابتدائية أو أعلى$q$]::text[],null,'{}'::text[],18) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$kg_service_staff$q$,$q$موظفة خدمات (مدارس رياض الأطفال)$q$,null,array[$q$ترتبط بوكيلة الشؤون المدرسية$q$]::text[],$q$الاهتمام بمرافق المدرسة وتقديم الخدمات العامة.$q$,array[$q$الثانوية العامة$q$]::text[],null,'{}'::text[],19) on conflict (code) do nothing;
insert into public.guide_jobs(code,title,subtitle,org_link,objective,min_qualifications,competencies,notes,sort_order) values ($q$service_worker$q$,$q$عامل خدمات$q$,null,array[$q$يرتبط بوكيل الشؤون المدرسية$q$]::text[],$q$الحفاظ على نظافة المدرسة وتقديم الخدمات العامة.$q$,array[$q$يجيد القراءة والكتابة$q$]::text[],null,'{}'::text[],20) on conflict (code) do nothing;
insert into public.guide_assignments(code,kind,title,full_title,org_link,objective,formation_rules,meeting_rules,notes,sort_order) values ($q$administrative_committee$q$,$q$committee$q$,$q$اللجنة الإدارية$q$,$q$مهام واختصاصات اللجنة الإدارية بالمدرسة$q$,'{}'::text[],$q$إقرار خطة المدرسة التشغيلية، ومتابعة سير العملية التربوية والتعليمية، وتشجيع أوجه الإبداع والتميّز المدرسي بما يعزز التحصيل الدراسي للطالب ويحقق رسالة المدرسة، ومناقشة التحديات التي تواجه المدرسة واتخاذ التوصيات اللازمة بشأنها، للارتقاء بمستوى التعليم والتعلم.$q$,array[$q$يصدر مدير المدرسة قرارًا بتشكيل اللجنة.$q$,$q$يختار مدير المدرسة المعلمين، ويكون من بينهم معلم خبير على الأقل، أو معلم متقدم على الأقل في حال عدم توفر المعلم الخبير، أو معلمون ممارسون في حال عدم توفر المعلمين الخبراء والمتقدمين.$q$]::text[],array[$q$تعقد اللجنة اجتماعاتها بدعوة من رئيسها مرة واحدة شهرياً، ولرئيس اللجنة أن يدعو لاجتماع طارئ عند الحاجة، على ألا تتسبب هذه الاجتماعات بإرباك/ تعطيل اليوم الدراسي.$q$,$q$لرئيس اللجنة دعوة من يراه من غير الأعضاء للمشاركة في مناقشة أحد الموضوعات في جدول أعمال اللجنة، وفق الضوابط المنظمة لذلك.$q$,$q$توثق اجتماعات اللجنة بمحاضر رسمية وتدون في سجل خاص متضمن المناقشات والتوصيات والقرارات.$q$]::text[],'{}'::text[],1) on conflict (code) do nothing;
insert into public.guide_assignments(code,kind,title,full_title,org_link,objective,formation_rules,meeting_rules,notes,sort_order) values ($q$student_guidance_committee$q$,$q$committee$q$,$q$لجنة التوجيه الطلابي$q$,$q$مهام واختصاصات لجنة التوجيه الطلابي$q$,'{}'::text[],$q$التخطيط لبرامج التوجيه الطلابي ومتابعة تنفيذها وتقويمها واقتراح البرامج التي تتناسب مع إمكانيات وحاجات المدرسة، والنظر في قضايا الطلاب.$q$,array[$q$يصدر مدير المدرسة قراراً بتشكيل اللجنة.$q$,$q$يشارك في اجتماع اللجنة وفقاً لمرئيات أعضاء اللجنة من يستدعي حضوره دون التصويت على قرارات اللجنة، مثل: معلم الصف، معلم المادة، معلم ذوي الإعاقة ، معلم الموهوبين، رائد النشاط، الطالب، ولي أمر الطالب.$q$]::text[],array[$q$تعقد اللجنة اجتماعاتها بشكل شهري ،ولرئيس اللجنة دعوة اللجنة إلى اجتماعات طارئة وفق الحاجة، على ألا تتسبب هذه الاجتماعات بإرباك/تعطيل اليوم الدراسي.$q$,$q$توثق اجتماعات اللجنة بمحاضر رسمية وتدون في سجل خاص متضمن المناقشات والتوصيات والقرارات.$q$]::text[],'{}'::text[],2) on conflict (code) do nothing;
insert into public.guide_assignments(code,kind,title,full_title,org_link,objective,formation_rules,meeting_rules,notes,sort_order) values ($q$academic_achievement_committee$q$,$q$committee$q$,$q$لجنة التحصيل الدراسي$q$,$q$مهام واختصاصات لجنة التحصيل الدراسي$q$,'{}'::text[],$q$ضمان تطبيق اختبارات التحصيل الدراسي والاختبارات بأنواعها (الوطنية، والمعتمدة من الوزارة)، بما يسهم في تجويد العمليات التربوية والتعليمية في المدرسة، والارتقاء بكفاءة الأداء التحصيلي ونواتج التعلم للمدرسة، وتدقيق واستخراج النتائج وفقًا للوائح والإجراءات والتعليمات المعتمدة.$q$,array[$q$يصدر مدير المدرسة قرارًا بتشكيل اللجنة.$q$,$q$يتم اختيار المعلمين من قبل مدير المدرسة.$q$]::text[],array[$q$تعقد اللجنة اجتماعاتها بشكل دوري في كل فصل دراسي بما لا يقل عن اجتماعين، ولرئيس اللجنة دعوة اللجنة إلى اجتماعات طارئة وفق الحاجة، على ألا تتسبب هذه الاجتماعات بإرباك/ تعطيل اليوم الدراسي.$q$,$q$توثق اجتماعات اللجنة بمحاضر رسمية وتدون في سجل خاص متضمن المناقشات والتوصيات والقرارات.$q$]::text[],'{}'::text[],3) on conflict (code) do nothing;
insert into public.guide_assignments(code,kind,title,full_title,org_link,objective,formation_rules,meeting_rules,notes,sort_order) values ($q$excellence_committee$q$,$q$committee$q$,$q$لجنة التميز$q$,$q$مهام واختصاصات لجنة التميز$q$,'{}'::text[],$q$إعداد الخطة التشغيلية للمدرسة، وتشجيع أفضل الممارسات بين منسوبيها لضمان التميز المؤسسي والتخصصي المدرسي بما يسهم في تجويد العمليات التربوية والتعليمية والتنظيمية في المدرسة، والارتقاء بكفاءة الأداء المؤسسي المدرسي.$q$,array[$q$يصدر مدير المدرسة قراراً بتشكيل اللجنة.$q$,$q$يتم اختيار معلمين خبراء من قبل مدير المدرسة ، أو معلمين متقدمين في حال عدم توفر الخبراء، أو معلمين ممارسين في حال عدم توفر المعلمين الخبراء والمتقدمين.$q$]::text[],array[$q$تعقد اللجنة اجتماعاتها مرة كل شهر وتسجل اجتماعاتها في محاضر يوقعها الأعضاء، ولرئيس اللجنة دعوة اللجنة إلى اجتماعات طارئة وفق الحاجة، على ألا تتسبب هذه الاجتماعات بإرباك/تعطيل اليوم الدراسي.$q$,$q$توثق اجتماعات اللجنة بمحاضر و تدون في سجل خاص متضمن التوصيات ومتابعة القرارات.$q$,$q$يتم اتخاذ التوصية في أي موضوع يطرح للنقاش من خلال التصويت بالأغلبية وعند تساوي الأصوات يغلب الطرف الذي فيه الرئيس.$q$]::text[],'{}'::text[],4) on conflict (code) do nothing;
insert into public.guide_assignments(code,kind,title,full_title,org_link,objective,formation_rules,meeting_rules,notes,sort_order) values ($q$school_fund_team$q$,$q$team$q$,$q$فريق الصندوق المدرسي$q$,$q$مهام واختصاصات فريق عمل الصندوق المدرسي (يرتبط باللجنة الإدارية) فريق العمل المؤقت الخاص ب «الصندوق المدرسي»$q$,array[$q$يرتبط باللجنة الإدارية$q$]::text[],$q$إدارة ومتابعة أعمال الصندوق المدرسي والعمل على تنمية موارده$q$,array[$q$يتم تكليف فريق العمل من قبل اللجنة الإدارية من أعضائها للإشراف على الصندوق المدرسي.$q$,$q$يتم الرفع بالتقارير الدورية للجنة الإدارية.$q$]::text[],array[$q$يعقد الفريق اجتماعاته مرّة واحدة على الأقل شهريًا، ولرئيس الفريق أن يدعو لاجتماع طارئ عند الحاجة، على ألا تتسبب هذه الاجتماعات بإرباك/تعطيل اليوم الدراسي.$q$,$q$توثق اجتماعات الفريق بمحاضر رسمية وتدون في سجل خاص متضمن المناقشات والتوصيات والقرارات.$q$]::text[],array[$q$فريق العمل المؤقت الخاص ب «الصندوق المدرسي»$q$]::text[],5) on conflict (code) do nothing;
insert into public.guide_assignments(code,kind,title,full_title,org_link,objective,formation_rules,meeting_rules,notes,sort_order) values ($q$safety_security_facilities_team$q$,$q$team$q$,$q$فريق الأمن والسلامة والمرافق$q$,$q$مهام واختصاصات فريق عمل الأمن والسلامة والمرافق (يرتبط باللجنة الإدارية) فريق العمل المؤقت الخاص ب «الأمن والسلامة والمرافق»$q$,array[$q$يرتبط باللجنة الإدارية$q$]::text[],$q$إدارة ومتابعة عمليات الأمن والسلامة واستمرارية الأعمال وعمليات الإخلاء.$q$,array[$q$قبل بداية كل فصل دراسي يتم تكليف فريق العمل من قبل اللجنة الإدارية من أعضائها للإشراف على الأمن والسلامة والمرافق.$q$,$q$الالتزام بالأدلة والقواعد المتعلقة بعمليات الأمن والسلامة والإخلاء.$q$,$q$يتم الرفع بالتقارير الدورية للجنة الإدارية.$q$]::text[],array[$q$يعقد الفريق اجتماعاته مرة واحدة على الأقل شهريًا، ولرئيس الفريق أن يدعو لاجتماع طارئ عند الحاجة، على ألا تسبب هذه الاجتماعات بإرباك/تعطيل اليوم الدراسي.$q$,$q$توثق اجتماعات الفريق وعمليات المسح الميداني بمحاضر رسمية وتدون في سجل خاص متضمن المناقشات والتوصيات والقرارات.$q$]::text[],array[$q$فريق العمل المؤقت الخاص ب «الأمن والسلامة والمرافق»$q$]::text[],6) on conflict (code) do nothing;
insert into public.guide_assignments(code,kind,title,full_title,org_link,objective,formation_rules,meeting_rules,notes,sort_order) values ($q$disability_team$q$,$q$team$q$,$q$فريق عمل ذوي الإعاقة$q$,$q$مهام واختصاصات فريق عمل الطلاب ذوي الإعاقة (يرتبط باللجنة الإدارية) في المدارس التي تتضمن برامجاً للطلاب ذوي الإعاقة$q$,array[$q$يرتبط باللجنة الإدارية$q$]::text[],$q$تقديم خدمات تعليم الطلاب ذوي الإعاقة ومتابعة شؤونهم في المدرسة.$q$,array[$q$يتم تشكيل الفريق في المدارس التي يوجد بها برامج للطلاب ذوي الإعاقة قبل بداية كل فصل دراسي.$q$,$q$يتم تكليف فريق العمل من قبل اللجنة الإدارية.$q$,$q$الالتزام باللوائح والقواعد التنظيمية المتعلقة بالطلاب ذوي الإعاقة .$q$,$q$لرئيس الفريق الاستعانة بمن تدعو الحاجة له.$q$]::text[],array[$q$يعقد الفريق اجتماعاته مرة واحدة على الأقل شهريًا، ولرئيس الفريق أن يدعو لاجتماع طارئ عند الحاجة.$q$,$q$توثق اجتماعات الفريق بمحاضر رسمية وتدون في سجل خاص متضمن المناقشات والتوصيات والقرارات.$q$,$q$استخدام النماذج المعتمدة في ذلك في الأدلة ذات العلاقة في عمليات الفريق.$q$]::text[],array[$q$في المدارس التي تتضمن برامجاً للطلاب ذوي الإعاقة$q$]::text[],7) on conflict (code) do nothing;
insert into public.guide_assignments(code,kind,title,full_title,org_link,objective,formation_rules,meeting_rules,notes,sort_order) values ($q$school$q$,$q$org_unit$q$,$q$المدرسة$q$,$q$مهام واختصاصات المدرسة$q$,array[$q$ترتبط المدرسة (الابتدائية / المتوسطة / الثانوية) حسب مرحلتها، ب (مدير المرحلة) المعني في قسم الإدارة المدرسية بإدارة التعليم العامة.$q$,$q$ترتبط مدرسة رياض الأطفال بمدير قسم رياض الأطفال في إدارة التعليم العامة.$q$,$q$ترتبط الحضانة بمدير قسم الحضانة في إدارة التعليم العامة.$q$,$q$ترتبط مدرسة التعليم المستمر بمدير قسم التعليم المستمر في إدارة التعليم العامة.$q$,$q$ترتبط مدرسة الطلاب ذوي الإعاقة (باستثناء مدارس الدمج) بمدير قسم ذوي الإعاقة بإدارة التعليم العامة (باستثناء المراكز أو المعاهد أو ما في حكمها المختصة بذوي الإعاقة والتي صدر بها تنظيم مستقل معتمد من صاحب الصلاحية).$q$,$q$ترتبط مدرسة الموهوبين بمدير قسم الموهوبين بإدارة التعليم العامة.$q$]::text[],$q$بناء وتعزيز القيم الإسلامية والوطنية والفكرية وتنمية المعارف والمهارات لإنشاء جيل واعٍ قادر على مواجهة الحياة.$q$,'{}'::text[],'{}'::text[],'{}'::text[],8) on conflict (code) do nothing;
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$principal$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,2,$q$قيادة عملية إعداد خطة المدرسة ومتابعة تنفيذها بعد اعتمادها، بما يحقق الاستفادة المثلى من الخبرات والمواهب والموارد في المدرسة.$q$,$q$قيادة عملية إعداد خطة المدرسة ومتابعة تنفيذها بعد اعتمادها، بما يحقق الاستفادة المثلى من الخبرات والمواهب والموارد في المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,3,$q$الحفاظ على كفاءة وفعالية الأداء داخل المدرسة، واستثمار الوقت والموارد لتحسين نواتج التعلم وجودة الخدمة المقدمة، وتحقيق السلامة المدرسية.$q$,$q$الحفاظ على كفاءة وفعالية الأداء داخل المدرسة، واستثمار الوقت والموارد لتحسين نواتج التعلم وجودة الخدمة المقدمة، وتحقيق السلامة المدرسية.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,4,$q$الإشراف على تنفيذ برامج الوعي الفكري وخططه وقواعده المعتمدة، وتعزيز الوسطية والاعتدال الفكري والتأكد من سلامة البيئة التعليمية من الفكر المتطرف والظواهر السلبية.$q$,$q$الإشراف على تنفيذ برامج الوعي الفكري وخططه وقواعده المعتمدة، وتعزيز الوسطية والاعتدال الفكري والتأكد من سلامة البيئة التعليمية من الفكر المتطرف والظواهر السلبية.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,5,$q$حماية مجتمع المدرسة من كل ما يؤدي إلى المخالفات الفكرية أو ضعف الالتزام الوطني بما لا يتماشى مع الوسطية والاعتدال الفكري.$q$,$q$حماية مجتمع المدرسة من كل ما يؤدي إلى المخالفات الفكرية أو ضعف الالتزام الوطني بما لا يتماشى مع الوسطية والاعتدال الفكري.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,6,$q$متابعة حالات المخالفات أو الاشتباه في المخالفات للسياسات العامة، والالتزام الفكري والوطني.$q$,$q$متابعة حالات المخالفات أو الاشتباه في المخالفات للسياسات العامة، والالتزام الفكري والوطني.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,7,$q$رصد حالات المخالفات الفكرية، أو الاشتباه في وجود مخالفات للسياسات العامة، والالتزام الفكري والوطني بما ينافي الوسطية والاعتدال الفكري في المدارس، ومعالجتها بنا ء على القواعد والإجراءات المعتمدة.$q$,$q$رصد حالات المخالفات الفكرية، أو الاشتباه في وجود مخالفات للسياسات العامة، والالتزام الفكري والوطني بما ينافي الوسطية والاعتدال الفكري في المدارس، ومعالجتها بنا ء على القواعد والإجراءات المعتمدة.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,8,$q$الرفع الفوري لمدير عام التعليم / صاحب الصلاحية في حالات المخالفات الفكرية أو المخالفات للسياسات العامة التي لم تتم معالجتها.$q$,$q$الرفع الفوري لمدير عام التعليم / صاحب الصلاحية في حالات المخالفات الفكرية أو المخالفات للسياسات العامة التي لم تتم معالجتها.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,9,$q$تزويد إدارة التعليم العامة بتقارير دورية عن حالة الوعي الفكري، وفقاً للقواعد والإجراءات المعتمدة.$q$,$q$تزويد إدارة التعليم العامة بتقارير دورية عن حالة الوعي الفكري، وفقاً للقواعد والإجراءات المعتمدة.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,10,$q$تحديد الاحتياج من الكوادر المهنية والمفاضلة بينهم ووضع الأهداف الفردية ومؤشرات الأداء الرئيسية لكل من منسوبي المدرسة، ومناقشتها معهم.$q$,$q$تحديد الاحتياج من الكوادر المهنية والمفاضلة بينهم ووضع الأهداف الفردية ومؤشرات الأداء الرئيسية لكل من منسوبي المدرسة، ومناقشتها معهم.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,11,$q$توزيع المهام والواجبات على منسوبي المدرسة وإصدار التكاليف اللازمة لإنجاز أعمالهم ومناقشتها لتوضيح مضامينها والعمل بموجبها.$q$,$q$توزيع المهام والواجبات على منسوبي المدرسة وإصدار التكاليف اللازمة لإنجاز أعمالهم ومناقشتها لتوضيح مضامينها والعمل بموجبها.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,12,$q$مراجعة وتقويم أداء منسوبي المدرسة بشكل دوري، ومناقشتهم وتقديم تغذية راجعة بناءة لهم، واعتماد التقويم النهائي لأدائهم، والتأكد من أنها تتماشى مع اللوائح والتعليمات.$q$,$q$مراجعة وتقويم أداء منسوبي المدرسة بشكل دوري، ومناقشتهم وتقديم تغذية راجعة بناءة لهم، واعتماد التقويم النهائي لأدائهم، والتأكد من أنها تتماشى مع اللوائح والتعليمات.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,13,$q$توفير التوجيه المناسب لتحسين أداء منسوبي المدرسة، وتحديد الاحتياجات التدريبية اللازمة لهم ورفعها لإدارة التعليم العامة.$q$,$q$توفير التوجيه المناسب لتحسين أداء منسوبي المدرسة، وتحديد الاحتياجات التدريبية اللازمة لهم ورفعها لإدارة التعليم العامة.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,14,$q$تمكين الموظفين وإشراكهم في اعداد الخطة التشغيلية وتحسين العمليات داخل المدرسة بما يعزز لديهم شعور الانتماء للمدرسة.$q$,$q$تمكين الموظفين وإشراكهم في اعداد الخطة التشغيلية وتحسين العمليات داخل المدرسة بما يعزز لديهم شعور الانتماء للمدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,15,$q$التأكد من وجود نظام مناسب لإدارة المدرسة ولمراجعة وتحسين العمليات الرئيسية (نمط إدارة للعمل يتناسب مع وضع المدرسة).$q$,$q$التأكد من وجود نظام مناسب لإدارة المدرسة ولمراجعة وتحسين العمليات الرئيسية (نمط إدارة للعمل يتناسب مع وضع المدرسة).$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,16,$q$العمل مع وكلاء المدرسة لرسم الخطط التطويرية لأداء الموظفين.$q$,$q$العمل مع وكلاء المدرسة لرسم الخطط التطويرية لأداء الموظفين.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,17,$q$تشجيع منسوبي المدرسة على الاستفادة من الخبرات المكتسبة والتطوير في تحسين الأداء المدرسي.$q$,$q$تشجيع منسوبي المدرسة على الاستفادة من الخبرات المكتسبة والتطوير في تحسين الأداء المدرسي.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,18,$q$الإشراف على تهيئة بيئة تعليمية محفزة داخل المدرسة، ورفع الروح المعنوية بين المعلمين والطلاب وأولياء الأمور.$q$,$q$الإشراف على تهيئة بيئة تعليمية محفزة داخل المدرسة، ورفع الروح المعنوية بين المعلمين والطلاب وأولياء الأمور.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,19,$q$مراجعة أداء مبادرات المدرسة وأهدافها وإجراء حوارات حول الأداء مع منسوبي المدرسة مبني على تقارير الأداء للتأكد من تلبيتها لأهداف الأداء.$q$,$q$مراجعة أداء مبادرات المدرسة وأهدافها وإجراء حوارات حول الأداء مع منسوبي المدرسة مبني على تقارير الأداء للتأكد من تلبيتها لأهداف الأداء.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,20,$q$متابعة التحصيل الدراسي وتقدم الطلاب داخل المدرسة، والتأكد من مدى فعالية أساليب التدريس واتخاذ الإجراءات المناسبة حيالها.$q$,$q$متابعة التحصيل الدراسي وتقدم الطلاب داخل المدرسة، والتأكد من مدى فعالية أساليب التدريس واتخاذ الإجراءات المناسبة حيالها.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,21,$q$الإشراف على عمليات التدريس واستخدام استراتيجيات التعلم داخل الفصول الدراسية وفق الجدول الزمني المخصص لها وبما يضمن تحقيق أهداف المقررات الدراسية.$q$,$q$الإشراف على عمليات التدريس واستخدام استراتيجيات التعلم داخل الفصول الدراسية وفق الجدول الزمني المخصص لها وبما يضمن تحقيق أهداف المقررات الدراسية.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,22,$q$توفير بيئة تعليمية آمنة وجاذبة، وذلك بتوفير الدعم المستمر للاحترام والانضباط ورفع الروح المعنوية بين المعلمين والطلاب وأولياءالأمور.$q$,$q$توفير بيئة تعليمية آمنة وجاذبة، وذلك بتوفير الدعم المستمر للاحترام والانضباط ورفع الروح المعنوية بين المعلمين والطلاب وأولياءالأمور.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,23,$q$إدارة عمليات الانضباط داخل المدرسة ومتابعة حضور المعلمين والقيام بالترتيبات الملائمة لمعالجة العجز الطارئ من داخل المدرسة وفق التعليمات المعتمدة.$q$,$q$إدارة عمليات الانضباط داخل المدرسة ومتابعة حضور المعلمين والقيام بالترتيبات الملائمة لمعالجة العجز الطارئ من داخل المدرسة وفق التعليمات المعتمدة.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,24,$q$متابعة أداء أعمال الهيئة التعليمية والإدارية للمدرسة وذلك من خلال الزيارات الدورية لهم والاطلاع على أعمالهم وأنشطتهم ومشاركاتهم.$q$,$q$متابعة أداء أعمال الهيئة التعليمية والإدارية للمدرسة وذلك من خلال الزيارات الدورية لهم والاطلاع على أعمالهم وأنشطتهم ومشاركاتهم.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,25,$q$الإشراف على مجالس أولياء الأمور وتفعيل دورها في المدرسة، واعتماد التوصيات الصادرة عن لجان المدرسة، وفق اللوائح والتعليمات المنظمة.$q$,$q$الإشراف على مجالس أولياء الأمور وتفعيل دورها في المدرسة، واعتماد التوصيات الصادرة عن لجان المدرسة، وفق اللوائح والتعليمات المنظمة.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,26,$q$متابعة التزام المدرسة بالسياسات والإجراءات التي تم وضعها مركزيًا من قبل الوزارة، ومتابعة اللوائح والأنطمة والتعاميم الهامة الصادرة من جهات الاختصاص وإطلاع جميع منسوبي المدرسة عليها ومناقشتها لتوضيح مضامينها والعمل بموجبها.$q$,$q$متابعة التزام المدرسة بالسياسات والإجراءات التي تم وضعها مركزيًا من قبل الوزارة، ومتابعة اللوائح والأنطمة والتعاميم الهامة الصادرة من جهات الاختصاص وإطلاع جميع منسوبي المدرسة عليها ومناقشتها لتوضيح مضامينها والعمل بموجبها.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,27,$q$تفعيل التعليم الإلكتروني وتشجيعه بقنواته المختلفة، وتطبيق الممارسات الإدارية والتعليمية وفق التعاميم المنظمة ، لضمان جودة العملية التعليمية، ومتابعة التطبيقات في منصات التعليم الإلكتروني المعتمدة، وتعزيز الاستخدام الأمثل لمصادر التعلم، والمعدات والتقنية لدعم أنظمة المدرسة.$q$,$q$تفعيل التعليم الإلكتروني وتشجيعه بقنواته المختلفة، وتطبيق الممارسات الإدارية والتعليمية وفق التعاميم المنظمة ، لضمان جودة العملية التعليمية، ومتابعة التطبيقات في منصات التعليم الإلكتروني المعتمدة، وتعزيز الاستخدام الأمثل لمصادر التعلم، والمعدات والتقنية لدعم أنظمة المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,28,$q$إدارة ميزانية المدرسة على النحو الأمثل لتحقيق أهداف المدرسة.$q$,$q$إدارة ميزانية المدرسة على النحو الأمثل لتحقيق أهداف المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,29,$q$تحليل واستخدام المعلومات والبيانات لدعم العمليات المدرسية وخطط العمل.$q$,$q$تحليل واستخدام المعلومات والبيانات لدعم العمليات المدرسية وخطط العمل.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,30,$q$الالتزام بالسياسات والضوابط والمعايير المعتمدة والمنظمة للنشاط الإعلامي للمدرسة وحوكمة استخدام حسابات شبكات التواصل الاجتماعي لوزارة التعليم.$q$,$q$الالتزام بالسياسات والضوابط والمعايير المعتمدة والمنظمة للنشاط الإعلامي للمدرسة وحوكمة استخدام حسابات شبكات التواصل الاجتماعي لوزارة التعليم.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,31,$q$حضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته.$q$,$q$حضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,32,$q$حضور دروس المعلمين وفق جدول يعتمده. ويقوم بالتدريس لعدد حصص مادة التخصص . وبما لا يتجاوز عن ٨ حصص.$q$,$q$حضور دروس المعلمين وفق جدول يعتمده. ويقوم بالتدريس لعدد حصص مادة التخصص . وبما لا يتجاوز عن ٨ حصص.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,33,$q$تفعيل مجالس و لجان المدرسة و فرق العمل و الإشراف عليها و ممارسة الصلاحيات المعتمدة و متابعة تنفيذها.$q$,$q$تفعيل مجالس و لجان المدرسة و فرق العمل و الإشراف عليها و ممارسة الصلاحيات المعتمدة و متابعة تنفيذها.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,34,$q$الإشراف على تهيئة و تنظيم و تجهيز مرافق المدرسة قبل و أثناء الدراسة في المواعيد المحددة .$q$,$q$الإشراف على تهيئة و تنظيم و تجهيز مرافق المدرسة قبل و أثناء الدراسة في المواعيد المحددة .$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,35,$q$التواصل الفعّال والتنسيق و التعاون مع مقدمي خدمات دعم التميز المدرسي وغيرهم ممن تقتضي طبيعة عملهم زيارة المدرسة للحصول على أفضل خدمة ممكنة .$q$,$q$التواصل الفعّال والتنسيق و التعاون مع مقدمي خدمات دعم التميز المدرسي وغيرهم ممن تقتضي طبيعة عملهم زيارة المدرسة للحصول على أفضل خدمة ممكنة .$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,36,$q$إعداد تقييم أداء مرؤوسيه المباشرين ومناقشة الأهداف معهم وتحديد مؤشرات الأداء الرئيسية لهم وإعطاؤهم تغذية راجعة بناءة، ورفعها لمدير القسم الذي يرتبط به للاعتماد وفق الحوكمة المعتمدة لذلك.$q$,$q$إعداد تقييم أداء مرؤوسيه المباشرين ومناقشة الأهداف معهم وتحديد مؤشرات الأداء الرئيسية لهم وإعطاؤهم تغذية راجعة بناءة، ورفعها لمدير القسم الذي يرتبط به للاعتماد وفق الحوكمة المعتمدة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$principal$q$),null,37,$q$القيام بأية مهام يكلف بها من المسؤول المباشر وتتناسب مع مهامه/مؤهلاته.$q$,$q$القيام بأية مهام يكلف بها من المسؤول المباشر وتتناسب مع مهامه/مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,2,$q$التأكد من مطابقة أهداف المدرسة مع أهداف العملية التعليمية وشرح هذه الأهداف لجميع المعلمين.$q$,$q$التأكد من مطابقة أهداف المدرسة مع أهداف العملية التعليمية وشرح هذه الأهداف لجميع المعلمين.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,3,$q$إعداد تقييم أداء المعلمين ومناقشة الأهداف التعليمية للمواد الدراسية لكل معلم وتحديد مؤشرات الأداء الرئيسية له وإعطاء تغذية راجعة بناءة له بالتنسيق مع المعلم الخبير (إن وجد) للمادة مع تقديم الدعم والتدريب لتحسين الأداء متى ما تطلب الأمر.$q$,$q$إعداد تقييم أداء المعلمين ومناقشة الأهداف التعليمية للمواد الدراسية لكل معلم وتحديد مؤشرات الأداء الرئيسية له وإعطاء تغذية راجعة بناءة له بالتنسيق مع المعلم الخبير (إن وجد) للمادة مع تقديم الدعم والتدريب لتحسين الأداء متى ما تطلب الأمر.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,4,$q$تحليل مستوى التحصيل لدى الطلاب ومتابعة أدائهم ومدى تطور مستوى تحصيلهم الدراسي. ومتابعة نتائجهم بشكل دوري، وعرض الحالات التي تتطلب إضافة حصص علاجية أو إثرائية على لجنة التوجيه الطلابي.$q$,$q$تحليل مستوى التحصيل لدى الطلاب ومتابعة أدائهم ومدى تطور مستوى تحصيلهم الدراسي. ومتابعة نتائجهم بشكل دوري، وعرض الحالات التي تتطلب إضافة حصص علاجية أو إثرائية على لجنة التوجيه الطلابي.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,5,$q$توفير التوجيه المناسب لتحسين أداء مرؤوسيه، وتحديد الاحتياجات التدريبية اللازمة لهم ورفعها لمدير المدرسة.$q$,$q$توفير التوجيه المناسب لتحسين أداء مرؤوسيه، وتحديد الاحتياجات التدريبية اللازمة لهم ورفعها لمدير المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,6,$q$إعداد الجداول المدرسية وتوزيع الأنصبة وفق التخصصات.$q$,$q$إعداد الجداول المدرسية وتوزيع الأنصبة وفق التخصصات.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,7,$q$المشاركة في تصنيف المعلمين والاستفادة من خبراتهم المهنية والتعليمية.$q$,$q$المشاركة في تصنيف المعلمين والاستفادة من خبراتهم المهنية والتعليمية.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,8,$q$المشاركة في قيادة وإدارة تنفيذ البرامج والأنشطة التعليمية والتربوية في المدرسة.$q$,$q$المشاركة في قيادة وإدارة تنفيذ البرامج والأنشطة التعليمية والتربوية في المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,9,$q$مراجعة ممارسات العملية التعليمية ورصد الصعوبات ومتابعة الظواهر المتعلقة بالشؤون التعليمية التي تظهر في المدرسة، والعناية بها ومتابعة معالجتها، وتحليل البيئة الداخلية والخارجية من أجل تطوير خطط العمل المتعلقة بالشؤون التعليمية في المدرسة حتى تلبي احتياجاتها الحالية والمستقبلية.$q$,$q$مراجعة ممارسات العملية التعليمية ورصد الصعوبات ومتابعة الظواهر المتعلقة بالشؤون التعليمية التي تظهر في المدرسة، والعناية بها ومتابعة معالجتها، وتحليل البيئة الداخلية والخارجية من أجل تطوير خطط العمل المتعلقة بالشؤون التعليمية في المدرسة حتى تلبي احتياجاتها الحالية والمستقبلية.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,10,$q$الإشراف على رصد التقدم في إنجاز الأعمال المكلف بها المعلمين وتحليل النتائج.$q$,$q$الإشراف على رصد التقدم في إنجاز الأعمال المكلف بها المعلمين وتحليل النتائج.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,11,$q$تقديم الدعم والمساندة والخبرة والمعرفة والرفع لمدير المدرسة ببرامج تدريب المعلمين لمساعدتهم على تحسين مستوى أدائهم.$q$,$q$تقديم الدعم والمساندة والخبرة والمعرفة والرفع لمدير المدرسة ببرامج تدريب المعلمين لمساعدتهم على تحسين مستوى أدائهم.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,12,$q$التطوير المهني المستمر لاكتساب خبرة، ومهارات إدارية وقيادية.$q$,$q$التطوير المهني المستمر لاكتساب خبرة، ومهارات إدارية وقيادية.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,13,$q$متابعة وتحفيز المعلمين لاستخدام أدوات التقييم المتنوعة والاستفادة من المعلومات في تحسين مستوى الطلاب وتفعيل التعليم الإلكتروني وتشجيعه بقنواته المختلفة، وتطبيق الممارسات الإدارية والتعليمية بما يتناسب معه وفق التعاميم والضوابط المنظمة لذلك، لضمان جودة العملية التعليمية، وتعزيز الاستخدام الأمثل لمصادر التعلم والمعدات والتقنية لدعم أنظمة المدرسة.$q$,$q$متابعة وتحفيز المعلمين لاستخدام أدوات التقييم المتنوعة والاستفادة من المعلومات في تحسين مستوى الطلاب وتفعيل التعليم الإلكتروني وتشجيعه بقنواته المختلفة، وتطبيق الممارسات الإدارية والتعليمية بما يتناسب معه وفق التعاميم والضوابط المنظمة لذلك، لضمان جودة العملية التعليمية، وتعزيز الاستخدام الأمثل لمصادر التعلم والمعدات والتقنية لدعم أنظمة المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,14,$q$تقديم الاقتراح الأمثل لجميع متطلبات التدريس (أجهزة العرض، النظام السمعي/المرئي-الفيديو ...) والاحتياجات الأساسية ذات الصلة (مواد مختبرية، معدات، ...الخ) وذلك لحماية جميع الممتلكات داخل المدرسة والتأكد من استخدامها بأفضل طريقة تحقق نتائج التعلم المستهدفة.$q$,$q$تقديم الاقتراح الأمثل لجميع متطلبات التدريس (أجهزة العرض، النظام السمعي/المرئي-الفيديو ...) والاحتياجات الأساسية ذات الصلة (مواد مختبرية، معدات، ...الخ) وذلك لحماية جميع الممتلكات داخل المدرسة والتأكد من استخدامها بأفضل طريقة تحقق نتائج التعلم المستهدفة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,15,$q$متابعة تقييم أداء الطلاب وتطور مستوى تحصيلهم الدراسي، والإشراف الكامل على الإجراءات المتعلقة بذلك منذ بدايتها وحتى انتهائها.$q$,$q$متابعة تقييم أداء الطلاب وتطور مستوى تحصيلهم الدراسي، والإشراف الكامل على الإجراءات المتعلقة بذلك منذ بدايتها وحتى انتهائها.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,16,$q$تخطيط وإدارة الموارد المادية والتعليمية المخصصة للبرامج التعليمية.$q$,$q$تخطيط وإدارة الموارد المادية والتعليمية المخصصة للبرامج التعليمية.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,17,$q$تسهيل التواصل مع المعلمين من خلال قنوات تواصل تتسم بالشفافية.$q$,$q$تسهيل التواصل مع المعلمين من خلال قنوات تواصل تتسم بالشفافية.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,18,$q$متابعة مستوى تقدم الطلاب وأدائهم مع معلمي الصف فيما يتعلق بالأهداف المحددة لكل مادة دراسية، والتأكد من الالتزام بإجراءات المتابعة واتخاذ الإجراءات المناسبة عند الضرورة.$q$,$q$متابعة مستوى تقدم الطلاب وأدائهم مع معلمي الصف فيما يتعلق بالأهداف المحددة لكل مادة دراسية، والتأكد من الالتزام بإجراءات المتابعة واتخاذ الإجراءات المناسبة عند الضرورة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,19,$q$إعداد التوقيت الزمني لفترات البرنامج اليومي (خاص برياض الأطفال).$q$,$q$إعداد التوقيت الزمني لفترات البرنامج اليومي (خاص برياض الأطفال).$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,20,$q$إعداد جدول الاشراف والمناوبة اليومية ومتابعة تنفيذه بعد اعتماده من مدير المدرسة.$q$,$q$إعداد جدول الاشراف والمناوبة اليومية ومتابعة تنفيذه بعد اعتماده من مدير المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,21,$q$حضور دروس المعلمين وفق جدول يعتمده مدير المدرسة و يقوم بالتدريس لعدد حصص لمادة التخصص بما لا يتجاوز ٨ حصص.$q$,$q$حضور دروس المعلمين وفق جدول يعتمده مدير المدرسة و يقوم بالتدريس لعدد حصص لمادة التخصص بما لا يتجاوز ٨ حصص.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,22,$q$تفعيل مجالس ولجان المدرسة وفرق العمل والإشراف عليها وممارسة الصلاحيات المعتمدة ومتابعة تنفيذها.$q$,$q$تفعيل مجالس ولجان المدرسة وفرق العمل والإشراف عليها وممارسة الصلاحيات المعتمدة ومتابعة تنفيذها.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,23,$q$الإشراف على تهيئة وتنظيم وتجهيز مرافق المدرسة قبل وأثناء الدراسة في المواعيد المحددة .$q$,$q$الإشراف على تهيئة وتنظيم وتجهيز مرافق المدرسة قبل وأثناء الدراسة في المواعيد المحددة .$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,24,$q$التنسيق والتعاون مع مقدمي خدمات دعم التميز المدرسي وغيرهم ممن تقتضي طبيعة عملهم زيارة المدرسة.$q$,$q$التنسيق والتعاون مع مقدمي خدمات دعم التميز المدرسي وغيرهم ممن تقتضي طبيعة عملهم زيارة المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,25,$q$حضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته.$q$,$q$حضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_academic$q$),null,26,$q$القيام بأي مهام يكلف بها من قبل مدير المدرسة وتتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من قبل مدير المدرسة وتتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,2,$q$الإشراف على البرامج المتعلقة بالطلاب وتقديم الخدمات المناسبة لهم.$q$,$q$الإشراف على البرامج المتعلقة بالطلاب وتقديم الخدمات المناسبة لهم.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,3,$q$إعداد تقييم أداء الموظفين الذين يشرف عليهم وتحديد مؤشرات الأداء الرئيسية لهم وإعطاء تغذية راجعة بناءة لهم .$q$,$q$إعداد تقييم أداء الموظفين الذين يشرف عليهم وتحديد مؤشرات الأداء الرئيسية لهم وإعطاء تغذية راجعة بناءة لهم .$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,4,$q$توفير التوجيه المناسب لتحسين أداء مرؤوسيه، وتحديد الاحتياجات التدريبية اللازمة لهم ورفعها لمدير المدرسة .$q$,$q$توفير التوجيه المناسب لتحسين أداء مرؤوسيه، وتحديد الاحتياجات التدريبية اللازمة لهم ورفعها لمدير المدرسة .$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,5,$q$المساهمة في إنشاء قنوات تواصل تتسم بالشفافية مع أولياء أمور الطلاب.$q$,$q$المساهمة في إنشاء قنوات تواصل تتسم بالشفافية مع أولياء أمور الطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,6,$q$الإشراف الكامل على الإجراءات المتعلقة بالقبول والتسجيل للطلاب منذ بدايتها وحتى انتهائها. والتأكد من أن تنفيذها يتم بطريقة فعالة، ويُتبع فيها جميع الضوابط والمعايير المعتمدة لها وفق الأنظمة واللوائح المنظمة لذلك لمختلف الفئات الطلابية المستهدفة.$q$,$q$الإشراف الكامل على الإجراءات المتعلقة بالقبول والتسجيل للطلاب منذ بدايتها وحتى انتهائها. والتأكد من أن تنفيذها يتم بطريقة فعالة، ويُتبع فيها جميع الضوابط والمعايير المعتمدة لها وفق الأنظمة واللوائح المنظمة لذلك لمختلف الفئات الطلابية المستهدفة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,7,$q$متابعة تطبيق الخطط الدراسية لجميع الطلاب وفق حالاتهم وتخصصاتهم، بما في ذلك متابعة تنفيذ حصص النشاط عبر منصات التعليم الإلكتروني والتعليم عن بعد المعتمدة في الوزارة.$q$,$q$متابعة تطبيق الخطط الدراسية لجميع الطلاب وفق حالاتهم وتخصصاتهم، بما في ذلك متابعة تنفيذ حصص النشاط عبر منصات التعليم الإلكتروني والتعليم عن بعد المعتمدة في الوزارة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,8,$q$التأكد من تنظيم الأنشطة الطلابية بما يتماشى مع محتوى البرنامج المقدم وبما يتماشى مع أفضل الممارسات التطبيقية لها، والإشراف على تطبيقها.$q$,$q$التأكد من تنظيم الأنشطة الطلابية بما يتماشى مع محتوى البرنامج المقدم وبما يتماشى مع أفضل الممارسات التطبيقية لها، والإشراف على تطبيقها.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,9,$q$تزويد الطلاب بالمعلومات والإشراف على تطوير برامج التوجيه لتهيئة الطلاب وتوجيههم فيما يتعلق باختيار (الجامعة / وسوق العمل) بالتعاون مع معلميهم / والهيئة التعليمية وأولياء الأمور.$q$,$q$تزويد الطلاب بالمعلومات والإشراف على تطوير برامج التوجيه لتهيئة الطلاب وتوجيههم فيما يتعلق باختيار (الجامعة / وسوق العمل) بالتعاون مع معلميهم / والهيئة التعليمية وأولياء الأمور.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,10,$q$الإشراف الكامل على الإجراءات المتعلقة بالتوجيه الطلابي وفاعليته في القيام بدراسات الحالة للطلاب وتقديم الخدمات لهم، وإدارة الحالات المعقدة والحرجة منها إذا تطلب الأمر ذلك.$q$,$q$الإشراف الكامل على الإجراءات المتعلقة بالتوجيه الطلابي وفاعليته في القيام بدراسات الحالة للطلاب وتقديم الخدمات لهم، وإدارة الحالات المعقدة والحرجة منها إذا تطلب الأمر ذلك.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,11,$q$إعداد الشراكات مع القطاعين الحكومي والخاص لدعم أو رعاية برامج المدرسة بما ينسجم مع الأهداف التربوية، وفق الأنظمة واللوائح والتعليمات المنظمة لذلك، والعرض على لجنة التوجيه الطلابي.$q$,$q$إعداد الشراكات مع القطاعين الحكومي والخاص لدعم أو رعاية برامج المدرسة بما ينسجم مع الأهداف التربوية، وفق الأنظمة واللوائح والتعليمات المنظمة لذلك، والعرض على لجنة التوجيه الطلابي.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,12,$q$حضور دروس المعلمين وفق جدول يعتمده مدير المدرسة ويقوم بالتدريس لعدد حصص مادة التخصص وبما لا يتجاوز 8 حصص.$q$,$q$حضور دروس المعلمين وفق جدول يعتمده مدير المدرسة ويقوم بالتدريس لعدد حصص مادة التخصص وبما لا يتجاوز 8 حصص.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,13,$q$المشاركة في إجراء تحليل البيانات والاستفادة من نتائج التعليم للطلاب في البرامج المقدمة لهم.$q$,$q$المشاركة في إجراء تحليل البيانات والاستفادة من نتائج التعليم للطلاب في البرامج المقدمة لهم.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,14,$q$متابعة عمليات حضور وغياب الطلاب في المدرسة، و متابعة سلوكهم والتأكد من تطبيق الأنظمة واللوائح المنظمة لذلك، والتواصل مع أولياء أمورهم فيما يتعلق بهذا الخصوص.$q$,$q$متابعة عمليات حضور وغياب الطلاب في المدرسة، و متابعة سلوكهم والتأكد من تطبيق الأنظمة واللوائح المنظمة لذلك، والتواصل مع أولياء أمورهم فيما يتعلق بهذا الخصوص.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,15,$q$اعتماد توزيع المعلمين على برامج النشاط غير الصفي بالتنسيق مع رائد النشاط ومتابعة تنفيذ خطط وبرامج أنشطة الطلاب غير الصفية.$q$,$q$اعتماد توزيع المعلمين على برامج النشاط غير الصفي بالتنسيق مع رائد النشاط ومتابعة تنفيذ خطط وبرامج أنشطة الطلاب غير الصفية.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,16,$q$الإشراف على رصد الدرجات/المهارات على النظام الحاسوبي المعتمد ومتابعة إصدارها وتوزيعها على الطلاب.$q$,$q$الإشراف على رصد الدرجات/المهارات على النظام الحاسوبي المعتمد ومتابعة إصدارها وتوزيعها على الطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,17,$q$إعداد مجالس أولياء الأمور ومتابعة تفعيلها في المدرسة، بالتنسيق مع الموجه الطلابي ورائد النشاط.$q$,$q$إعداد مجالس أولياء الأمور ومتابعة تفعيلها في المدرسة، بالتنسيق مع الموجه الطلابي ورائد النشاط.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,18,$q$الإشراف على جميع العمليات المتعلقة بالسجلات والملفات الخاصة بالطلاب ومتابعة تحديثها وتنظيمها وحفظها واكتمالها في برنامج نور أو غيره من البرامج التي تعتمدها الوزارة.$q$,$q$الإشراف على جميع العمليات المتعلقة بالسجلات والملفات الخاصة بالطلاب ومتابعة تحديثها وتنظيمها وحفظها واكتمالها في برنامج نور أو غيره من البرامج التي تعتمدها الوزارة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,19,$q$حضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته.$q$,$q$حضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_students$q$),null,20,$q$القيام بأي مهام يكلف بها من قبل مدير المدرسة وتتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من قبل مدير المدرسة وتتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,2,$q$إعداد تقييم أداء الموظفين الذين يشرف عليهم وتحديد مؤشرات الأداء الرئيسية لهم وإعطاء تغذية راجعة بناءة لهم مع تقديم الدعم والتدريب لتحسين الأداء متى ما تطلب الأمر.$q$,$q$إعداد تقييم أداء الموظفين الذين يشرف عليهم وتحديد مؤشرات الأداء الرئيسية لهم وإعطاء تغذية راجعة بناءة لهم مع تقديم الدعم والتدريب لتحسين الأداء متى ما تطلب الأمر.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,3,$q$توفير التوجيه المناسب لتحسين أداء مرؤوسيه، وتحديد احتياجات التطوير المهني اللازمة لهم ورفعها لمدير المدرسة .$q$,$q$توفير التوجيه المناسب لتحسين أداء مرؤوسيه، وتحديد احتياجات التطوير المهني اللازمة لهم ورفعها لمدير المدرسة .$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,4,$q$المشاركة في إنشاء قنوات تواصل تتسم بالشفافية بين منسوبي المدرسة.$q$,$q$المشاركة في إنشاء قنوات تواصل تتسم بالشفافية بين منسوبي المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,5,$q$الإشراف على تنفيذ الخدمات الإدارية والمساندة للعملية التربوية والتعليمية في المدرسة وتأمين الاحتياجات ذات العلاقة فيها (تنظيم ملفات وسجلات منسوبي المدرسة، ومتابعة سجل الدوام اليومي وإغلاقه، ومتابعة جميع شؤونهم من مباشرة عمل واخلاء طرف وندب والإجازات بأنواعها وغيرها من الإجراءات الوظيفية، وتزويد المعنين بالوثائق والمستندات والمعلومات اللازمة، وخلافها).$q$,$q$الإشراف على تنفيذ الخدمات الإدارية والمساندة للعملية التربوية والتعليمية في المدرسة وتأمين الاحتياجات ذات العلاقة فيها (تنظيم ملفات وسجلات منسوبي المدرسة، ومتابعة سجل الدوام اليومي وإغلاقه، ومتابعة جميع شؤونهم من مباشرة عمل واخلاء طرف وندب والإجازات بأنواعها وغيرها من الإجراءات الوظيفية، وتزويد المعنين بالوثائق والمستندات والمعلومات اللازمة، وخلافها).$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,6,$q$ضمان التنفيذ الفعال لخطة التقنية المعلوماتية في المدرسة، والمساهمة في ضمان تفعيل الحد الأدنى من منصات تقنية المعلومات المعتمدة في المدرسة وضمان استمراريتها واستثمارها بالشكل الأمثل.$q$,$q$ضمان التنفيذ الفعال لخطة التقنية المعلوماتية في المدرسة، والمساهمة في ضمان تفعيل الحد الأدنى من منصات تقنية المعلومات المعتمدة في المدرسة وضمان استمراريتها واستثمارها بالشكل الأمثل.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,7,$q$الإشراف على عملية جمع البيانات لتقييم أداء الخدمات المساندة بالمدرسة وعملياتها وتقديم التقارير اللازمة لمدير المدرسة .$q$,$q$الإشراف على عملية جمع البيانات لتقييم أداء الخدمات المساندة بالمدرسة وعملياتها وتقديم التقارير اللازمة لمدير المدرسة .$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,8,$q$الإشراف على صيانة المدرسة والمحافظة على مرافقها.$q$,$q$الإشراف على صيانة المدرسة والمحافظة على مرافقها.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,9,$q$الإشراف على مصادر التعلم ومتابعة تقديم خدماتها لمنسوبي المدرسة وتعزيز قدرة المكتبة لدعم جميع البرامج والتخصصات.$q$,$q$الإشراف على مصادر التعلم ومتابعة تقديم خدماتها لمنسوبي المدرسة وتعزيز قدرة المكتبة لدعم جميع البرامج والتخصصات.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,10,$q$العمل على ضمان توفر الكتب والمصادر المناسبة للعملية التعليمية في مكتبة المدرسة والتواصل مع الجهات ذات العلاقة لتأمين الاحتياج إن وجد.$q$,$q$العمل على ضمان توفر الكتب والمصادر المناسبة للعملية التعليمية في مكتبة المدرسة والتواصل مع الجهات ذات العلاقة لتأمين الاحتياج إن وجد.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,11,$q$الإشراف على مختبرات ومعامل المدرسة ومتابعة سلامتها وتقديم الخدمات بالشكل المطلوب.$q$,$q$الإشراف على مختبرات ومعامل المدرسة ومتابعة سلامتها وتقديم الخدمات بالشكل المطلوب.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,12,$q$العمل على توفر المواد المختبرية وأجهزة الحاسب الكافية والتي تدعم تحقيق أهداف العملية التعليمية، والتواصل مع الجهات ذات العلاقة لتأمين الاحتياج إن وجد، والإشراف على إتلاف المواد المختبرية وفق التعليمات المنظمة لذلك.$q$,$q$العمل على توفر المواد المختبرية وأجهزة الحاسب الكافية والتي تدعم تحقيق أهداف العملية التعليمية، والتواصل مع الجهات ذات العلاقة لتأمين الاحتياج إن وجد، والإشراف على إتلاف المواد المختبرية وفق التعليمات المنظمة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,13,$q$تحديد احتياجات المدرسة من أجهزة الأمن والسلامة.$q$,$q$تحديد احتياجات المدرسة من أجهزة الأمن والسلامة.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,14,$q$التنسيق مع الجهات المختصة لعقد برامج وورش عمل لمنسوبي المدرسة فيما يخص الأمن والسلامة، لتوعيتهم وتدريبهم بإجراءات السلامة وتعريفهم بوسائل الوقاية الواجب اتخاذها في حينه.$q$,$q$التنسيق مع الجهات المختصة لعقد برامج وورش عمل لمنسوبي المدرسة فيما يخص الأمن والسلامة، لتوعيتهم وتدريبهم بإجراءات السلامة وتعريفهم بوسائل الوقاية الواجب اتخاذها في حينه.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,15,$q$رصد الحالات الطارئة في نظام البلاغات.$q$,$q$رصد الحالات الطارئة في نظام البلاغات.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,16,$q$حضور دروس المعلمين وفق جدول يعتمده مدير المدرسة ويقوم بالتدريس لعدد حصص مادة التخصص وبما لا يتجاوز 8 حصص.$q$,$q$حضور دروس المعلمين وفق جدول يعتمده مدير المدرسة ويقوم بالتدريس لعدد حصص مادة التخصص وبما لا يتجاوز 8 حصص.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,17,$q$حضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته.$q$,$q$حضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,18,$q$الإشراف على عمليات إدارة المرافق المدرسية (المستودع، المقصف،.....) وفق التعليمات المنظمة لذلك.$q$,$q$الإشراف على عمليات إدارة المرافق المدرسية (المستودع، المقصف،.....) وفق التعليمات المنظمة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$deputy_school_affairs$q$),null,19,$q$القيام بأي مهام يكلف بها من قبل مدير المدرسة وتتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من قبل مدير المدرسة وتتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,1,$q$تعزيز قيم الانتماء والمواطنة الاعتزاز بالدين الإسلامي والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة التي تعمل على تنمية الاعتزاز بالدين والولاء للملك والانتماء للوطن.$q$,$q$تعزيز قيم الانتماء والمواطنة الاعتزاز بالدين الإسلامي والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة التي تعمل على تنمية الاعتزاز بالدين والولاء للملك والانتماء للوطن.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,2,$q$احترام الطالب ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.$q$,$q$احترام الطالب ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,3,$q$دعم أهداف المدرسة مع تحديد فرص التحسين وتقديم توصية بشأنها لمدير المدرسة ومقدمي خدمات دعم التميز المدرسي.$q$,$q$دعم أهداف المدرسة مع تحديد فرص التحسين وتقديم توصية بشأنها لمدير المدرسة ومقدمي خدمات دعم التميز المدرسي.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,4,$q$تحقيق الأهداف التعليمية ومؤشرات الأداء الرئيسية التي تقع ضمن تخصصه ومسؤولياته.$q$,$q$تحقيق الأهداف التعليمية ومؤشرات الأداء الرئيسية التي تقع ضمن تخصصه ومسؤولياته.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,5,$q$تحديد مشاكل الطلاب، وطلب الدعم/المشورة من الأطراف المعنية عند الحاجة.$q$,$q$تحديد مشاكل الطلاب، وطلب الدعم/المشورة من الأطراف المعنية عند الحاجة.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,6,$q$المشاركة في اعداد البحوث التخصصية أو التربوية او الاستفادة من نتائج ابحاث تخصصيه او تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.$q$,$q$المشاركة في اعداد البحوث التخصصية أو التربوية او الاستفادة من نتائج ابحاث تخصصيه او تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,7,$q$تصميم تدريس المواد المسندة إليه في المدرسة للطلاب حضورياً أو عن بعد باستخدام استراتيجيات تعليم وتعلم حديثة ومتنوعة وتعمل على تنمية القدرة على التفكير والإبداع لدى الطلاب.$q$,$q$تصميم تدريس المواد المسندة إليه في المدرسة للطلاب حضورياً أو عن بعد باستخدام استراتيجيات تعليم وتعلم حديثة ومتنوعة وتعمل على تنمية القدرة على التفكير والإبداع لدى الطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,8,$q$تفعيل التعليم الإلكتروني بقنواته المختلفة، وتطبيق ممارساته التعليمية بما يتناسب مع احتياجات الطلاب ورفع جودة العملية التعليمية، ومتابعة التطبيقات في المنصات المعتمدة.$q$,$q$تفعيل التعليم الإلكتروني بقنواته المختلفة، وتطبيق ممارساته التعليمية بما يتناسب مع احتياجات الطلاب ورفع جودة العملية التعليمية، ومتابعة التطبيقات في المنصات المعتمدة.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,9,$q$إعداد خطة العمل الفصلية والأسبوعية واليومية، مع استحضار أهداف وعناصر المنهج للمواد المسندة إليه، لضمان التغطية الكاملة لهذه المناهج.$q$,$q$إعداد خطة العمل الفصلية والأسبوعية واليومية، مع استحضار أهداف وعناصر المنهج للمواد المسندة إليه، لضمان التغطية الكاملة لهذه المناهج.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,10,$q$تقييم مستوى الطلاب بشكل مرحلي، وتفعيل جميع أدوات التقويم المتنوعة، وقياس نواتج التعلم، لضمان استيعابهم للمادة التي يتم تدريسها، ووضع خطط علاجية لمعالجة نقاط ضعف الطلاب، وإعداد مواد إثرائية داعمة للمستويات المتقدمة.$q$,$q$تقييم مستوى الطلاب بشكل مرحلي، وتفعيل جميع أدوات التقويم المتنوعة، وقياس نواتج التعلم، لضمان استيعابهم للمادة التي يتم تدريسها، ووضع خطط علاجية لمعالجة نقاط ضعف الطلاب، وإعداد مواد إثرائية داعمة للمستويات المتقدمة.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,11,$q$تهيئة الطلاب وإعدادهم للمشاركة في الاختبارات الوطنية والدولية.$q$,$q$تهيئة الطلاب وإعدادهم للمشاركة في الاختبارات الوطنية والدولية.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,12,$q$إعداد التكليفات والأنشطة والمهام الأدائية والاختبارات وفق الضوابط المعتمدة لذلك، وتصحيحها والعمل على تحديد الاحتياجات الفردية للطالب لفهمها.$q$,$q$إعداد التكليفات والأنشطة والمهام الأدائية والاختبارات وفق الضوابط المعتمدة لذلك، وتصحيحها والعمل على تحديد الاحتياجات الفردية للطالب لفهمها.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,13,$q$تقديم تقييم وتغذية راجعة بناءة وبشكل منتظم تتوافق مع مستويات الطلاب لزيادة التحصيل الدراسي.$q$,$q$تقديم تقييم وتغذية راجعة بناءة وبشكل منتظم تتوافق مع مستويات الطلاب لزيادة التحصيل الدراسي.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,14,$q$تقديم المشورة والتعاون مع المسؤولين ووكيل الشؤون التعليمية والمعلمين حول إعداد وتطوير المقررات، وأدوات التدريس، وإطار التعلم، وبرامج التدريس، وأساليب التدريس والتقييم وتحديد أولويات الرعاية.$q$,$q$تقديم المشورة والتعاون مع المسؤولين ووكيل الشؤون التعليمية والمعلمين حول إعداد وتطوير المقررات، وأدوات التدريس، وإطار التعلم، وبرامج التدريس، وأساليب التدريس والتقييم وتحديد أولويات الرعاية.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,15,$q$التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.$q$,$q$التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,16,$q$الحفاظ على النظام والانضباط بين الطلاب وفقًا للسياسات المدرسة لضمان امتثالهم لتلك السياسات داخل وخارج مبنى المدرسة.$q$,$q$الحفاظ على النظام والانضباط بين الطلاب وفقًا للسياسات المدرسة لضمان امتثالهم لتلك السياسات داخل وخارج مبنى المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,17,$q$تفعيل المختبرات والمعامل ومصادر التعلم لتنمية مهارات التعليم لدى الطلاب.$q$,$q$تفعيل المختبرات والمعامل ومصادر التعلم لتنمية مهارات التعليم لدى الطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,18,$q$الاستخدام الفعال للأجهزة والوسائل التعليمية ذات الصلة وتقديم طلب صيانة لها (آلات العرض، النظام السمعي/المرئي(الفيديو)...إلخ) والاحتياجات الأساسية وذلك لحماية جميع الممتلكات داخل المدرسة والتأكد من استخدامها على النحو الأمثل.$q$,$q$الاستخدام الفعال للأجهزة والوسائل التعليمية ذات الصلة وتقديم طلب صيانة لها (آلات العرض، النظام السمعي/المرئي(الفيديو)...إلخ) والاحتياجات الأساسية وذلك لحماية جميع الممتلكات داخل المدرسة والتأكد من استخدامها على النحو الأمثل.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,19,$q$التخطيط للأنشطة الصفية واللاصفية من قبل المعلم الخبير (إن وجد)، ومشاركة المعلم الممارس والمعلم المتقدم في الإعداد والتنفيذ لهذه الأنشطة مثل الاجتماعات وبرامج التطوير المهني داخل المدرسة (مجتمعات التعلم المهني) والنمو المهني المفتوح (التخصصية والتربوية) خارج المدرسة ، والتي تتعلق بالمتعلمين، المقررات الدراسية أو التنظيم المدرسي.$q$,$q$التخطيط للأنشطة الصفية واللاصفية من قبل المعلم الخبير (إن وجد)، ومشاركة المعلم الممارس والمعلم المتقدم في الإعداد والتنفيذ لهذه الأنشطة مثل الاجتماعات وبرامج التطوير المهني داخل المدرسة (مجتمعات التعلم المهني) والنمو المهني المفتوح (التخصصية والتربوية) خارج المدرسة ، والتي تتعلق بالمتعلمين، المقررات الدراسية أو التنظيم المدرسي.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,20,$q$التنمية الذاتية علمياً ومهنياً وتربوياً، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة أو مقدم خدمات دعم التميز المدرسي المختص وفق التنظيم والوقت المحددين.$q$,$q$التنمية الذاتية علمياً ومهنياً وتربوياً، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة أو مقدم خدمات دعم التميز المدرسي المختص وفق التنظيم والوقت المحددين.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,21,$q$المشاركة في تنمية زملاء العمل علمياً ومهنياً وتربوياً وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.$q$,$q$المشاركة في تنمية زملاء العمل علمياً ومهنياً وتربوياً وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,22,$q$التواصل المستمر مع أولياء الأمور بالتعاون مع الموجه الطلابي، لاطلاعهم وتعريفهم بمستوى أبنائهم وتسليط الضوء على أي جوانب تستدعي الاهتمام وبناء شراكات مجتمعية مع مؤسسات المجتمع.$q$,$q$التواصل المستمر مع أولياء الأمور بالتعاون مع الموجه الطلابي، لاطلاعهم وتعريفهم بمستوى أبنائهم وتسليط الضوء على أي جوانب تستدعي الاهتمام وبناء شراكات مجتمعية مع مؤسسات المجتمع.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,23,$q$تنفيذ أنشطة المدرسة التعليمية/ التعليمية المساندة ضمن الامكانيات المحددة.$q$,$q$تنفيذ أنشطة المدرسة التعليمية/ التعليمية المساندة ضمن الامكانيات المحددة.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,24,$q$إعداد تقرير يتضمن تفاصيل الأنشطة والإنجازات والمعوقات أثناء تنفيذ مهامه كمعلم.$q$,$q$إعداد تقرير يتضمن تفاصيل الأنشطة والإنجازات والمعوقات أثناء تنفيذ مهامه كمعلم.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,25,$q$تفهم الخصائص النفسية للمرحلة العمرية التي يقوم بتدريسها والاجتماعية للكبار أو خصائص المرحلة.$q$,$q$تفهم الخصائص النفسية للمرحلة العمرية التي يقوم بتدريسها والاجتماعية للكبار أو خصائص المرحلة.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,26,$q$القيام بأعمال المناوبة والإشراف على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي ب 15 دقيقة وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته. والمشاركة في الإشراف اليومي على الطلاب حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الإنتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع، وسد العجز الطارئ وفق توجيه إدارة المدرسة.$q$,$q$القيام بأعمال المناوبة والإشراف على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي ب 15 دقيقة وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته. والمشاركة في الإشراف اليومي على الطلاب حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الإنتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع، وسد العجز الطارئ وفق توجيه إدارة المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$teacher$q$),null,27,$q$القيام بأي مهام يكلف بها من قبل مدير المدرسة تتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من قبل مدير المدرسة تتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، والمشاركة في متابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، والمشاركة في متابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,2,$q$مساعدة المعلم في ضبط الفصل الدراسي، والحفاظ على النظام والانضباط بين الطلاب وفقًا لسياسات المدرسة ،وإكمال أداءمهامه المنصوص عليها في حال غياب المعلم لضمان امتثالهم لتلك السياسات داخل وخارج مبنى المدرسة.$q$,$q$مساعدة المعلم في ضبط الفصل الدراسي، والحفاظ على النظام والانضباط بين الطلاب وفقًا لسياسات المدرسة ،وإكمال أداءمهامه المنصوص عليها في حال غياب المعلم لضمان امتثالهم لتلك السياسات داخل وخارج مبنى المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,3,$q$مساعدة المعلم في تحقيق الأهداف التعليمية ومؤشرات الأداء الرئيسية التي تقع ضمن تخصصه ومسؤولياته.$q$,$q$مساعدة المعلم في تحقيق الأهداف التعليمية ومؤشرات الأداء الرئيسية التي تقع ضمن تخصصه ومسؤولياته.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,4,$q$العمل مع المعلم في تنظيم الأنشطة التعليمية داخل الفصل وفي الأنشطة اللامنهجية داخل المدرسة وخارجها، والمشاركة في تنفيذها تحت إشراف المعلم.$q$,$q$العمل مع المعلم في تنظيم الأنشطة التعليمية داخل الفصل وفي الأنشطة اللامنهجية داخل المدرسة وخارجها، والمشاركة في تنفيذها تحت إشراف المعلم.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,5,$q$مساعدة معلم المادة في متابعة تنفيذ الخطط التعليمية الخاصة بكل طالب، وفق توجيهات المعلم.$q$,$q$مساعدة معلم المادة في متابعة تنفيذ الخطط التعليمية الخاصة بكل طالب، وفق توجيهات المعلم.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,6,$q$تكثيف المتابعة مع الطلاب ذوي المستوى التحصيلي المنخفض ليتمكنوا من مسايرة زملائهم ، وفق توجيهات المعلم.$q$,$q$تكثيف المتابعة مع الطلاب ذوي المستوى التحصيلي المنخفض ليتمكنوا من مسايرة زملائهم ، وفق توجيهات المعلم.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,7,$q$المساعدة في إعداد المواد التعليمية وتحضير بعض الأدوات الخاصة بالصف الدراسي، وتجهيز الوسائل التعليمية اللازمة للحصة الدراسية.$q$,$q$المساعدة في إعداد المواد التعليمية وتحضير بعض الأدوات الخاصة بالصف الدراسي، وتجهيز الوسائل التعليمية اللازمة للحصة الدراسية.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,8,$q$توزيع المواد التعليمية مثل الاختبارات والواجبات المنزلية وجمعها، والمساعدة في رصد/وضع الدرجات والنتائج، ومتابعة مستوى التقدم لدى طلاب الفصل.$q$,$q$توزيع المواد التعليمية مثل الاختبارات والواجبات المنزلية وجمعها، والمساعدة في رصد/وضع الدرجات والنتائج، ومتابعة مستوى التقدم لدى طلاب الفصل.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,9,$q$يساعد المعلم في إعداد خطة الدرس، وإعداد المراجع، والخرائط، والنماذج والرسوم البيانية، وتجهيز السبورة، ولوحة الإعلانات وتسجيل الحضور والغياب للطلاب في الحصة.$q$,$q$يساعد المعلم في إعداد خطة الدرس، وإعداد المراجع، والخرائط، والنماذج والرسوم البيانية، وتجهيز السبورة، ولوحة الإعلانات وتسجيل الحضور والغياب للطلاب في الحصة.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,10,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$),
  ((select id from public.guide_jobs where code=$q$teacher_assistant$q$),null,11,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,2,$q$احترام الطالب ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.$q$,$q$احترام الطالب ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,3,$q$تقييم مستوى الطلاب بشكل مرحلي، وقياس نواتج التعلم، لضمان استيعابهم للمادة التي يتم تدريسها، ووضع خطط علاجية لمعالجة نقاط ضعف الطلاب، وإعداد مواد إثرائية داعمة للمستويات المتقدمة.$q$,$q$تقييم مستوى الطلاب بشكل مرحلي، وقياس نواتج التعلم، لضمان استيعابهم للمادة التي يتم تدريسها، ووضع خطط علاجية لمعالجة نقاط ضعف الطلاب، وإعداد مواد إثرائية داعمة للمستويات المتقدمة.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,4,$q$تصميم وتدريس المواد المسندة إليه في المدرسة للطلاب ذوي الإعاقة (بأسلوب فردي أو مجموعات) حضورياً أو عن بعد باستخدام استراتيجيات تعليم وتعلم حديثة ومتنوعة وتعمل على تنمية القدرة على التفكير والإبداع لدى الطلاب.$q$,$q$تصميم وتدريس المواد المسندة إليه في المدرسة للطلاب ذوي الإعاقة (بأسلوب فردي أو مجموعات) حضورياً أو عن بعد باستخدام استراتيجيات تعليم وتعلم حديثة ومتنوعة وتعمل على تنمية القدرة على التفكير والإبداع لدى الطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,5,$q$إعداد خطة العمل الفصلية والأسبوعية واليومية، مع استحضار عناصر المنهج للمواد المسندة إليه، لضمان التغطية الكاملة لهذه المناهج.$q$,$q$إعداد خطة العمل الفصلية والأسبوعية واليومية، مع استحضار عناصر المنهج للمواد المسندة إليه، لضمان التغطية الكاملة لهذه المناهج.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,6,$q$تولي مسؤولية غرفة المصادر لذوي الإعاقة (إن وجدت) في المدرسة والعمل على تحديد العجز من التجهيزات المطلوبة لها ومن التجهيزات المطلوبة للمبنى المدرسي لحالات الطلاب ذوي الإعاقة ورفعها لوكيل الشؤون المدرسية.$q$,$q$تولي مسؤولية غرفة المصادر لذوي الإعاقة (إن وجدت) في المدرسة والعمل على تحديد العجز من التجهيزات المطلوبة لها ومن التجهيزات المطلوبة للمبنى المدرسي لحالات الطلاب ذوي الإعاقة ورفعها لوكيل الشؤون المدرسية.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,7,$q$المشاركة في إعداد الجداول الدراسية لكل طالب من ذوي الإعاقة بالتعاون والتنسيق مع المعنيين في المدرسة.$q$,$q$المشاركة في إعداد الجداول الدراسية لكل طالب من ذوي الإعاقة بالتعاون والتنسيق مع المعنيين في المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,8,$q$التواصل مع أولياء الأمور وتوعيتهم وتفعيل دورهم في المشاركة الإيجابية مع المعنيين في المدرسة بالتعاون مع الموجه الطلابي.$q$,$q$التواصل مع أولياء الأمور وتوعيتهم وتفعيل دورهم في المشاركة الإيجابية مع المعنيين في المدرسة بالتعاون مع الموجه الطلابي.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,9,$q$التنسيق مع الجهات ذات العلاقة داخل وخارج المدرسة فيما يتعلق بالطلاب ذوي الإعاقة.$q$,$q$التنسيق مع الجهات ذات العلاقة داخل وخارج المدرسة فيما يتعلق بالطلاب ذوي الإعاقة.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,10,$q$تنظيم السجلات والوثائق ذات العلاقة بذوي الإعاقة وفق الأسس الفنية المتعارف عليها.$q$,$q$تنظيم السجلات والوثائق ذات العلاقة بذوي الإعاقة وفق الأسس الفنية المتعارف عليها.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,11,$q$تقديم الدعم للهيئة التعليمية أو اللجان ذات العلاقة في الأمور التي تخص الطلاب ذوي الإعاقة من طرق التدريس والاستراتيجيات التعليمية وأساليب التعامل مع الطالب و أساليب تأدية الاختبارات وغيرها.$q$,$q$تقديم الدعم للهيئة التعليمية أو اللجان ذات العلاقة في الأمور التي تخص الطلاب ذوي الإعاقة من طرق التدريس والاستراتيجيات التعليمية وأساليب التعامل مع الطالب و أساليب تأدية الاختبارات وغيرها.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,12,$q$تنفيذ التطبيقات الصفية ومراجعة نواتج التعلم بمعدل عشر دقائق للحصة الواحدة.$q$,$q$تنفيذ التطبيقات الصفية ومراجعة نواتج التعلم بمعدل عشر دقائق للحصة الواحدة.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,13,$q$متابعة أعمال الطلاب الصفية والواجبات المنزلية وتصحيحها، وتقديم التغذية الراجعة لهم.$q$,$q$متابعة أعمال الطلاب الصفية والواجبات المنزلية وتصحيحها، وتقديم التغذية الراجعة لهم.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,14,$q$إعداد وتنفيذ البرامج التربوية الفردية والخاصة بالطلاب ذوي الإعاقة ومتابعة نتائجها والعمل على تطويرها.$q$,$q$إعداد وتنفيذ البرامج التربوية الفردية والخاصة بالطلاب ذوي الإعاقة ومتابعة نتائجها والعمل على تطويرها.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,15,$q$إعداد التقارير الدورية عن مستوى الطلاب ذوي الإعاقة وتزويد أولياء أمورهم بها بعد اعتمادها من وكيل الشؤون التعليمية.$q$,$q$إعداد التقارير الدورية عن مستوى الطلاب ذوي الإعاقة وتزويد أولياء أمورهم بها بعد اعتمادها من وكيل الشؤون التعليمية.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,16,$q$إعداد وتنفيذ الاختبارات للطلاب ذوي الإعاقة بالمشاركة مع ذوي العلاقة في المدرسة، حسب ما ورد في المذكرة التفسيرية للائحة تقويم الطالب للعام 1443ه.$q$,$q$إعداد وتنفيذ الاختبارات للطلاب ذوي الإعاقة بالمشاركة مع ذوي العلاقة في المدرسة، حسب ما ورد في المذكرة التفسيرية للائحة تقويم الطالب للعام 1443ه.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,17,$q$إعداد البرامج الترفيهية والأنشطة الصفية واللا صفية وبرامج الصحة والسلامة وتفعيل مناسبات الإعاقة المحلية والإقليمية والعالمية بالتعاون مع الجهات المعنية في المدرسة وخارجها، بالتنسيق مع رائد النشاط.$q$,$q$إعداد البرامج الترفيهية والأنشطة الصفية واللا صفية وبرامج الصحة والسلامة وتفعيل مناسبات الإعاقة المحلية والإقليمية والعالمية بالتعاون مع الجهات المعنية في المدرسة وخارجها، بالتنسيق مع رائد النشاط.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,18,$q$القيام بأعمال المناوبة والإشراف على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي ب 15 دقيقة وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته والمشاركة في الإشراف اليومي على الطلاب حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 29 ساعة في الأسبوع.$q$,$q$القيام بأعمال المناوبة والإشراف على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي ب 15 دقيقة وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته والمشاركة في الإشراف اليومي على الطلاب حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 29 ساعة في الأسبوع.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,19,$q$تغطية حصص الانتظار والقيام بعمل معلم ذوي الإعاقة الغائب وسد العجز الطارئ في عددهم في المدرسة وفق توجيه إدارة المدرسة.$q$,$q$تغطية حصص الانتظار والقيام بعمل معلم ذوي الإعاقة الغائب وسد العجز الطارئ في عددهم في المدرسة وفق توجيه إدارة المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,20,$q$دراسة ومعالجة صعوبات التعلم وأسبابها لدى الطلاب اللذين يواجهون هذه المشكلة.$q$,$q$دراسة ومعالجة صعوبات التعلم وأسبابها لدى الطلاب اللذين يواجهون هذه المشكلة.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,21,$q$المشاركة في اعداد البحوث التخصصية أو التربوية او الاستفادة من نتائج أبحاث تخصصيه او تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.$q$,$q$المشاركة في اعداد البحوث التخصصية أو التربوية او الاستفادة من نتائج أبحاث تخصصيه او تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,22,$q$التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.$q$,$q$التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,23,$q$التنمية الذاتية علمياً ومهنياً وتربوياً، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة بالتنسيق مع الجهات ذات العلاقة أو مقدمو خدمات دعم التميز المدرسي المختصون، ووفق التنظيم والوقت المحددين.$q$,$q$التنمية الذاتية علمياً ومهنياً وتربوياً، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة بالتنسيق مع الجهات ذات العلاقة أو مقدمو خدمات دعم التميز المدرسي المختصون، ووفق التنظيم والوقت المحددين.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,24,$q$تنمية زملاء العمل علمياً ومهنياً وتربوياً وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.$q$,$q$تنمية زملاء العمل علمياً ومهنياً وتربوياً وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,25,$q$الالتزام بالنصاب التدريسي حسب الرتب التعليمية التي يشغلها، 18حصة للمعلم الممارس، و16 حصة للمعلم المتقدم، و14 حصة للمعلم الخبير.$q$,$q$الالتزام بالنصاب التدريسي حسب الرتب التعليمية التي يشغلها، 18حصة للمعلم الممارس، و16 حصة للمعلم المتقدم، و14 حصة للمعلم الخبير.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher$q$),null,26,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,2,$q$احترام الطالب ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.$q$,$q$احترام الطالب ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,3,$q$تنفيذ الخطة التشغيلية لبرامج الموهوبين وفقاً للمعايير العلمية والضوابط التنظيمية المنصوص عليها.$q$,$q$تنفيذ الخطة التشغيلية لبرامج الموهوبين وفقاً للمعايير العلمية والضوابط التنظيمية المنصوص عليها.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,4,$q$المشاركة والتنسيق لترشيح الطلاب للمشروع الوطني للكشف على الموهوبين.$q$,$q$المشاركة والتنسيق لترشيح الطلاب للمشروع الوطني للكشف على الموهوبين.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,5,$q$اختيار وترشيح الطلاب لبرامج الموهوبين داخل المدرسة وخارجها عن طريق مدير المدرسة وفق مخرجات المشروع الوطني للكشف على الموهوبين.$q$,$q$اختيار وترشيح الطلاب لبرامج الموهوبين داخل المدرسة وخارجها عن طريق مدير المدرسة وفق مخرجات المشروع الوطني للكشف على الموهوبين.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,6,$q$إعداد قاعدة بيانات للطلاب الموهوبين داخل المدرسة وتزويد قسم الموهوبين بنسخة منها، وربطها مع النظام.$q$,$q$إعداد قاعدة بيانات للطلاب الموهوبين داخل المدرسة وتزويد قسم الموهوبين بنسخة منها، وربطها مع النظام.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,7,$q$متابعة أعمال الطلاب الصفية والمشاريع والأنشطة الإثرائية، وتقديم التغذية الراجعة لهم.$q$,$q$متابعة أعمال الطلاب الصفية والمشاريع والأنشطة الإثرائية، وتقديم التغذية الراجعة لهم.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,8,$q$قياس نواتج التعلم في الحصص الدراسية واستيفاء النماذج المخصصة لذلك.$q$,$q$قياس نواتج التعلم في الحصص الدراسية واستيفاء النماذج المخصصة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,9,$q$التنسيق مع الموجه الطلابي بالمدرسة؛ لتوفير الرعاية النفسية والاجتماعية المناسبة للطلاب الموهوبين.$q$,$q$التنسيق مع الموجه الطلابي بالمدرسة؛ لتوفير الرعاية النفسية والاجتماعية المناسبة للطلاب الموهوبين.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,10,$q$تنمية مهارات التفكير والبحث العلمي لدى الطلاب الموهوبين التي تناسب اهتماماتهم وميولهم من خلال تقديم البرامج الإثرائية.$q$,$q$تنمية مهارات التفكير والبحث العلمي لدى الطلاب الموهوبين التي تناسب اهتماماتهم وميولهم من خلال تقديم البرامج الإثرائية.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,11,$q$تغطية حصص الانتظار (بما لا يزيد عن حصتين في الأسبوع), والقيام بعمل المعلم الغائب وسد العجز الطارئ في عدد معلمي المدرسة وفق توجيه إدارة المدرسة.$q$,$q$تغطية حصص الانتظار (بما لا يزيد عن حصتين في الأسبوع), والقيام بعمل المعلم الغائب وسد العجز الطارئ في عدد معلمي المدرسة وفق توجيه إدارة المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,12,$q$القيام بأعمال المناوبة والإشراف على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي ب 15 دقيقة وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته ، والمشاركة في الإشراف اليومي على الطلاب حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$,$q$القيام بأعمال المناوبة والإشراف على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي ب 15 دقيقة وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته ، والمشاركة في الإشراف اليومي على الطلاب حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، وبما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,13,$q$المشاركة في تقويم برامج الموهوبين في المدرسة باستخدام أدوات التقويم المعتمدة، وإبراز جميع أعمال ومنجزات الطلاب الموهوبين داخل المدرسة من خلال المعرض الختامي السنوي.$q$,$q$المشاركة في تقويم برامج الموهوبين في المدرسة باستخدام أدوات التقويم المعتمدة، وإبراز جميع أعمال ومنجزات الطلاب الموهوبين داخل المدرسة من خلال المعرض الختامي السنوي.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,14,$q$التواصل مع أولياء أمور الموهوبين فيما يخص شئون مواهبهم، والمشاركة في عضوية اللجان الخاصة بالموهوبين داخل المدرسة إن وجدت، مثل: لجنة تسريع الطلاب الموهوبين وغيرها من اللجان.$q$,$q$التواصل مع أولياء أمور الموهوبين فيما يخص شئون مواهبهم، والمشاركة في عضوية اللجان الخاصة بالموهوبين داخل المدرسة إن وجدت، مثل: لجنة تسريع الطلاب الموهوبين وغيرها من اللجان.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,15,$q$المشاركة في نشر ثقافة الموهبة والإبداع داخل المجتمع المدرسي والبيئة المحيطة، والبرامج الإثرائية والمسابقات التي ينفذها قسم الموهوبين في إدارة التعليم العامة.$q$,$q$المشاركة في نشر ثقافة الموهبة والإبداع داخل المجتمع المدرسي والبيئة المحيطة، والبرامج الإثرائية والمسابقات التي ينفذها قسم الموهوبين في إدارة التعليم العامة.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,16,$q$حضور ورش العمل والاجتماعات الدورية والبرامج التدريبية لمعلمي الموهوبين وفق خطة قسم الموهوبين في إدارة التعليم العامة.$q$,$q$حضور ورش العمل والاجتماعات الدورية والبرامج التدريبية لمعلمي الموهوبين وفق خطة قسم الموهوبين في إدارة التعليم العامة.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,17,$q$ترشيح طلبة المدرسة للبرنامج الوطني للكشف عن الموهوبين عن طريق مدير المدرسة، والأولمبياد الوطني للإبداع العلمي "إبداع"، والمسابقات والفعاليات الأخرى المعتمدة في مجال الموهوبين.$q$,$q$ترشيح طلبة المدرسة للبرنامج الوطني للكشف عن الموهوبين عن طريق مدير المدرسة، والأولمبياد الوطني للإبداع العلمي "إبداع"، والمسابقات والفعاليات الأخرى المعتمدة في مجال الموهوبين.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,18,$q$المشاركة في اعداد البحوث التخصصية أو التربوية او الاستفادة من نتائج ابحاث تخصصيه او تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.$q$,$q$المشاركة في اعداد البحوث التخصصية أو التربوية او الاستفادة من نتائج ابحاث تخصصيه او تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,19,$q$التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.$q$,$q$التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,20,$q$التنمية الذاتية علميا ومهنيا وتربويا، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة بالتنسيق مع الجهات ذات العلاقة أو مقدمو خدمات دعم التميز المدرسي المختصون، وفق التنظيم والوقت المحددين.$q$,$q$التنمية الذاتية علميا ومهنيا وتربويا، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة بالتنسيق مع الجهات ذات العلاقة أو مقدمو خدمات دعم التميز المدرسي المختصون، وفق التنظيم والوقت المحددين.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,21,$q$تنمية زملاء العمل علمياً ومهنياً وتربوياً وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.$q$,$q$تنمية زملاء العمل علمياً ومهنياً وتربوياً وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,22,$q$إعداد تقرير ختامي سنوي عن البرامج المنفذة والدور الذي قام به داخل المدرسة، والعمل على رفع التوصيات على ما تم ملاحظته خلال العام؛ لتطوير وتجويد العمل وتحسينه لرفعها لقسم الموهوبين في إدارة التعليم العامة.$q$,$q$إعداد تقرير ختامي سنوي عن البرامج المنفذة والدور الذي قام به داخل المدرسة، والعمل على رفع التوصيات على ما تم ملاحظته خلال العام؛ لتطوير وتجويد العمل وتحسينه لرفعها لقسم الموهوبين في إدارة التعليم العامة.$q$),
  ((select id from public.guide_jobs where code=$q$gifted_teacher$q$),null,23,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,2,$q$احترام الطفل ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.$q$,$q$احترام الطفل ومعاملته معاملة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي مواهبه، وتغرس في نفسه حب المعرفة، وتكسبه السلوك الحميد والمودة للآخرين وتؤصل فيه الاستقامة والثقة بالنفس.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,3,$q$تنفيذ الخطة وفقاً للمعايير العلمية والضوابط التنظيمية المنصوص عليها.$q$,$q$تنفيذ الخطة وفقاً للمعايير العلمية والضوابط التنظيمية المنصوص عليها.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,4,$q$التعامل مع الطفل بطريقة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي اهتماماته وخصائصه العمرية، وتغرس في نفسه حب التعلم والمعرفة، وتكسبه السلوك الإيجابي والتواصل الفعال مع المحيطين به، وتؤصل فيه الثقة بالنفس.$q$,$q$التعامل مع الطفل بطريقة تربوية تحقق له الأمن والطمأنينة وتنمي شخصيته، وتشعره بقيمته وتراعي اهتماماته وخصائصه العمرية، وتغرس في نفسه حب التعلم والمعرفة، وتكسبه السلوك الإيجابي والتواصل الفعال مع المحيطين به، وتؤصل فيه الثقة بالنفس.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,5,$q$تقبل جميع الأطفال ومعاملتهم بعدالة وعدم التحيز واحترام الاختلافات بينهم في الشكل واللون والعرق والثقافة.$q$,$q$تقبل جميع الأطفال ومعاملتهم بعدالة وعدم التحيز واحترام الاختلافات بينهم في الشكل واللون والعرق والثقافة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,6,$q$تفعيل منهج رياض الأطفال المعتمد والتخطيط للبرنامج الأسبوعي واليومي وتنفيذه، مع تطبيق الممارسات الملائمة نمائياً، والأنشطة والوسائل التعليمية التربوية المصاحبة، وتنمية جوانب الإبداع لدى الأطفال وتعزيزها.$q$,$q$تفعيل منهج رياض الأطفال المعتمد والتخطيط للبرنامج الأسبوعي واليومي وتنفيذه، مع تطبيق الممارسات الملائمة نمائياً، والأنشطة والوسائل التعليمية التربوية المصاحبة، وتنمية جوانب الإبداع لدى الأطفال وتعزيزها.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,7,$q$تهيئة البيئة التعليمية، والاستعانة بالتقنية الداعمة، وإعداد الوسائل التعليمية والتخطيط لبناء أنشطة محفزة، واستثمار المواقف التعليمية بما يتوافق مع الخصائص النمائية للطفل وطبيعة المرحلة العمرية واحتياجاتها؛ لدعم العملية التعليمية من أجل تحقيق الأهداف التربوية المنشودة.$q$,$q$تهيئة البيئة التعليمية، والاستعانة بالتقنية الداعمة، وإعداد الوسائل التعليمية والتخطيط لبناء أنشطة محفزة، واستثمار المواقف التعليمية بما يتوافق مع الخصائص النمائية للطفل وطبيعة المرحلة العمرية واحتياجاتها؛ لدعم العملية التعليمية من أجل تحقيق الأهداف التربوية المنشودة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,8,$q$تقويم الطفل بشكل مستمر وقياس نواتج التعلم لديه ومتابعة تطور جوانب النمو المختلفة مع تقديم النتائج والتوصيات للجهات ذات العلاقة، وتقديم التغذية الراجعة لهم.$q$,$q$تقويم الطفل بشكل مستمر وقياس نواتج التعلم لديه ومتابعة تطور جوانب النمو المختلفة مع تقديم النتائج والتوصيات للجهات ذات العلاقة، وتقديم التغذية الراجعة لهم.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,9,$q$دراسة حالة الطفل في حال تطلب دعم أحد جوانب نمو الطفل أو ظهور مشاكل سلوكية بالتنسيق مع ذوي العلاقة، لإيجاد الحلول التربوية الملائمة.$q$,$q$دراسة حالة الطفل في حال تطلب دعم أحد جوانب نمو الطفل أو ظهور مشاكل سلوكية بالتنسيق مع ذوي العلاقة، لإيجاد الحلول التربوية الملائمة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,10,$q$التنسيق مع الموجه الطلابي بالمدرسة (إن وجد) وإدارة المدرسة لتوفير الرعاية النفسية والاجتماعية المناسبة للأطفال الموهوبين وللطلاب الذين لديهم مشكلات سلوكية لمتابعة دراسة حالتهم.$q$,$q$التنسيق مع الموجه الطلابي بالمدرسة (إن وجد) وإدارة المدرسة لتوفير الرعاية النفسية والاجتماعية المناسبة للأطفال الموهوبين وللطلاب الذين لديهم مشكلات سلوكية لمتابعة دراسة حالتهم.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,11,$q$التبليغ عن الحالات الطارئة أو الخاصة، أو المرضية، واتباع الاجراءات النظامية عند الاشتباه بحالة عنف أو أي نوع من الإيذاء نحو الطفل حسب التعاميم المنظمة لذلك.$q$,$q$التبليغ عن الحالات الطارئة أو الخاصة، أو المرضية، واتباع الاجراءات النظامية عند الاشتباه بحالة عنف أو أي نوع من الإيذاء نحو الطفل حسب التعاميم المنظمة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,12,$q$القيام بأعمال المناوبة والإشراف على الأطفال في الفصل الخاص به بداية الدوام الرسمي قبل الاصطفاف الصباحي ب 15 دقيقة وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته، والمشاركة في الإشراف اليومي على الأطفال حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع، وسد العجز الطارئ وفق توجيه إدارة المدرسة، وسد العجز الطارئ وفق توجيه إدارة المدرسة.$q$,$q$القيام بأعمال المناوبة والإشراف على الأطفال في الفصل الخاص به بداية الدوام الرسمي قبل الاصطفاف الصباحي ب 15 دقيقة وبعد نهايته بما لا يزيد عن 30 دقيقة، وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته، والمشاركة في الإشراف اليومي على الأطفال حال قل عدد شاغلي الوظائف الإدارية في المدرسة عن خمسة موظفين، وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع، وسد العجز الطارئ وفق توجيه إدارة المدرسة، وسد العجز الطارئ وفق توجيه إدارة المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,13,$q$مواكبة المستجدات وتنمية الذات، وتطوير الكفايات العلمية والمهنية والتربوية من خلال المشاركة في البرامج والأنشطة والدورات التربوية وورش العمل التي تطور المتطلبات الوظيفية.$q$,$q$مواكبة المستجدات وتنمية الذات، وتطوير الكفايات العلمية والمهنية والتربوية من خلال المشاركة في البرامج والأنشطة والدورات التربوية وورش العمل التي تطور المتطلبات الوظيفية.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,14,$q$متابعة الأطفال خلال فترات البرنامج اليومي للحفاظ على أمنهم وسلامتهم، وتوجيه سلوكهم بما يتناسب مع الخصائص النمائية للمرحلة.$q$,$q$متابعة الأطفال خلال فترات البرنامج اليومي للحفاظ على أمنهم وسلامتهم، وتوجيه سلوكهم بما يتناسب مع الخصائص النمائية للمرحلة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,15,$q$تقويم جوانب العملية التعليمية (أنشطة المنهج، بيئات التعلم، الممارسات والاستراتيجيات، والمواد التعليمية) وتطوير النتائج؛ لتحقيق الأهداف ورفع مستوى جودة التعليم والتعلم.$q$,$q$تقويم جوانب العملية التعليمية (أنشطة المنهج، بيئات التعلم، الممارسات والاستراتيجيات، والمواد التعليمية) وتطوير النتائج؛ لتحقيق الأهداف ورفع مستوى جودة التعليم والتعلم.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,16,$q$بناء علاقة إيجابية مع أسر الأطفال، لدعم جوانب نموه وتلبية احتياجاته وتعزيز قدراته ومهاراته.$q$,$q$بناء علاقة إيجابية مع أسر الأطفال، لدعم جوانب نموه وتلبية احتياجاته وتعزيز قدراته ومهاراته.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,17,$q$المشاركة في اعداد البحوث التخصصية أو التربوية او الاستفادة من نتائج ابحاث تخصصيه او تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.$q$,$q$المشاركة في اعداد البحوث التخصصية أو التربوية او الاستفادة من نتائج ابحاث تخصصيه او تربوية من قبل جميع الرتب التعليمية، وتنفيذ البحوث الإجرائية من قبل المعلم الخبير.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,18,$q$التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.$q$,$q$التعاون مع مقدمي خدمات دعم التميز المدرسي والتعامل الإيجابي مع ما يوصون به وما يقدمونه من خبرات.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,19,$q$التنمية الذاتية علميا ومهنيا وتربويا، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة بالتنسيق مع الجهات ذات العلاقة أو مقدمو خدمات دعم التميز المدرسي المختصون، وفق التنظيم والوقت المحددين.$q$,$q$التنمية الذاتية علميا ومهنيا وتربويا، وحضور الدورات وورش العمل التي تنظمها إدارة التعليم العامة بالتنسيق مع الجهات ذات العلاقة أو مقدمو خدمات دعم التميز المدرسي المختصون، وفق التنظيم والوقت المحددين.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,20,$q$تنمية زملاء العمل علميا ومهنيا وتربويا وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.$q$,$q$تنمية زملاء العمل علميا ومهنيا وتربويا وتقديم الدورات وورش العمل من قبل المعلم المتقدم والخبير.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,21,$q$المشاركة في تنظيم الفصل والملاعب الداخلية والخارجية.$q$,$q$المشاركة في تنظيم الفصل والملاعب الداخلية والخارجية.$q$),
  ((select id from public.guide_jobs where code=$q$kg_teacher$q$),null,22,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,2,$q$مساعدة المعلم في ضبط الفصل الدراسي، والحفاظ على النظام والانضباط بين الطلاب وفقًا لسياسات المدرسة لضمان امتثالهم لتلك السياسات داخل وخارج مبنى المدرسة.$q$,$q$مساعدة المعلم في ضبط الفصل الدراسي، والحفاظ على النظام والانضباط بين الطلاب وفقًا لسياسات المدرسة لضمان امتثالهم لتلك السياسات داخل وخارج مبنى المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,3,$q$مساعدة المعلم في تحقيق الأهداف التعليمية ومؤشرات الأداء الرئيسية التي تقع ضمن تخصصه ومسؤولياته.$q$,$q$مساعدة المعلم في تحقيق الأهداف التعليمية ومؤشرات الأداء الرئيسية التي تقع ضمن تخصصه ومسؤولياته.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,4,$q$دعم معلم ذوي الإعاقة في التقييم لحالات الإعاقة.$q$,$q$دعم معلم ذوي الإعاقة في التقييم لحالات الإعاقة.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,5,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,6,$q$العمل مع المعلم في إعداد وتنظيم الأنشطة التعليمية داخل الفصل وفي الأنشطة اللامنهجية داخل المدرسة وخارجها، والمشاركة في تنفيذها تحت إشراف المعلم.$q$,$q$العمل مع المعلم في إعداد وتنظيم الأنشطة التعليمية داخل الفصل وفي الأنشطة اللامنهجية داخل المدرسة وخارجها، والمشاركة في تنفيذها تحت إشراف المعلم.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,7,$q$مساعدة معلم ذوي الإعاقة على إعداد الخطط التعليمية الخاصة بكل طالب، ومتابعة تنفيذها وفق توجيهات المعلم.$q$,$q$مساعدة معلم ذوي الإعاقة على إعداد الخطط التعليمية الخاصة بكل طالب، ومتابعة تنفيذها وفق توجيهات المعلم.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,8,$q$مساعدة الطلاب أثناء مراجعتهم دروسهم، وتكثيف المتابعة مع الطلاب ذوي المستوى التحصيلي المنخفض ليتمكنوا من مسايرة زملائهم.$q$,$q$مساعدة الطلاب أثناء مراجعتهم دروسهم، وتكثيف المتابعة مع الطلاب ذوي المستوى التحصيلي المنخفض ليتمكنوا من مسايرة زملائهم.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,9,$q$المساعدة في إعداد المواد التعليمية وتحضير بعض الأدوات الخاصة بالصف الدراسي، وتجهيز الوسائل التعليمية اللازمة للحصة الدراسية.$q$,$q$المساعدة في إعداد المواد التعليمية وتحضير بعض الأدوات الخاصة بالصف الدراسي، وتجهيز الوسائل التعليمية اللازمة للحصة الدراسية.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,10,$q$توزيع المواد التعليمية مثل الاختبارات والواجبات المنزلية وجمعها، والمساعدة في رصد/وضع الدرجات والنتائج، ومتابعة مستوى التقدم لدى طلاب الفصل ولدى الطلاب المستهدفين خاصة داخل الفصل.$q$,$q$توزيع المواد التعليمية مثل الاختبارات والواجبات المنزلية وجمعها، والمساعدة في رصد/وضع الدرجات والنتائج، ومتابعة مستوى التقدم لدى طلاب الفصل ولدى الطلاب المستهدفين خاصة داخل الفصل.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,11,$q$المشاركة في الاجتماعات التي يحضرها أولياء أمور الطلاب لمناقشة أوضاعهم الدراسية والسلوكية.$q$,$q$المشاركة في الاجتماعات التي يحضرها أولياء أمور الطلاب لمناقشة أوضاعهم الدراسية والسلوكية.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,12,$q$تولي مسؤولية ضبط الفصل/الطلاب في حال غياب المعلم وإكمال أداءمهامه المنصوص عليها.$q$,$q$تولي مسؤولية ضبط الفصل/الطلاب في حال غياب المعلم وإكمال أداءمهامه المنصوص عليها.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,13,$q$مساعدة المعلم في إعداد خطة الدرس، وإعداد المراجع، والخرائط، والنماذج والرسوم البيانية، وتجهيز السبورة، ولوحة الإعلانات وتسجيل الحضور والغياب للطلاب في الحصة.$q$,$q$مساعدة المعلم في إعداد خطة الدرس، وإعداد المراجع، والخرائط، والنماذج والرسوم البيانية، وتجهيز السبورة، ولوحة الإعلانات وتسجيل الحضور والغياب للطلاب في الحصة.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,14,$q$مساعدة الطلاب ذوي الإعاقة على فهم الدروس والتعليمات التي يقدمها المعلم باللغة التي تتناسب مع نوع الإعاقة لديهم.$q$,$q$مساعدة الطلاب ذوي الإعاقة على فهم الدروس والتعليمات التي يقدمها المعلم باللغة التي تتناسب مع نوع الإعاقة لديهم.$q$),
  ((select id from public.guide_jobs where code=$q$sped_teacher_assistant$q$),null,15,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,2,$q$دعم الأهداف التعليمية من خلال الأنشطة المدرسية وتحديد فرص التحسين وتقديم التوصية للمسؤولين.$q$,$q$دعم الأهداف التعليمية من خلال الأنشطة المدرسية وتحديد فرص التحسين وتقديم التوصية للمسؤولين.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,3,$q$تحقيق أهداف ومؤشرات الأداء للأنشطة والفعاليات الرئيسية حسب الخطة التشغيلية للمدرسة.$q$,$q$تحقيق أهداف ومؤشرات الأداء للأنشطة والفعاليات الرئيسية حسب الخطة التشغيلية للمدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,4,$q$تحديد الصعوبات المتعلقة بتنفيذ الأنشطة والبرامج الطلابية ذات العلاقة بالنشاط الطلابي، والعمل على تجاوزها قدر الإمكان (داخل المدرسة)، وطلب الدعم/المشورة عبر إدارة المدرسة من الجهات ذات العلاقة عند الضرورة.$q$,$q$تحديد الصعوبات المتعلقة بتنفيذ الأنشطة والبرامج الطلابية ذات العلاقة بالنشاط الطلابي، والعمل على تجاوزها قدر الإمكان (داخل المدرسة)، وطلب الدعم/المشورة عبر إدارة المدرسة من الجهات ذات العلاقة عند الضرورة.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,5,$q$اكتشاف قدرات وميول واحتياجات الطلاب (غير التعليمية) بكفاءة عالية فيما يتعلق بمجال اختصاصه ومن خلال المعلمين المختصين.$q$,$q$اكتشاف قدرات وميول واحتياجات الطلاب (غير التعليمية) بكفاءة عالية فيما يتعلق بمجال اختصاصه ومن خلال المعلمين المختصين.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,6,$q$الإشراف على تنفيذ الخطة التشغيلية للأنشطة الطلابية والبرامج المعدة لذلك بما فيها حصص النشاط عبر منصة التعليم الإلكتروني والتعليم عن بعد المعتمدة في الوزارة (مدرستي)، بما يتفق مع الأنظمة واللوائح المنظمة لذلك، وتوثيقها، وتفعيل الاستبانات التي تقيس مدى تحقق برامج النشاط وتحليلها.$q$,$q$الإشراف على تنفيذ الخطة التشغيلية للأنشطة الطلابية والبرامج المعدة لذلك بما فيها حصص النشاط عبر منصة التعليم الإلكتروني والتعليم عن بعد المعتمدة في الوزارة (مدرستي)، بما يتفق مع الأنظمة واللوائح المنظمة لذلك، وتوثيقها، وتفعيل الاستبانات التي تقيس مدى تحقق برامج النشاط وتحليلها.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,7,$q$التخطيط للأنشطة والبرامج ذات العلاقة قبل بداية الفصل الدراسي وفق الأسابيع الدراسية المعتمدة، وضمان مناسبتها للمرحلة العمرية المستهدفة، وحسب الإمكانيات والموارد المتاحة وشمولها للجانب التطويري للطلاب.$q$,$q$التخطيط للأنشطة والبرامج ذات العلاقة قبل بداية الفصل الدراسي وفق الأسابيع الدراسية المعتمدة، وضمان مناسبتها للمرحلة العمرية المستهدفة، وحسب الإمكانيات والموارد المتاحة وشمولها للجانب التطويري للطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,8,$q$الإشراف على مشاركة الطلاب في إعداد الخطة التشغيلية للأنشطة الطلابية والبرامج المعدة لذلك.$q$,$q$الإشراف على مشاركة الطلاب في إعداد الخطة التشغيلية للأنشطة الطلابية والبرامج المعدة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,9,$q$تنفيذ أنشطة المدرسة بما يتوافق مع الميزانية المحددة لها من الميزانية التشغيلية وفق المستندات النظامية المنظمة لذلك.$q$,$q$تنفيذ أنشطة المدرسة بما يتوافق مع الميزانية المحددة لها من الميزانية التشغيلية وفق المستندات النظامية المنظمة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,10,$q$المشاركة في تقييم ومتابعة عملية الموافقة على تشكيل الأندية (إن وجدت) والتحقق من تلبيتها لمتطلبات واهتمامات الطلاب.$q$,$q$المشاركة في تقييم ومتابعة عملية الموافقة على تشكيل الأندية (إن وجدت) والتحقق من تلبيتها لمتطلبات واهتمامات الطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,11,$q$تفعيل المشاركات المدرسية والطلابية في المنصات العامة المخصصة لذلك، وتفعيل مشاركة الطلاب في الأنشطة، وتطوير مجموعة واسعة من المهارات الجديدة وذات الصلة تتناسب مع خطة وأهداف الوزارة.$q$,$q$تفعيل المشاركات المدرسية والطلابية في المنصات العامة المخصصة لذلك، وتفعيل مشاركة الطلاب في الأنشطة، وتطوير مجموعة واسعة من المهارات الجديدة وذات الصلة تتناسب مع خطة وأهداف الوزارة.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,12,$q$توجيه بعض برامج النشاط للمعلمين وأولياء الأمور والمجتمع المحلي، وتعزيز العلاقات الإيجابية بين المدرسة والأسرة والمجتمع باعتبارها مؤسسات تربوية تؤثر في الطالب.$q$,$q$توجيه بعض برامج النشاط للمعلمين وأولياء الأمور والمجتمع المحلي، وتعزيز العلاقات الإيجابية بين المدرسة والأسرة والمجتمع باعتبارها مؤسسات تربوية تؤثر في الطالب.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,13,$q$إعداد تقرير يتضمن تفاصيل الأنشطة، والإنجازات والمعوقات أثناء تنفيذ المهام المعينة (أو المطلوبة)، والرفع به لوكيل الشؤون الطلاب .$q$,$q$إعداد تقرير يتضمن تفاصيل الأنشطة، والإنجازات والمعوقات أثناء تنفيذ المهام المعينة (أو المطلوبة)، والرفع به لوكيل الشؤون الطلاب .$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,14,$q$التأكد من تطبيق الاشتراطات النظامية والأمنية قبل تنفيذ برامج النشاط الصفية وغير الصفية.$q$,$q$التأكد من تطبيق الاشتراطات النظامية والأمنية قبل تنفيذ برامج النشاط الصفية وغير الصفية.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,15,$q$تقديم الدعم للمتميزين في برامج النشاط من المعلمين وأولياء الأمور والطلاب والرفع للجنة الإدارية/وكيل المدرسة لشؤون الطلاب ليتم تكريمهم من قبل مدير المدرسة.$q$,$q$تقديم الدعم للمتميزين في برامج النشاط من المعلمين وأولياء الأمور والطلاب والرفع للجنة الإدارية/وكيل المدرسة لشؤون الطلاب ليتم تكريمهم من قبل مدير المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,16,$q$العمل بشكل وثيق مع المعلمين ودعمهم في تنفيذ الأنشطة اللاصفية.$q$,$q$العمل بشكل وثيق مع المعلمين ودعمهم في تنفيذ الأنشطة اللاصفية.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,17,$q$تنسيق جميع الأنشطة اللاصفية في المدرسة، وتوفير أساسياتها ذات الصلة، ومرافق التدريب والتوجيه لضمان إعطاء فرص متكافئة للطلبة حسب الميول والقدرات.$q$,$q$تنسيق جميع الأنشطة اللاصفية في المدرسة، وتوفير أساسياتها ذات الصلة، ومرافق التدريب والتوجيه لضمان إعطاء فرص متكافئة للطلبة حسب الميول والقدرات.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,18,$q$توجيه تنظيم الأحداث المدرسية للأنشطة والبطولات من أجل رفع مستوى المشاركة والاهتمام بالأنشطة بين الطلاب.$q$,$q$توجيه تنظيم الأحداث المدرسية للأنشطة والبطولات من أجل رفع مستوى المشاركة والاهتمام بالأنشطة بين الطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,19,$q$التواصل مع المدارس الأخرى في المنطقة عبر طرق التواصل المعتمدة للمشاركة في الأحداث الرياضية المدرسية، بعد موافقة مدير المدرسة.$q$,$q$التواصل مع المدارس الأخرى في المنطقة عبر طرق التواصل المعتمدة للمشاركة في الأحداث الرياضية المدرسية، بعد موافقة مدير المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,20,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وحضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته وشغل حصص الإنتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وحضور الاصطفاف الصباحي والتأكيد على تفعيل الإذاعة المدرسية ونشيد العلم وتحيته وشغل حصص الإنتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,21,$q$متابعة وتقييم كافة البرامج بدقة والحرص على عدم احتوائها على ما يخالف التعليمات.$q$,$q$متابعة وتقييم كافة البرامج بدقة والحرص على عدم احتوائها على ما يخالف التعليمات.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,22,$q$تفعيل دليل الشراكات وفق الدليل المنظم لذلك.$q$,$q$تفعيل دليل الشراكات وفق الدليل المنظم لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,23,$q$تأصيل حب التطوع في نفوس الطلاب، وابتكار واستحداث مجالات ونشاطات تطوعية مع الطلبة لخدمة المجتمع.$q$,$q$تأصيل حب التطوع في نفوس الطلاب، وابتكار واستحداث مجالات ونشاطات تطوعية مع الطلبة لخدمة المجتمع.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,24,$q$العمل على تأهيل الطالب للمسابقات والمشاركات الوطنية والإقليمية والدولية، والاستعانة بالجهات ذات الاختصاص للمساعدة في ذلك.$q$,$q$العمل على تأهيل الطالب للمسابقات والمشاركات الوطنية والإقليمية والدولية، والاستعانة بالجهات ذات الاختصاص للمساعدة في ذلك.$q$),
  ((select id from public.guide_jobs where code=$q$activity_leader$q$),null,25,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,2,$q$إعداد الخطة السنوية للتوجيه الطلابي في المدرسة، وفقاً لما هو معتمد لذلك، وتوزيع الأسابيع الدراسية مع مراعاة تفعيلها وتنفيذها حسب التعاميم المنظمة لذلك.$q$,$q$إعداد الخطة السنوية للتوجيه الطلابي في المدرسة، وفقاً لما هو معتمد لذلك، وتوزيع الأسابيع الدراسية مع مراعاة تفعيلها وتنفيذها حسب التعاميم المنظمة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,3,$q$حصر ومتابعة المشكلات السلوكية والحالات الخاصة (تربوية –نفسية-اجتماعية). وتخطيط التدخلات التربوية المناسبة.$q$,$q$حصر ومتابعة المشكلات السلوكية والحالات الخاصة (تربوية –نفسية-اجتماعية). وتخطيط التدخلات التربوية المناسبة.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,4,$q$متابعة حالات الطلاب متكرري الغياب والتأخر الصباحي، والتأخر نهاية اليوم الدراسي، واتخاذ الإجراءات التصحيحية اللازمة، بالتنسيق مع وكيل شؤون الطلاب.$q$,$q$متابعة حالات الطلاب متكرري الغياب والتأخر الصباحي، والتأخر نهاية اليوم الدراسي، واتخاذ الإجراءات التصحيحية اللازمة، بالتنسيق مع وكيل شؤون الطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,5,$q$متابعة مستويات الطلاب التحصيلية (المعيدين والمتأخرين دراسياً ومتكرري الرسوب) والمساهمة في تحسين أداء الطلاب وزيادة نواتج تعلمهم من خلال وضع البرامج المحفزة والعلاجية المناسبة لهم بعد دراسة وتحليل وتفسير نتائج كل فترة مع وجود مقارنة مجدولة قبل وبعد البرنامج العلاجي.$q$,$q$متابعة مستويات الطلاب التحصيلية (المعيدين والمتأخرين دراسياً ومتكرري الرسوب) والمساهمة في تحسين أداء الطلاب وزيادة نواتج تعلمهم من خلال وضع البرامج المحفزة والعلاجية المناسبة لهم بعد دراسة وتحليل وتفسير نتائج كل فترة مع وجود مقارنة مجدولة قبل وبعد البرنامج العلاجي.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,6,$q$متابعة التحسن في نواتج تعلم الطلاب المعيدين والمتأخرين دراسيا ومتكرري الرسوب، لمعرفة جدوى الإجراءات المتخذة، وتقديم التقارير إلى لجنة التحصيل الدراسي بالتنسيق مع معلمي المواد.$q$,$q$متابعة التحسن في نواتج تعلم الطلاب المعيدين والمتأخرين دراسيا ومتكرري الرسوب، لمعرفة جدوى الإجراءات المتخذة، وتقديم التقارير إلى لجنة التحصيل الدراسي بالتنسيق مع معلمي المواد.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,7,$q$تفعيل برامج التوجيه الطلابي الوزارية في مستوياتها (الإنمائية والوقائية والعلاجية) وبرامج الخطة التشغيلية لإدارة التعليم، بما يتواءم مع واقع تشخيص المدرسة، والعمل على تطويرها وتفعيل البرامج التثقيفية للطلاب للتعريف بمهارات المستقبل ومتطلباته.$q$,$q$تفعيل برامج التوجيه الطلابي الوزارية في مستوياتها (الإنمائية والوقائية والعلاجية) وبرامج الخطة التشغيلية لإدارة التعليم، بما يتواءم مع واقع تشخيص المدرسة، والعمل على تطويرها وتفعيل البرامج التثقيفية للطلاب للتعريف بمهارات المستقبل ومتطلباته.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,8,$q$دراسة حالات الطلاب المعيدين والمتأخرين دراسياً ومتكرري الرسوب، واقتراح الإجراءات المناسبة بالتنسيق مع معلمي المواد، وتقديم تقرير إلى لجنة التحصيل الدراسي لإقرار التوصيات المناسبة، ومتابعة تنفيذ التوصيات بعد اعتمادها من مدير المدرسة.$q$,$q$دراسة حالات الطلاب المعيدين والمتأخرين دراسياً ومتكرري الرسوب، واقتراح الإجراءات المناسبة بالتنسيق مع معلمي المواد، وتقديم تقرير إلى لجنة التحصيل الدراسي لإقرار التوصيات المناسبة، ومتابعة تنفيذ التوصيات بعد اعتمادها من مدير المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,9,$q$تفعيل قرارات وتوصيات لجنة التوجيه الطلابي في المدرسة ومتابعة تنفيذها.$q$,$q$تفعيل قرارات وتوصيات لجنة التوجيه الطلابي في المدرسة ومتابعة تنفيذها.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,10,$q$تفعيل المجلس الطلابي وفق الأدلة المنظمة لذلك.$q$,$q$تفعيل المجلس الطلابي وفق الأدلة المنظمة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,11,$q$عقد جلسات توجيه فردي وجمعي مع فتح ملفات دراسة حالة فردية أكثر تفصيلاً إذا لزم الأمر.$q$,$q$عقد جلسات توجيه فردي وجمعي مع فتح ملفات دراسة حالة فردية أكثر تفصيلاً إذا لزم الأمر.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,12,$q$تقديم التوجيه الجمعي لعموم الطلاب فيما يتعلق بالقضايا الاجتماعية الهامة بالتعاون مع المعلمين وأولياء الأمور.$q$,$q$تقديم التوجيه الجمعي لعموم الطلاب فيما يتعلق بالقضايا الاجتماعية الهامة بالتعاون مع المعلمين وأولياء الأمور.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,13,$q$تعريف الطلبة بسوق العمل ومتطلباته ومساعدتهم على تحديد أهدافهم المهنية المستقبلية وإعدادهم لسوق العمل من خلال تطوير مهاراتهم الشخصية والمهنية بما يتناسب مع المرحلة الدراسية وتفعيل المناشط والمناسبات المرتبطة بها.$q$,$q$تعريف الطلبة بسوق العمل ومتطلباته ومساعدتهم على تحديد أهدافهم المهنية المستقبلية وإعدادهم لسوق العمل من خلال تطوير مهاراتهم الشخصية والمهنية بما يتناسب مع المرحلة الدراسية وتفعيل المناشط والمناسبات المرتبطة بها.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,14,$q$الاستفادة من الأنشطة المدرسية بما يخدم عملية التوجيه الطلابي.$q$,$q$الاستفادة من الأنشطة المدرسية بما يخدم عملية التوجيه الطلابي.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,15,$q$الإشراف على الطلاب ومرافقتهم إلى المعارض المهنية والمؤتمرات الدولية وتقديم التوجيه ما أمكن.$q$,$q$الإشراف على الطلاب ومرافقتهم إلى المعارض المهنية والمؤتمرات الدولية وتقديم التوجيه ما أمكن.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,16,$q$إدارة وتنظيم لقاءات أولياء أمور الطلاب وإعداد مجالس أولياء الأمور بالتنسيق مع وكيل شؤون الطلاب وأصحاب العلاقة والمشاركة في فعاليات شراكة المدرسة مع الاسرة.$q$,$q$إدارة وتنظيم لقاءات أولياء أمور الطلاب وإعداد مجالس أولياء الأمور بالتنسيق مع وكيل شؤون الطلاب وأصحاب العلاقة والمشاركة في فعاليات شراكة المدرسة مع الاسرة.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,17,$q$تعزيز الصحة النفسية لدى الطلاب بكافة الوسائل والأساليب الإرشادية المتاحة، بمشاركة الموجه الصحي.$q$,$q$تعزيز الصحة النفسية لدى الطلاب بكافة الوسائل والأساليب الإرشادية المتاحة، بمشاركة الموجه الصحي.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,18,$q$اكتشاف قدرات وميول الطلاب وتنميتها وتوجيههم للتخصصات المناسبة لهم وتنمية الاتجاه الإيجابي لهم نحو المهن، بالتنسيق مع معلم الموهوبين (إن وجد).$q$,$q$اكتشاف قدرات وميول الطلاب وتنميتها وتوجيههم للتخصصات المناسبة لهم وتنمية الاتجاه الإيجابي لهم نحو المهن، بالتنسيق مع معلم الموهوبين (إن وجد).$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,19,$q$تفعيل قنوات التعليم الإلكتروني المعتمدة في تطبيق ممارسات التوجيه الطلابي بكافة جوانبها التربوية والنفسية والاجتماعية وغيرها بما يتناسب مع احتياجات الطلاب ويسهم في رفع جودة نواتج التعلم السلوكية.$q$,$q$تفعيل قنوات التعليم الإلكتروني المعتمدة في تطبيق ممارسات التوجيه الطلابي بكافة جوانبها التربوية والنفسية والاجتماعية وغيرها بما يتناسب مع احتياجات الطلاب ويسهم في رفع جودة نواتج التعلم السلوكية.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,20,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته وشغل حصص الإنتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته وشغل حصص الإنتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,21,$q$تنظيم برنامج استقبال الطلاب المستجدين في المرحلة الابتدائية وبرنامج التهيئة الارشادية في الصفوف والمراحل الانتقالية وللطلبة المنتقلين للمدرسة.$q$,$q$تنظيم برنامج استقبال الطلاب المستجدين في المرحلة الابتدائية وبرنامج التهيئة الارشادية في الصفوف والمراحل الانتقالية وللطلبة المنتقلين للمدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,22,$q$تعريف الطلاب باختبارات قياس والاختبارات التحصيلية وتهيئتهم للاستعداد لها.$q$,$q$تعريف الطلاب باختبارات قياس والاختبارات التحصيلية وتهيئتهم للاستعداد لها.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,23,$q$توعية منسوبي المدرسة بخصائص نمو الطلاب ومراعاة احتياجاتهم ومطالب نموهم في المجتمع المدرسي والمحلي، بمشاركة الموجه الصحي.$q$,$q$توعية منسوبي المدرسة بخصائص نمو الطلاب ومراعاة احتياجاتهم ومطالب نموهم في المجتمع المدرسي والمحلي، بمشاركة الموجه الصحي.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,24,$q$رعاية الطلاب المتفوقين دراسياً والمتميزين سلوكياً والرفع لتكريمهم من قبل مدير المدرسة وفق الأنظمة المعدة لذلك، بالتنسيق مع معلم الموهوبين(إن وجد).$q$,$q$رعاية الطلاب المتفوقين دراسياً والمتميزين سلوكياً والرفع لتكريمهم من قبل مدير المدرسة وفق الأنظمة المعدة لذلك، بالتنسيق مع معلم الموهوبين(إن وجد).$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,25,$q$تطبيق فنيات التوجيه النفسي وأساليب تعديل السلوك لمساعدة الطلاب الذين لديهم مشكلات سلوكية ومراعاة خصائص نمو الطلاب واحتياجاتهم ومطالب نموهم.$q$,$q$تطبيق فنيات التوجيه النفسي وأساليب تعديل السلوك لمساعدة الطلاب الذين لديهم مشكلات سلوكية ومراعاة خصائص نمو الطلاب واحتياجاتهم ومطالب نموهم.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,26,$q$إعداد التقرير الختامي للبرامج والخدمات التوجيهية متضمناً التقويم والمرئيات حول الخدمات المقدمة، ورفعها للجنة التوجيه الطلابي.$q$,$q$إعداد التقرير الختامي للبرامج والخدمات التوجيهية متضمناً التقويم والمرئيات حول الخدمات المقدمة، ورفعها للجنة التوجيه الطلابي.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,27,$q$رفع وتوثيق أعمال وبرامج وخدمات رعاية الطلاب ودعمهم على برنامج نور.$q$,$q$رفع وتوثيق أعمال وبرامج وخدمات رعاية الطلاب ودعمهم على برنامج نور.$q$),
  ((select id from public.guide_jobs where code=$q$student_counselor$q$),null,28,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$,$q$القيام بأي مهام أخرى يكلف بها تتناسب مع مهامه / مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,2,$q$إعداد خطة الصحة المدرسية وتنفيذ البرامج والمناسبات الصحية المعتمدة في خطة الشؤون الصحية المدرسية وتسجيل متطلباتها والتقارير اللازمة لها في حساب الموجه الصحي على نظام نور.$q$,$q$إعداد خطة الصحة المدرسية وتنفيذ البرامج والمناسبات الصحية المعتمدة في خطة الشؤون الصحية المدرسية وتسجيل متطلباتها والتقارير اللازمة لها في حساب الموجه الصحي على نظام نور.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,3,$q$التوعية الصحية والتثقيف الصحي في المجتمع المدرسي، وتفعيل التوصيات المتعلقة بالصحة المدرسية في المدرسة.$q$,$q$التوعية الصحية والتثقيف الصحي في المجتمع المدرسي، وتفعيل التوصيات المتعلقة بالصحة المدرسية في المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,4,$q$تلقي ملاحظات منسوبي المدرسة عن المشكلات الصحية لدى الطلاب أو في البيئة المدرسية والتنسيق لاتخاذ الإجراء المناسب تجاهها.$q$,$q$تلقي ملاحظات منسوبي المدرسة عن المشكلات الصحية لدى الطلاب أو في البيئة المدرسية والتنسيق لاتخاذ الإجراء المناسب تجاهها.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,5,$q$الإشراف على عمل الإسعافات الأولية للحالات الطارئة في المدرسة قبل وصول المختصين.$q$,$q$الإشراف على عمل الإسعافات الأولية للحالات الطارئة في المدرسة قبل وصول المختصين.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,6,$q$تنفيذ التعليمات والتعاميم والخطط من مشرف الشؤون الصحية وإعداد الخطوات التنفيذية لها، ورفع التقارير الدورية له.$q$,$q$تنفيذ التعليمات والتعاميم والخطط من مشرف الشؤون الصحية وإعداد الخطوات التنفيذية لها، ورفع التقارير الدورية له.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,7,$q$مساعدة ممرض المدرسة (إن وجد) في متابعة الحالة الصحية للطلاب ومتابعة السجلات الصحية للطلاب على (النظام الإلكتروني) ومتابعة المحالين بأعراض مرضية للمركز الصحي.$q$,$q$مساعدة ممرض المدرسة (إن وجد) في متابعة الحالة الصحية للطلاب ومتابعة السجلات الصحية للطلاب على (النظام الإلكتروني) ومتابعة المحالين بأعراض مرضية للمركز الصحي.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,8,$q$مشاركة ممرض المدرسة (إن وجد) في تنفيذ البرامج الصحية بالمدرسة.$q$,$q$مشاركة ممرض المدرسة (إن وجد) في تنفيذ البرامج الصحية بالمدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,9,$q$تفقد البيئة الصحية المدرسية.$q$,$q$تفقد البيئة الصحية المدرسية.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,10,$q$التعاون مع منسوبي المدرسة في تفقد النظافة الشخصية للطلاب ومتابعة سلوكياتهم الصحية والعمل على تعديلها.$q$,$q$التعاون مع منسوبي المدرسة في تفقد النظافة الشخصية للطلاب ومتابعة سلوكياتهم الصحية والعمل على تعديلها.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,11,$q$المساهمة مع الموجه الطلابي في توعية منسوبي المدرسة بخصائص نمو الطلاب ومراعاة احتياجاتهم ومطالب نموهم في المجتمع المدرسي والمحلي.$q$,$q$المساهمة مع الموجه الطلابي في توعية منسوبي المدرسة بخصائص نمو الطلاب ومراعاة احتياجاتهم ومطالب نموهم في المجتمع المدرسي والمحلي.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,12,$q$حصر ودراسة ومتابعة حالات الطلاب الصحية، وتقديم الخدمات المناسبة لهم من بداية العام الدراسي.$q$,$q$حصر ودراسة ومتابعة حالات الطلاب الصحية، وتقديم الخدمات المناسبة لهم من بداية العام الدراسي.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,13,$q$إعداد التقرير الختامي للبرامج والخدمات الصحية في ضوء خطة الصحة المدرسية المعتمدة متضمناً التقويم والمرئيات حول الخدمات المقدمة.$q$,$q$إعداد التقرير الختامي للبرامج والخدمات الصحية في ضوء خطة الصحة المدرسية المعتمدة متضمناً التقويم والمرئيات حول الخدمات المقدمة.$q$),
  ((select id from public.guide_jobs where code=$q$health_counselor$q$),null,14,$q$القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,2,$q$تحديد وتقديم المقترحات التطويرية لوكيل شؤون الطلاب ولمقدم خدمات دعم التميز المدرسي على مصادر التعلم/المعامل لتحقيق ودعم أهداف المدرسة.$q$,$q$تحديد وتقديم المقترحات التطويرية لوكيل شؤون الطلاب ولمقدم خدمات دعم التميز المدرسي على مصادر التعلم/المعامل لتحقيق ودعم أهداف المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,3,$q$تحقيق أهداف ومؤشرات الأداء حسب مهامه ومسؤولياته على المصادر/المعامل.$q$,$q$تحقيق أهداف ومؤشرات الأداء حسب مهامه ومسؤولياته على المصادر/المعامل.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,4,$q$تحديد المشكلات والبحث عن الحلول والدعم من الجهات المختصة عند اللزوم.$q$,$q$تحديد المشكلات والبحث عن الحلول والدعم من الجهات المختصة عند اللزوم.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,5,$q$المشاركة في تفعيل المناسبات الثقافية والتربوية والوطنية وتنمية الاعتزاز بالدين والولاء للملك والانتماء للوطن.$q$,$q$المشاركة في تفعيل المناسبات الثقافية والتربوية والوطنية وتنمية الاعتزاز بالدين والولاء للملك والانتماء للوطن.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,6,$q$تطوير الخطط والإجراءات للاستفادة من المصادر/المعامل في تحقيق الأهداف العامة من التعليم والتعلم.$q$,$q$تطوير الخطط والإجراءات للاستفادة من المصادر/المعامل في تحقيق الأهداف العامة من التعليم والتعلم.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,7,$q$تفعيل إجراءات نظام إعارة وترجيع مكونات المصادر المدرسية لضمان جودة وكفاءة ومعايير الخدمات المقدمة.$q$,$q$تفعيل إجراءات نظام إعارة وترجيع مكونات المصادر المدرسية لضمان جودة وكفاءة ومعايير الخدمات المقدمة.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,8,$q$تدريب المستفيدين من مصادر التعلم على أفضل الطرق للاستخدام الأمثل لمرافق المصادر/المعامل المدرسية من أجل المحافظة على مستلزماتها ومرافقها مع توفير البيئة المكانية المناسبة.$q$,$q$تدريب المستفيدين من مصادر التعلم على أفضل الطرق للاستخدام الأمثل لمرافق المصادر/المعامل المدرسية من أجل المحافظة على مستلزماتها ومرافقها مع توفير البيئة المكانية المناسبة.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,9,$q$إعداد خطة عامة وجدول عمل يومي أو أسبوعي خاص بمصادر التعلم/المعامل.$q$,$q$إعداد خطة عامة وجدول عمل يومي أو أسبوعي خاص بمصادر التعلم/المعامل.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,10,$q$الاتصال مع المستفيدين في المدرسة من أجل توفير جميع المتطلبات الخاصة باستخدام غرفة مصادر التعلم، وتحديد الاحتياجات مثل الكتب ، مجلات ، دوريات وأي خدمات أخرى مثل أجهزة عرض وشبكة اتصال حاسوبية وما إلى ذلك.$q$,$q$الاتصال مع المستفيدين في المدرسة من أجل توفير جميع المتطلبات الخاصة باستخدام غرفة مصادر التعلم، وتحديد الاحتياجات مثل الكتب ، مجلات ، دوريات وأي خدمات أخرى مثل أجهزة عرض وشبكة اتصال حاسوبية وما إلى ذلك.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,11,$q$العمل على إيصال أدوات المصادر/أجهزة المعامل من خلال المشاركة في مراجعة وتسليم الطلبات الخاصة بالمصادر/أجهزة المعامل واستلامها.$q$,$q$العمل على إيصال أدوات المصادر/أجهزة المعامل من خلال المشاركة في مراجعة وتسليم الطلبات الخاصة بالمصادر/أجهزة المعامل واستلامها.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,12,$q$التأكد بأن جميع المواد والمحتوى المعرفي المتوفر بالمصادر متوافق مع الشروط والأنظمة واللوائح المنظمة لذلك من حيث مناسبته للفئة العمرية للطلاب وثقافة المملكة العربية السعودية.$q$,$q$التأكد بأن جميع المواد والمحتوى المعرفي المتوفر بالمصادر متوافق مع الشروط والأنظمة واللوائح المنظمة لذلك من حيث مناسبته للفئة العمرية للطلاب وثقافة المملكة العربية السعودية.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,13,$q$إدارة إجراءات استعارة الكتب وإعادتها، وارسال رسائل تذكيريه للمتأخرين لضمان التزام الجميع بسياسات وإجراءات المصادر.$q$,$q$إدارة إجراءات استعارة الكتب وإعادتها، وارسال رسائل تذكيريه للمتأخرين لضمان التزام الجميع بسياسات وإجراءات المصادر.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,14,$q$إدارة وتنظيم وترتيب وترميز وتصنيف موارد المعلومات الالكترونية والمطبوعة على حد سواء. وإدخالها في النظام المخصص لذلك وفهرسة وتصنيف المواد والكتب ومصادر التعلم المختلفة الخاصة بالمكتبة، لتسهيل عملية تداولها والوصول إليها، وإدارة عملية إعارتها.$q$,$q$إدارة وتنظيم وترتيب وترميز وتصنيف موارد المعلومات الالكترونية والمطبوعة على حد سواء. وإدخالها في النظام المخصص لذلك وفهرسة وتصنيف المواد والكتب ومصادر التعلم المختلفة الخاصة بالمكتبة، لتسهيل عملية تداولها والوصول إليها، وإدارة عملية إعارتها.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,15,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته وشغل حصص الإنتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته وشغل حصص الإنتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,16,$q$مساعدة المعلمين والطلاب في المعمل (عند الحاجة) إذا تطلب الأمر.$q$,$q$مساعدة المعلمين والطلاب في المعمل (عند الحاجة) إذا تطلب الأمر.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,17,$q$تهيئة وتجهيز المعامل والتأكد من جاهزيتها وتنظيمها وترتيبها ومتابعة نظافتها قبل وبعد استخدامها.$q$,$q$تهيئة وتجهيز المعامل والتأكد من جاهزيتها وتنظيمها وترتيبها ومتابعة نظافتها قبل وبعد استخدامها.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,18,$q$القدرة على تحديد المشاكل وطلب الدعم/المشورة من الأطراف المعنية عند الضرورة في مجال عمله وتخصصه.$q$,$q$القدرة على تحديد المشاكل وطلب الدعم/المشورة من الأطراف المعنية عند الضرورة في مجال عمله وتخصصه.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,19,$q$استكشاف أخطاء الأجهزة والمواد التعليمية وإصلاحها قدر المستطاع عند وجود مسائل أو مشكلات فنية متعلقة بها من أجل تحديد وإجراء الحلول المناسبة.$q$,$q$استكشاف أخطاء الأجهزة والمواد التعليمية وإصلاحها قدر المستطاع عند وجود مسائل أو مشكلات فنية متعلقة بها من أجل تحديد وإجراء الحلول المناسبة.$q$),
  ((select id from public.guide_jobs where code=$q$learning_resources_keeper$q$),null,20,$q$القيام بأي مهام يكلف بها من المسؤول المباشر يتناسب مع مهامه/مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من المسؤول المباشر يتناسب مع مهامه/مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,2,$q$دعم أهداف المدرسة من خلال توفير بيئة مختبرية آمنة وتحديد فرص التحسين وتقديم التوصية بذلك لوكيل الشؤون المدرسية ولمقدم خدمات دعم التميز المدرسي.$q$,$q$دعم أهداف المدرسة من خلال توفير بيئة مختبرية آمنة وتحديد فرص التحسين وتقديم التوصية بذلك لوكيل الشؤون المدرسية ولمقدم خدمات دعم التميز المدرسي.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,3,$q$تحقيق الأهداف ومؤشرات الأداء الرئيسة حسب مهامه ومسؤولياته.$q$,$q$تحقيق الأهداف ومؤشرات الأداء الرئيسة حسب مهامه ومسؤولياته.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,4,$q$القدرة على تحديد المشاكل وطلب الدعم/المشورة من الأطراف المعنية عند الضرورة في مجال عمله وتخصصه.$q$,$q$القدرة على تحديد المشاكل وطلب الدعم/المشورة من الأطراف المعنية عند الضرورة في مجال عمله وتخصصه.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,5,$q$إعداد وتنظيم الأجهزة والمواد التعليمية كما هو متطلب للدروس.$q$,$q$إعداد وتنظيم الأجهزة والمواد التعليمية كما هو متطلب للدروس.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,6,$q$تهيئة وتجهيز المختبرات وتنظيمها وترتيبها ، ومتابعة نظافتها قبل وبعد استخدامها.$q$,$q$تهيئة وتجهيز المختبرات وتنظيمها وترتيبها ، ومتابعة نظافتها قبل وبعد استخدامها.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,7,$q$ضمان تجهيز وتسليم الأجهزة المطلوبة من قبل المعلمين ووضعها في المكان المخصص.$q$,$q$ضمان تجهيز وتسليم الأجهزة المطلوبة من قبل المعلمين ووضعها في المكان المخصص.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,8,$q$ترتيب وتنظيف الأجهزة عند الانتهاء من استعمالها وتخزينها بصورة سليمة وآمنة.$q$,$q$ترتيب وتنظيف الأجهزة عند الانتهاء من استعمالها وتخزينها بصورة سليمة وآمنة.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,9,$q$الحفاظ على الأجهزة والمواد التعليمية، وتخزينها بشكل صحيح، وإجراء إصلاحات بسيطة إن كان ذلك ممكنًا، وترتيب المواد الكيميائية بطريقة منظمة وآمنة.$q$,$q$الحفاظ على الأجهزة والمواد التعليمية، وتخزينها بشكل صحيح، وإجراء إصلاحات بسيطة إن كان ذلك ممكنًا، وترتيب المواد الكيميائية بطريقة منظمة وآمنة.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,10,$q$إعداد برنامج متكامل لنشاط المختبرات حسب اليوم والحصة والموضوع مع جدول متابعة تنفيذ التجارب للمعلم.$q$,$q$إعداد برنامج متكامل لنشاط المختبرات حسب اليوم والحصة والموضوع مع جدول متابعة تنفيذ التجارب للمعلم.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,11,$q$مساعدة المعلمين والطلاب في المختبر (عند الحاجة) إذا تطلب الأمر.$q$,$q$مساعدة المعلمين والطلاب في المختبر (عند الحاجة) إذا تطلب الأمر.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,12,$q$إعداد اللوحات والنشرات الإرشادية باستخدام الأدوات والأجهزة والمواد في المعامل والمختبرات، ومراجعة فحوصات المخزون بشكل منتظم .$q$,$q$إعداد اللوحات والنشرات الإرشادية باستخدام الأدوات والأجهزة والمواد في المعامل والمختبرات، ومراجعة فحوصات المخزون بشكل منتظم .$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,13,$q$استكشاف مشاكل الأجهزة والمواد التعليمية والعمل على إصلاحها ومعالجتها قدر الإمكان، والتواصل مع الجهات ذات الاختصاص عند العجز عن ذلك.$q$,$q$استكشاف مشاكل الأجهزة والمواد التعليمية والعمل على إصلاحها ومعالجتها قدر الإمكان، والتواصل مع الجهات ذات الاختصاص عند العجز عن ذلك.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,14,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وحضور الاصطفاف الصباحي وتفعيل نشيد العلم وتحيته وشغل حصص الانتظار وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,15,$q$حفظ المواد الكيميائية/ والأجهزة في الأماكن المخصصة لها، والتأكد من مدى سلامة حفظها ومتابعة صلاحية انتهائها (للمواد الكيميائية).$q$,$q$حفظ المواد الكيميائية/ والأجهزة في الأماكن المخصصة لها، والتأكد من مدى سلامة حفظها ومتابعة صلاحية انتهائها (للمواد الكيميائية).$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,16,$q$المساهمة في تنفيذ أنشطة المدرسة المتعلقة بتخصص عمله وفق إمكاناتها.$q$,$q$المساهمة في تنفيذ أنشطة المدرسة المتعلقة بتخصص عمله وفق إمكاناتها.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,17,$q$إعداد تقرير يتضمن تفاصيل الأنشطة، والإنجازات والمعوقات أثناء تنفيذ المهام المطلوبة.$q$,$q$إعداد تقرير يتضمن تفاصيل الأنشطة، والإنجازات والمعوقات أثناء تنفيذ المهام المطلوبة.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,18,$q$الالتزام بكافة إجراءات السلامة في المختبر ومتابعة تنفيذها.$q$,$q$الالتزام بكافة إجراءات السلامة في المختبر ومتابعة تنفيذها.$q$),
  ((select id from public.guide_jobs where code=$q$lab_technician$q$),null,19,$q$القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من المسؤول المباشر بما يتناسب مع مهامه/مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,2,$q$أداء المهام والأنشطة المكتبية والإدارية الأساسية والسكرتارية للمدرسة وتنفيذ توجيهات المدير /الوكيل وتعليماته بشأنها. كتنسيق الملفات، وتصوير الأوراق، وإدخال واسترجاع البيانات والوثائق ومعالجة وتحرير النصوص.$q$,$q$أداء المهام والأنشطة المكتبية والإدارية الأساسية والسكرتارية للمدرسة وتنفيذ توجيهات المدير /الوكيل وتعليماته بشأنها. كتنسيق الملفات، وتصوير الأوراق، وإدخال واسترجاع البيانات والوثائق ومعالجة وتحرير النصوص.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,3,$q$أداء مهام الاتصالات الإدارية وإرسال واستلام الرسائل والطرود وفرزها وتوجيهها إلى الشخص المعني، وفقًا لتوجيهات المدير/الوكيل.$q$,$q$أداء مهام الاتصالات الإدارية وإرسال واستلام الرسائل والطرود وفرزها وتوجيهها إلى الشخص المعني، وفقًا لتوجيهات المدير/الوكيل.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,4,$q$تبليغ ما يصدر من المدير / الوكيل من تعليمات لموظفي المدرسة.$q$,$q$تبليغ ما يصدر من المدير / الوكيل من تعليمات لموظفي المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,5,$q$تقديم الدعم للعمليات المدرسية التنظيمية والإدارية اليومية متى ما تطلب ذلك.$q$,$q$تقديم الدعم للعمليات المدرسية التنظيمية والإدارية اليومية متى ما تطلب ذلك.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,6,$q$تنظيم اجتماعات المدرسة/اللجنة وإدارة وتوثيق محاضرها، حسب توجيه المدير/الوكيل.$q$,$q$تنظيم اجتماعات المدرسة/اللجنة وإدارة وتوثيق محاضرها، حسب توجيه المدير/الوكيل.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,7,$q$إعداد جداول الأعمال ونشرها وفقًا للتوجيهات من المدير / الوكيل.$q$,$q$إعداد جداول الأعمال ونشرها وفقًا للتوجيهات من المدير / الوكيل.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,8,$q$المساعدة في جمع وتنظيم المعلومات وإعداد التقارير وفق توجيه المدير/الوكيل.$q$,$q$المساعدة في جمع وتنظيم المعلومات وإعداد التقارير وفق توجيه المدير/الوكيل.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,9,$q$إعداد التقارير الكترونيا وورقيا وفق توجيه رئيسه المباشر.$q$,$q$إعداد التقارير الكترونيا وورقيا وفق توجيه رئيسه المباشر.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,10,$q$استلام وتجهيز ملفات الطلاب المستجدين والمنقولين من المدرسة وإليها، وإنهاء جميع المخاطبات والإجراءات، وتنظيم ملفات الطلاب والحرص على اكتمال جميع الوثائق المطلوبة.$q$,$q$استلام وتجهيز ملفات الطلاب المستجدين والمنقولين من المدرسة وإليها، وإنهاء جميع المخاطبات والإجراءات، وتنظيم ملفات الطلاب والحرص على اكتمال جميع الوثائق المطلوبة.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,11,$q$تسجيل وتسليم العهد لجميع العاملين في المدرسة واستلامها بنهاية العام الدراسي، وتنظيم ملفاتهم وتزويدها بجميع المستجدات التي تطرأ على الموظفين.$q$,$q$تسجيل وتسليم العهد لجميع العاملين في المدرسة واستلامها بنهاية العام الدراسي، وتنظيم ملفاتهم وتزويدها بجميع المستجدات التي تطرأ على الموظفين.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,12,$q$القيام بأخذ حضور وتأخر وغياب الطلاب عن المدرسة.$q$,$q$القيام بأخذ حضور وتأخر وغياب الطلاب عن المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,13,$q$إدارة وتنظيم أعمال مستودع المدرسة، واستلام وحفظ المواد والتجهيزات والكتب المدرسية في الأماكن المخصصة لذلك.$q$,$q$إدارة وتنظيم أعمال مستودع المدرسة، واستلام وحفظ المواد والتجهيزات والكتب المدرسية في الأماكن المخصصة لذلك.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,14,$q$التواصل مع أولياء أمور الطلاب باستخدام الوسائل المتاحة في حال تأخر وغياب الطلاب عن المدرسة.$q$,$q$التواصل مع أولياء أمور الطلاب باستخدام الوسائل المتاحة في حال تأخر وغياب الطلاب عن المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,15,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$,$q$القيام بأعمال المناوبة والإشراف اليومي على الطلاب بداية الدوام الرسمي قبل الاصطفاف الصباحي وبعد نهايته وفق الجدول المعد من قبل اللجنة الإدارية والمعتمد من مدير المدرسة ، و بما لا يزيد في مجموعه الأسبوعي مع ساعات الدوام الرسمي عن 35 ساعة في الأسبوع.$q$),
  ((select id from public.guide_jobs where code=$q$admin_assistant$q$),null,16,$q$القيام بأي مهام يكلف بها من المسؤول المباشر تتناسب مع مهامه/مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من المسؤول المباشر تتناسب مع مهامه/مؤهلاته.$q$);
