  ((select id from public.guide_jobs where code=$q$registrar$q$),null,6,$q$تجهيز البيانات المتعلقة بأسماء الطلاب الخريجين من المدرسة إلكترونياً.$q$,$q$تجهيز البيانات المتعلقة بأسماء الطلاب الخريجين من المدرسة إلكترونياً.$q$),
  ((select id from public.guide_jobs where code=$q$registrar$q$),null,7,$q$تحديث المعلومات والبيانات المتعلقة بالمدرسة إلكترونياً.$q$,$q$تحديث المعلومات والبيانات المتعلقة بالمدرسة إلكترونياً.$q$),
  ((select id from public.guide_jobs where code=$q$registrar$q$),null,8,$q$طباعة بيانات تسجيل الطلاب المستجدين في المرحلة الابتدائية ورياض الأطفال ومعالجة أي خلل يطرأ أثناء التسجيل.$q$,$q$طباعة بيانات تسجيل الطلاب المستجدين في المرحلة الابتدائية ورياض الأطفال ومعالجة أي خلل يطرأ أثناء التسجيل.$q$),
  ((select id from public.guide_jobs where code=$q$registrar$q$),null,9,$q$القيام باستخراج النتائج والإحصائيات والبيانات المتعلقة بالمدرسة إلكترونياً.$q$,$q$القيام باستخراج النتائج والإحصائيات والبيانات المتعلقة بالمدرسة إلكترونياً.$q$),
  ((select id from public.guide_jobs where code=$q$registrar$q$),null,10,$q$القيام بمتابعة كافة المتطلبات اللازمة لجهاز الحاسب الآلي والتنسيق مع المركز الوطني للمعلومات التربوية للاستفادة من الخدمات التي يقدمها.$q$,$q$القيام بمتابعة كافة المتطلبات اللازمة لجهاز الحاسب الآلي والتنسيق مع المركز الوطني للمعلومات التربوية للاستفادة من الخدمات التي يقدمها.$q$),
