insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$guard$q$),null,1,$q$يقوم بمباشرة عمله قبل حضور منسوبي المدرسة، وفتح وإغلاق باب المدرسة، وانصرافه مع آخر موظف، والتأكد من خلو المدرسة من الطلاب.$q$,$q$يقوم بمباشرة عمله قبل حضور منسوبي المدرسة، وفتح وإغلاق باب المدرسة، وانصرافه مع آخر موظف، والتأكد من خلو المدرسة من الطلاب.$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,2,$q$القيام بحراسة المبنى وما يحتويه.$q$,$q$القيام بحراسة المبنى وما يحتويه.$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,3,$q$عدم السماح لأي شخص بدخول المدرسة أو الخروج منها أثناء وبعد انتهاء الدوام إلا بإذن رسمي.$q$,$q$عدم السماح لأي شخص بدخول المدرسة أو الخروج منها أثناء وبعد انتهاء الدوام إلا بإذن رسمي.$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,4,$q$إبلاغ إدارة المدرسة والجهات المختصة عند حدوث أي طارئ وفق الآلية المعتمدة.$q$,$q$إبلاغ إدارة المدرسة والجهات المختصة عند حدوث أي طارئ وفق الآلية المعتمدة.$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,5,$q$متابعة عمال النظافة والصيانة في أوقات الدراسة وخارجها أثناء القيام بعملهم.$q$,$q$متابعة عمال النظافة والصيانة في أوقات الدراسة وخارجها أثناء القيام بعملهم.$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,6,$q$التأكد من إغلاق الأبواب والنوافذ وإطفاء الأنوار والمكيفات والمراوح ومحابس المياه بعد انتهاء الدوام.$q$,$q$التأكد من إغلاق الأبواب والنوافذ وإطفاء الأنوار والمكيفات والمراوح ومحابس المياه بعد انتهاء الدوام.$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,7,$q$المحافظة على محتويات وممتلكات المدرسة.$q$,$q$المحافظة على محتويات وممتلكات المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,8,$q$القيام بفتح مبنى المدرسة خارج أوقات الدوام الرسمي بعد موافقة إدارة المدرسة.$q$,$q$القيام بفتح مبنى المدرسة خارج أوقات الدوام الرسمي بعد موافقة إدارة المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,9,$q$السماح بدخول ومباشرة الفرق الإسعافية والحالات الطارئة أثناء الدوام الرسمي وفق التنظيمات المعتمدة.$q$,$q$السماح بدخول ومباشرة الفرق الإسعافية والحالات الطارئة أثناء الدوام الرسمي وفق التنظيمات المعتمدة.$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,10,$q$المتابعة والتأكد من البطاقات الشخصية للمسئولين عن نقل الطلاب بالسيارات الخاصة (خاص للطفولة المبكرة).$q$,$q$المتابعة والتأكد من البطاقات الشخصية للمسئولين عن نقل الطلاب بالسيارات الخاصة (خاص للطفولة المبكرة).$q$),
  ((select id from public.guide_jobs where code=$q$guard$q$),null,11,$q$القيام بأي مهام يكلف بها من المسؤول المباشر تتناسب مع مهامه/مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من المسؤول المباشر تتناسب مع مهامه/مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,1,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$,$q$تعزيز قيم الاعتزاز بالدين الإسلامي والانتماء والمواطنة، والمحافظة على أمن الوطن، ومتابعة البرامج والأنشطة الخاصة بذلك.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,2,$q$مرافقة أطفال ومنسوبات الروضة عند الحالات الطارئة.$q$,$q$مرافقة أطفال ومنسوبات الروضة عند الحالات الطارئة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,3,$q$مساعدة المعلمة في فصول رياض الأطفال في الجوانب غير التعليمية.$q$,$q$مساعدة المعلمة في فصول رياض الأطفال في الجوانب غير التعليمية.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,4,$q$مساعدة المناوبات لمراقبة الأطفال قبل وأثناء وبعد الدوام.$q$,$q$مساعدة المناوبات لمراقبة الأطفال قبل وأثناء وبعد الدوام.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,5,$q$عدم السماح لأي من الأطفال بالخروج من المدرسة أثناء الدوام الرسمي إلا بإذن خطي من الإدارة.$q$,$q$عدم السماح لأي من الأطفال بالخروج من المدرسة أثناء الدوام الرسمي إلا بإذن خطي من الإدارة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,6,$q$الاهتمام بمرافق المدرسة وتنظيمها أثناء الدوام المدرسي وفق النظام المتبع في المدرسة.$q$,$q$الاهتمام بمرافق المدرسة وتنظيمها أثناء الدوام المدرسي وفق النظام المتبع في المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,7,$q$مرافقة الأطفال إلى دورات المياه والعناية بهم عند الحاجة.$q$,$q$مرافقة الأطفال إلى دورات المياه والعناية بهم عند الحاجة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,8,$q$تنظيم الفصول والملاعب الداخلية والخارجية أخر الدوام استعداداً لليوم التالي.$q$,$q$تنظيم الفصول والملاعب الداخلية والخارجية أخر الدوام استعداداً لليوم التالي.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,9,$q$القيام بدورها المحدد في خطة الإخلاء المدرسي في الحالات الطارئة.$q$,$q$القيام بدورها المحدد في خطة الإخلاء المدرسي في الحالات الطارئة.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,10,$q$التأكد من خلو المدرسة من جميع (الأطفال) في نهاية الدوام المدرسي.$q$,$q$التأكد من خلو المدرسة من جميع (الأطفال) في نهاية الدوام المدرسي.$q$),
  ((select id from public.guide_jobs where code=$q$kg_service_staff$q$),null,11,$q$القيام بأي مهام يكلف بها من المسؤول المباشر تتناسب مع مهامها/مؤهلاتها.$q$,$q$القيام بأي مهام يكلف بها من المسؤول المباشر تتناسب مع مهامها/مؤهلاتها.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  ((select id from public.guide_jobs where code=$q$service_worker$q$),null,1,$q$القيام بفتح وإقفال الأبواب الداخلية (داخل المدرسة) والنوافذ والأنوار والمكيفات والمراوح ومحابس المياه.$q$,$q$القيام بفتح وإقفال الأبواب الداخلية (داخل المدرسة) والنوافذ والأنوار والمكيفات والمراوح ومحابس المياه.$q$),
  ((select id from public.guide_jobs where code=$q$service_worker$q$),null,2,$q$القيام بأعمال النظافة في الفصول وأفنية المدرسة وممراتها ومرافقها ودورات المياه.$q$,$q$القيام بأعمال النظافة في الفصول وأفنية المدرسة وممراتها ومرافقها ودورات المياه.$q$),
  ((select id from public.guide_jobs where code=$q$service_worker$q$),null,3,$q$تجهيز وتقديم أعمال الضيافة لإدارة المدرسة.$q$,$q$تجهيز وتقديم أعمال الضيافة لإدارة المدرسة.$q$),
  ((select id from public.guide_jobs where code=$q$service_worker$q$),null,4,$q$القيام بنقل المعاملات والأوراق داخل المدرسة، لتسهيل عمل كل من الهيئتين الإدارية والتعليمية.$q$,$q$القيام بنقل المعاملات والأوراق داخل المدرسة، لتسهيل عمل كل من الهيئتين الإدارية والتعليمية.$q$),
  ((select id from public.guide_jobs where code=$q$service_worker$q$),null,5,$q$التأكد من خلو المدرسة في نهاية وقت الدوام.$q$,$q$التأكد من خلو المدرسة في نهاية وقت الدوام.$q$),
  ((select id from public.guide_jobs where code=$q$service_worker$q$),null,6,$q$القيام بأي مهام يكلف بها من المسؤول المباشر تتناسب مع مهامه/مؤهلاته.$q$,$q$القيام بأي مهام يكلف بها من المسؤول المباشر تتناسب مع مهامه/مؤهلاته.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),1,$q$مناقشة الخطة التشغيلية للمدرسة المعدة من قبل لجنة التميز وإقرارها، ومتابعة تنفيذها بعد إعتمادها.$q$,$q$مناقشة الخطة التشغيلية للمدرسة المعدة من قبل لجنة التميز وإقرارها، ومتابعة تنفيذها بعد إعتمادها.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),2,$q$متابعة تنفيذ الخطة التشغيلية المعتمدة، وفقاً لمؤشرات الأداء.$q$,$q$متابعة تنفيذ الخطة التشغيلية المعتمدة، وفقاً لمؤشرات الأداء.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),3,$q$مناقشة تقارير التحصيل الدراسي وتقارير نواتج تعلم الطلاب، وإقرار التوصيات المناسبة لها.$q$,$q$مناقشة تقارير التحصيل الدراسي وتقارير نواتج تعلم الطلاب، وإقرار التوصيات المناسبة لها.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),4,$q$إقرار توزيع الموارد المالية للمدرسة بمختلف أنواعها ومواردها، والمناقلة بين بنود الميزانية التشغيلية وفق الضوابط المنظمة لذلك وإقرار التقارير المالية، والتنسيق مع قسم المالية والمشتريات بإدارة التعليم العامة في إجراءات صرف المبالغ المخصصة.$q$,$q$إقرار توزيع الموارد المالية للمدرسة بمختلف أنواعها ومواردها، والمناقلة بين بنود الميزانية التشغيلية وفق الضوابط المنظمة لذلك وإقرار التقارير المالية، والتنسيق مع قسم المالية والمشتريات بإدارة التعليم العامة في إجراءات صرف المبالغ المخصصة.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),5,$q$مناقشة الجوانب التطويرية للمدرسة وإقرار التوصيات المناسبة.$q$,$q$مناقشة الجوانب التطويرية للمدرسة وإقرار التوصيات المناسبة.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),6,$q$مناقشة التحديات التي تواجه تحقيق أهداف المدرسة واتخاذ التوصيات اللازمة حيالها.$q$,$q$مناقشة التحديات التي تواجه تحقيق أهداف المدرسة واتخاذ التوصيات اللازمة حيالها.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),7,$q$مناقشة الاستعداد المدرسي للعام القادم، وإقرار احتياجات المدرسة من الموارد (البشرية والمادية) ومتابعة توفيرها.$q$,$q$مناقشة الاستعداد المدرسي للعام القادم، وإقرار احتياجات المدرسة من الموارد (البشرية والمادية) ومتابعة توفيرها.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),8,$q$مناقشة القضايا والظواهر السلوكية في المدرسة واتخاذ التوصيات اللازمة حيالها.$q$,$q$مناقشة القضايا والظواهر السلوكية في المدرسة واتخاذ التوصيات اللازمة حيالها.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),9,$q$إقرار تحديد الأنشطة والفعاليات السنوية للمدرسة.$q$,$q$إقرار تحديد الأنشطة والفعاليات السنوية للمدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),10,$q$إقرار عقد الشراكات مع القطاعين القطاعات الحكومية والخاصة وغير الربحية، ومؤسسات المجتمع المحلي المحيطة بالمدرسة لدعم ورعاية برامج المدرسة بما ينسجم مع الأهداف التربوية، وفق الأنظمة واللوائح والتعليمات المنظمة لذلك.$q$,$q$إقرار عقد الشراكات مع القطاعين القطاعات الحكومية والخاصة وغير الربحية، ومؤسسات المجتمع المحلي المحيطة بالمدرسة لدعم ورعاية برامج المدرسة بما ينسجم مع الأهداف التربوية، وفق الأنظمة واللوائح والتعليمات المنظمة لذلك.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),11,$q$إقرار الشراكات مع مؤسسات المجتمع المحلي المحيط بالمدرسة، واقتراح الأنشطة المناسبة لدعم التواصل معها.$q$,$q$إقرار الشراكات مع مؤسسات المجتمع المحلي المحيط بالمدرسة، واقتراح الأنشطة المناسبة لدعم التواصل معها.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),12,$q$إقرار تحديد برامج التوجيه الطلابي وتضمينها في خطة المدرسة.$q$,$q$إقرار تحديد برامج التوجيه الطلابي وتضمينها في خطة المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$administrative_committee$q$),13,$q$مراجعة التقارير الدورية عن برامج وأنشطة الشراكة المجتمعية التي تم تنفيذها وإقرار التوصيات اللازمة.$q$,$q$مراجعة التقارير الدورية عن برامج وأنشطة الشراكة المجتمعية التي تم تنفيذها وإقرار التوصيات اللازمة.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),1,$q$متابعة الخطة السنوية للتوجيه للطلابي في المدرسة، وتوزيع الأسابيع الدراسية حسب التعاميم المنظمة لذلك، وتنفيذها بعد اعتمادها.$q$,$q$متابعة الخطة السنوية للتوجيه للطلابي في المدرسة، وتوزيع الأسابيع الدراسية حسب التعاميم المنظمة لذلك، وتنفيذها بعد اعتمادها.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),2,$q$متابعة تطبيق قواعد السلوك والمواظبة على طلاب المدرسة، وإعداد معايير منح الحوافز للطلبة بهذا الخصوص وتخصيص ميزانية لذلك.$q$,$q$متابعة تطبيق قواعد السلوك والمواظبة على طلاب المدرسة، وإعداد معايير منح الحوافز للطلبة بهذا الخصوص وتخصيص ميزانية لذلك.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),3,$q$متابعة توزيع الطلاب على الفصول حسب ما تراه اللجنة مع بداية العام الدراسي وفقاً للفروق الفردية بين الطلاب والاستعداد والميول.$q$,$q$متابعة توزيع الطلاب على الفصول حسب ما تراه اللجنة مع بداية العام الدراسي وفقاً للفروق الفردية بين الطلاب والاستعداد والميول.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),4,$q$دراسة إضافة حصص علاجية أو إثرائية لبعض المواد الدراسية المقررة في الخطة الدراسية، بالتنسيق مع لجنة التحصيل الدراسي على ألا يترتب على ذلك مبالغ مالية للطلاب أو تعويض مادي للمعلمين وتكون في فراغات جداول المعلمين بما يكمل أنصبتهم الرسمية ولا يخل بخطة المدرسة.$q$,$q$دراسة إضافة حصص علاجية أو إثرائية لبعض المواد الدراسية المقررة في الخطة الدراسية، بالتنسيق مع لجنة التحصيل الدراسي على ألا يترتب على ذلك مبالغ مالية للطلاب أو تعويض مادي للمعلمين وتكون في فراغات جداول المعلمين بما يكمل أنصبتهم الرسمية ولا يخل بخطة المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),5,$q$دراسة سلوك الطلاب ومواظبتهم على مستوى المدرسة، والعمل على تعزيز السلوك الإيجابي ومعالجة السلوك السلبي فيها.$q$,$q$دراسة سلوك الطلاب ومواظبتهم على مستوى المدرسة، والعمل على تعزيز السلوك الإيجابي ومعالجة السلوك السلبي فيها.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),6,$q$متابعة نتائج وأعمال المجالس الطلابية وتقديم الدعم لها وفقاً للتنظيمات والتعليمات المعتمدة، ودراسة التوصيات الواردة منها وعرضها على الأطراف المعنية في المدرسة؛ لاتخاذ الإجراءات اللازمة من قبل إدارة المدرسة.$q$,$q$متابعة نتائج وأعمال المجالس الطلابية وتقديم الدعم لها وفقاً للتنظيمات والتعليمات المعتمدة، ودراسة التوصيات الواردة منها وعرضها على الأطراف المعنية في المدرسة؛ لاتخاذ الإجراءات اللازمة من قبل إدارة المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),7,$q$إعداد التقارير الفصلية عن أعمال التوجيه الطلابي وأعمال اللجنة واعتمادها من مدير المدرسة ليتم رفعها إلى الجهة المختصة بإدارة التعليم العامة.$q$,$q$إعداد التقارير الفصلية عن أعمال التوجيه الطلابي وأعمال اللجنة واعتمادها من مدير المدرسة ليتم رفعها إلى الجهة المختصة بإدارة التعليم العامة.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),8,$q$التوصية بتحويل من لم تتم الموافقة على مواصلتهم الدراسة (متكرري الرسوب) إلى أقرب مدرسة للتعليم المستمر واعتماد التوصية والرفع بها من قبل مدير المدرسة ليتم إشعار قسم التوجيه الطلابي بإدارة التعليم العامة بذلك$q$,$q$التوصية بتحويل من لم تتم الموافقة على مواصلتهم الدراسة (متكرري الرسوب) إلى أقرب مدرسة للتعليم المستمر واعتماد التوصية والرفع بها من قبل مدير المدرسة ليتم إشعار قسم التوجيه الطلابي بإدارة التعليم العامة بذلك$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),9,$q$دراسة أوضاع الطلاب المخالفين لإجراءات سير الاختبارات، وإقرار الخدمات التوجيهية الطلابية اللازمة لهم.$q$,$q$دراسة أوضاع الطلاب المخالفين لإجراءات سير الاختبارات، وإقرار الخدمات التوجيهية الطلابية اللازمة لهم.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),10,$q$دراسة أعذار الطلاب الغائبين عن الاختبارات الفصلية والتحريرية، وإقرار مناسبة مدى وجاهة قبول العذر لدخول الطالب للاختبار البديل خلال الفترة المحددة.$q$,$q$دراسة أعذار الطلاب الغائبين عن الاختبارات الفصلية والتحريرية، وإقرار مناسبة مدى وجاهة قبول العذر لدخول الطالب للاختبار البديل خلال الفترة المحددة.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),11,$q$الإشراف على تنظيم لقاءات مع مؤسسات المجتمع المحلي للمدرسة، ومتابعة نتائجها والرفع بتقاريرها لمدير المدرسة.$q$,$q$الإشراف على تنظيم لقاءات مع مؤسسات المجتمع المحلي للمدرسة، ومتابعة نتائجها والرفع بتقاريرها لمدير المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),12,$q$دراسة الشراكات مع مؤسسات المجتمع المحلي المحيط بالمدرسة، بما يدعم أهداف المدرسة، والرفع بها للجنة الإدارية لإقرارها ثم لمدير المدرسة للاعتماد.$q$,$q$دراسة الشراكات مع مؤسسات المجتمع المحلي المحيط بالمدرسة، بما يدعم أهداف المدرسة، والرفع بها للجنة الإدارية لإقرارها ثم لمدير المدرسة للاعتماد.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),13,$q$اتخاذ القرارات اللازمة بشأن حالات الطلاب الذين لم يتمكنوا من تحقيق مهارات الحد الأدنى وحالات التأخر الدراسي التي لم تبد تجاوباً مع البرامج العلاجية .(المواءمة مع المادة الخامسة في لائحة تقويم الطالب بعد التعديل).$q$,$q$اتخاذ القرارات اللازمة بشأن حالات الطلاب الذين لم يتمكنوا من تحقيق مهارات الحد الأدنى وحالات التأخر الدراسي التي لم تبد تجاوباً مع البرامج العلاجية .(المواءمة مع المادة الخامسة في لائحة تقويم الطالب بعد التعديل).$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),14,$q$متابعة وتقويم برامج رعاية الطلاب ودعمهم في المدرسة.$q$,$q$متابعة وتقويم برامج رعاية الطلاب ودعمهم في المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$student_guidance_committee$q$),15,$q$التواصل مع الجهات الحكومية ذات العلاقة ومنها (مراكز الحماية من العنف الأسري وحماية الطفل) عند اكتشاف حالات الإهمال والإيذاء وعند حدوث الحالات النفسية عالية الخطورة.$q$,$q$التواصل مع الجهات الحكومية ذات العلاقة ومنها (مراكز الحماية من العنف الأسري وحماية الطفل) عند اكتشاف حالات الإهمال والإيذاء وعند حدوث الحالات النفسية عالية الخطورة.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),1,$q$متابعة المستوى التحصيلي للطلاب بشكل دوري وتحليله، ودراسة نتائج الطلاب للعام الدراسي السابق من جميع الجوانب، وإعداد التقارير اللازمة، ورفعها لمدير المدرسة لمناقشتها مع اللجنة الإدارية.$q$,$q$متابعة المستوى التحصيلي للطلاب بشكل دوري وتحليله، ودراسة نتائج الطلاب للعام الدراسي السابق من جميع الجوانب، وإعداد التقارير اللازمة، ورفعها لمدير المدرسة لمناقشتها مع اللجنة الإدارية.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),2,$q$تزويد معلمي المواد الدراسية بالتقارير المعتمدة لتحليل نتائج التحصيل للاختبارات بمختلف أنواعها والمتعلقة بتخصصية موادهم، وتوصيات اللجنة بشأنها.$q$,$q$تزويد معلمي المواد الدراسية بالتقارير المعتمدة لتحليل نتائج التحصيل للاختبارات بمختلف أنواعها والمتعلقة بتخصصية موادهم، وتوصيات اللجنة بشأنها.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),3,$q$مراجعة نتائج الاختبارات الوطنية الخاصة بالمدرسة وتقديم المقترحات لتعزيز نقاط القوة ومعالجة نقاط الضعف.$q$,$q$مراجعة نتائج الاختبارات الوطنية الخاصة بالمدرسة وتقديم المقترحات لتعزيز نقاط القوة ومعالجة نقاط الضعف.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),4,$q$اقتراح البرامج التعليمية والأنشطة الطلابية المناسبة لرفع مستوى التحصيل الدراسي للطلاب في خطة المدرسة، وقياس مدى فاعليتها بعد تنفيذها.$q$,$q$اقتراح البرامج التعليمية والأنشطة الطلابية المناسبة لرفع مستوى التحصيل الدراسي للطلاب في خطة المدرسة، وقياس مدى فاعليتها بعد تنفيذها.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),5,$q$تقديم الدعم للهيئة التعليمية حول المفاهيم والأسس والآليات التي تبنى عليها الاختبارات الوطنية والدولية، وتوفير جميع المتطلبات اللازمة للطلاب قبل تنفيذ الاختبارات الوطنية والدولية.$q$,$q$تقديم الدعم للهيئة التعليمية حول المفاهيم والأسس والآليات التي تبنى عليها الاختبارات الوطنية والدولية، وتوفير جميع المتطلبات اللازمة للطلاب قبل تنفيذ الاختبارات الوطنية والدولية.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),6,$q$تشكيل فرق العمل/اللجان الفرعية للاختبارات الفصلية والنهائية وتحديد مهام ومسؤوليات جميع أعضائها وفقاً للإجراءات المتبعة.$q$,$q$تشكيل فرق العمل/اللجان الفرعية للاختبارات الفصلية والنهائية وتحديد مهام ومسؤوليات جميع أعضائها وفقاً للإجراءات المتبعة.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),7,$q$إعداد جداول الاختبارات الفصلية والسجلات والملفات المتعلقة بالاختبارات في المدرسة.$q$,$q$إعداد جداول الاختبارات الفصلية والسجلات والملفات المتعلقة بالاختبارات في المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),8,$q$استلام مظاريف أوراق الأسئلة والإجابات الخاصة بها، وحفظها في الأماكن الآمنة المخصصة لها.$q$,$q$استلام مظاريف أوراق الأسئلة والإجابات الخاصة بها، وحفظها في الأماكن الآمنة المخصصة لها.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),9,$q$إعداد الكشوفات وأرقام الجلوس للطلاب وتسليمها للفرق الفرعية المسؤولة عن عملية تنظيم الاختبارات.$q$,$q$إعداد الكشوفات وأرقام الجلوس للطلاب وتسليمها للفرق الفرعية المسؤولة عن عملية تنظيم الاختبارات.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),10,$q$توضيح التعليمات للتعامل مع الحالات الطارئة (المرضية ، مخالفة الأنظمة والتعليمات...) أثناء الاختبارات وتهيئة الأدوات والمكان المناسب.$q$,$q$توضيح التعليمات للتعامل مع الحالات الطارئة (المرضية ، مخالفة الأنظمة والتعليمات...) أثناء الاختبارات وتهيئة الأدوات والمكان المناسب.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),11,$q$الإشراف على سير الاختبارات والبرامج التنفيذية المتعلقة بها بمختلف أنواعها بالمدرسة ومتابعتها، والتأكد من مدى سلامتها.$q$,$q$الإشراف على سير الاختبارات والبرامج التنفيذية المتعلقة بها بمختلف أنواعها بالمدرسة ومتابعتها، والتأكد من مدى سلامتها.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),12,$q$متابعة عمليات التصحيح والمراجعة للاختبارات وتدقيق النتائج في المدرسة، ومتابعة أعمال الرصد وإخراج النتائج وتسليمها وحفظها.$q$,$q$متابعة عمليات التصحيح والمراجعة للاختبارات وتدقيق النتائج في المدرسة، ومتابعة أعمال الرصد وإخراج النتائج وتسليمها وحفظها.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),13,$q$تقديم المقترحات التطويرية لآلية الاختبار وتقديمها للجهات المعنية، ومتابعة ومراجعة جميع التعديلات على آليات الاختبارات وتطبيقها.$q$,$q$تقديم المقترحات التطويرية لآلية الاختبار وتقديمها للجهات المعنية، ومتابعة ومراجعة جميع التعديلات على آليات الاختبارات وتطبيقها.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),14,$q$إعداد وتوثيق تقارير دورية عن أعمال اللجنة والمعوقات التي تواجهها ورفعها إلى مدير المدرسة لاتخاذ الإجراء اللازم.$q$,$q$إعداد وتوثيق تقارير دورية عن أعمال اللجنة والمعوقات التي تواجهها ورفعها إلى مدير المدرسة لاتخاذ الإجراء اللازم.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),15,$q$اقتراح برامج معالجة التأخر الدراسي واعتماد الحصص الإضافية لها وتكليف المعلمين وإشعار أولياء الأمور بالبرنامج.$q$,$q$اقتراح برامج معالجة التأخر الدراسي واعتماد الحصص الإضافية لها وتكليف المعلمين وإشعار أولياء الأمور بالبرنامج.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),16,$q$اقتراح البرامج والأنشطة اللاصفية التي تدعم نواتج التعليم والتعلم.$q$,$q$اقتراح البرامج والأنشطة اللاصفية التي تدعم نواتج التعليم والتعلم.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),17,$q$قياس رضا أولياء الأمور عن التحصيل الدراسي ونتائجه، وإشراكهم في معالجات ضعف التحصيل الدراسي لأبنائهم.$q$,$q$قياس رضا أولياء الأمور عن التحصيل الدراسي ونتائجه، وإشراكهم في معالجات ضعف التحصيل الدراسي لأبنائهم.$q$),
  (null,(select id from public.guide_assignments where code=$q$academic_achievement_committee$q$),18,$q$متابعة وقياس مدى فاعلية تطبيق معايير وإجراءات برنامج تحسين الأداء الكتابي والقرائي لدى الطلاب والطالبات في المرحلة الابتدائية، بما يسهم في رفع مستوى التحصيل الدراسي. للطلاب بعد تنفيذ هذه الإجراءات.$q$,$q$متابعة وقياس مدى فاعلية تطبيق معايير وإجراءات برنامج تحسين الأداء الكتابي والقرائي لدى الطلاب والطالبات في المرحلة الابتدائية، بما يسهم في رفع مستوى التحصيل الدراسي. للطلاب بعد تنفيذ هذه الإجراءات.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),1,$q$إعداد الخطة التشغيلية للمدرسة، وربطها بمؤشرات القياس المؤسسي والتخصصي المعتمدة لها ، ووضع توصيات دورية مرتبطة بمؤشرات القياس لضمان التحسين المستمر.$q$,$q$إعداد الخطة التشغيلية للمدرسة، وربطها بمؤشرات القياس المؤسسي والتخصصي المعتمدة لها ، ووضع توصيات دورية مرتبطة بمؤشرات القياس لضمان التحسين المستمر.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),2,$q$إقرار طلبات خدمة دعم التميز المدرسي قبل رفعها لإدارة التعليم العامة.$q$,$q$إقرار طلبات خدمة دعم التميز المدرسي قبل رفعها لإدارة التعليم العامة.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),3,$q$إعداد خطط تقويم الأداء الذاتي والتدقيق الداخلي للمدرسة وفقًا لمعايير تقويم المدارس ومؤشراتها المعتمدة، والإشراف على تنفيذها، ووضع التوصيات التحسينية في ضوء نتائجها، ومتابعة التطوير والاستدامة فيها.$q$,$q$إعداد خطط تقويم الأداء الذاتي والتدقيق الداخلي للمدرسة وفقًا لمعايير تقويم المدارس ومؤشراتها المعتمدة، والإشراف على تنفيذها، ووضع التوصيات التحسينية في ضوء نتائجها، ومتابعة التطوير والاستدامة فيها.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),4,$q$تشجيع المعلمين على تبادل أفضل الممارسات لرفع المستوى التحصيلي لدى الطلاب واقتراح التوصيات اللازمة في تطوير طرق التدريس وأساليب التقويم.$q$,$q$تشجيع المعلمين على تبادل أفضل الممارسات لرفع المستوى التحصيلي لدى الطلاب واقتراح التوصيات اللازمة في تطوير طرق التدريس وأساليب التقويم.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),5,$q$إعداد استطلاعات قياس رضا المستفيدين من خدمات المدرسة، باستثناء استطلاعات التحصيل الدراسي للطلاب، وتحليل النتائج، ووضع التوصيات التحسينية.$q$,$q$إعداد استطلاعات قياس رضا المستفيدين من خدمات المدرسة، باستثناء استطلاعات التحصيل الدراسي للطلاب، وتحليل النتائج، ووضع التوصيات التحسينية.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),6,$q$رصد اتجاهات الطلاب نحو المدرسة، وتقديم التوصيات اللازمة لمدير المدرسة.$q$,$q$رصد اتجاهات الطلاب نحو المدرسة، وتقديم التوصيات اللازمة لمدير المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),7,$q$تقديم الاقتراحات والدعم نحو تحول المدرسة إلى مؤسسة متعلمة ذاتيًا.$q$,$q$تقديم الاقتراحات والدعم نحو تحول المدرسة إلى مؤسسة متعلمة ذاتيًا.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),8,$q$دراسة الملاحظات على برامج التعليم والتعلم، وتقديم التوصيات اللازمة بشأنها.$q$,$q$دراسة الملاحظات على برامج التعليم والتعلم، وتقديم التوصيات اللازمة بشأنها.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),9,$q$دراسة بيئة المدرسة وتقديم المقترحات التطويرية اللازمة بشأنها.$q$,$q$دراسة بيئة المدرسة وتقديم المقترحات التطويرية اللازمة بشأنها.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),10,$q$دراسة الصعوبات والتحديات التي تواجه سير العمل في المدرسة وتقديم التوصيات.$q$,$q$دراسة الصعوبات والتحديات التي تواجه سير العمل في المدرسة وتقديم التوصيات.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),11,$q$المساهمة في نشر ثقافة التميز في المدرسة، وفي دعم وتشجيع المتميزين من منسوبي المدرسة من هيئة تعليمية وإدارية وطلابية.$q$,$q$المساهمة في نشر ثقافة التميز في المدرسة، وفي دعم وتشجيع المتميزين من منسوبي المدرسة من هيئة تعليمية وإدارية وطلابية.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),12,$q$العمل على إعداد وتطوير معايير جوائز التميز والحوافز لمنسوبي المدرسة.$q$,$q$العمل على إعداد وتطوير معايير جوائز التميز والحوافز لمنسوبي المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),13,$q$دراسة تسمية بعض مرافق المدرسة بأسماء أصحاب الإنجازات من منسوبيها.$q$,$q$دراسة تسمية بعض مرافق المدرسة بأسماء أصحاب الإنجازات من منسوبيها.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),14,$q$تمثيل المدرسة في متابعة تنفيذ خطط الإجراءات التقويمية، المصاحبة لتنفيذ عمليات دعم الأداء المدرسي من قبل مقدمي خدمات دعم التميز المدرسي في إدارات التعليم العامة.$q$,$q$تمثيل المدرسة في متابعة تنفيذ خطط الإجراءات التقويمية، المصاحبة لتنفيذ عمليات دعم الأداء المدرسي من قبل مقدمي خدمات دعم التميز المدرسي في إدارات التعليم العامة.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),15,$q$دراسة تقارير تقويم الأداء الخارجي للمدرسة الصادرة عن هيئة تقويم التعليم والتدريب وتحليلها واستثمار نتائجها في التخطيط لتطوير الأداء.$q$,$q$دراسة تقارير تقويم الأداء الخارجي للمدرسة الصادرة عن هيئة تقويم التعليم والتدريب وتحليلها واستثمار نتائجها في التخطيط لتطوير الأداء.$q$),
  (null,(select id from public.guide_assignments where code=$q$excellence_committee$q$),16,$q$ترشيح المدرسة/ منسوبيها لجوائز التميز على المستوى المحلي والإقليمي والعالمي، والرفع لمدير المدرسة لعرض ما يلزم على اللجنة الإدارية.$q$,$q$ترشيح المدرسة/ منسوبيها لجوائز التميز على المستوى المحلي والإقليمي والعالمي، والرفع لمدير المدرسة لعرض ما يلزم على اللجنة الإدارية.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  (null,(select id from public.guide_assignments where code=$q$school_fund_team$q$),1,$q$إعداد الميزانية التشغيلية للمدرسة، شاملة جميع الإيرادات المتوقعة، والبرنامج الزمني للصرف، وعرضها على اللجنة الإدارية للإقرار.$q$,$q$إعداد الميزانية التشغيلية للمدرسة، شاملة جميع الإيرادات المتوقعة، والبرنامج الزمني للصرف، وعرضها على اللجنة الإدارية للإقرار.$q$),
  (null,(select id from public.guide_assignments where code=$q$school_fund_team$q$),2,$q$الصرف من الميزانية التشغيلية وفقاً للبنود المحددة، بعد اعتمادها من اللجنة الإدارية.$q$,$q$الصرف من الميزانية التشغيلية وفقاً للبنود المحددة، بعد اعتمادها من اللجنة الإدارية.$q$),
  (null,(select id from public.guide_assignments where code=$q$school_fund_team$q$),3,$q$مراقبة الصرف وتدقيق المستندات الخاصة بالميزانية التشغيلية.$q$,$q$مراقبة الصرف وتدقيق المستندات الخاصة بالميزانية التشغيلية.$q$),
  (null,(select id from public.guide_assignments where code=$q$school_fund_team$q$),4,$q$مراجعة التقارير الدورية للميزانية، ورفعها للجنة الإدارية.$q$,$q$مراجعة التقارير الدورية للميزانية، ورفعها للجنة الإدارية.$q$),
  (null,(select id from public.guide_assignments where code=$q$school_fund_team$q$),5,$q$إعداد التقرير المالي الختامي لأعمال الصندوق السنوي المدرسي، ورفعه للجنة الإدارية لإقراره.$q$,$q$إعداد التقرير المالي الختامي لأعمال الصندوق السنوي المدرسي، ورفعه للجنة الإدارية لإقراره.$q$),
  (null,(select id from public.guide_assignments where code=$q$school_fund_team$q$),6,$q$العمل على تنمية موارد المدرسة لمساعدتها في تحقيق أهدافها وفقاً للأنظمة والتعليمات.$q$,$q$العمل على تنمية موارد المدرسة لمساعدتها في تحقيق أهدافها وفقاً للأنظمة والتعليمات.$q$),
  (null,(select id from public.guide_assignments where code=$q$school_fund_team$q$),7,$q$قيد إيرادات ومصروفات الصندوق وتدوينها في السجلات الإلكترونية/ورقية المخصصة لذلك، وفقاً للضوابط المنظمة لذلك.$q$,$q$قيد إيرادات ومصروفات الصندوق وتدوينها في السجلات الإلكترونية/ورقية المخصصة لذلك، وفقاً للضوابط المنظمة لذلك.$q$),
  (null,(select id from public.guide_assignments where code=$q$school_fund_team$q$),8,$q$حصر التبرعات الواردة للمدرسة ،وتوثيقها وفق الضوابط المنظمة لذلك.$q$,$q$حصر التبرعات الواردة للمدرسة ،وتوثيقها وفق الضوابط المنظمة لذلك.$q$),
  (null,(select id from public.guide_assignments where code=$q$school_fund_team$q$),9,$q$تقديم التقرير المالي السنوي لأعمال الصندوق المدرسي للجهات المختصة في إدارة التعليم العامة.$q$,$q$تقديم التقرير المالي السنوي لأعمال الصندوق المدرسي للجهات المختصة في إدارة التعليم العامة.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),1,$q$تنفيذ البرامج والأنشطة المعتمدة المتعلقة بالأمن والسلامة واستمرارية الأعمال.$q$,$q$تنفيذ البرامج والأنشطة المعتمدة المتعلقة بالأمن والسلامة واستمرارية الأعمال.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),2,$q$تقويم وضع الأمن والسلامة في المدرسة، وفق الاستمارات والأدوات المعدَّة لذلك.$q$,$q$تقويم وضع الأمن والسلامة في المدرسة، وفق الاستمارات والأدوات المعدَّة لذلك.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),3,$q$تكليف أحد إداريّ المدرسة للعمل كمنسق للأمن والسلامة وفق الضوابط المعتمدة لذلك، وتكليفه بالمهام المرتبطة بعمليات الأمن والسلامة المدرسية ذات العلاقة.$q$,$q$تكليف أحد إداريّ المدرسة للعمل كمنسق للأمن والسلامة وفق الضوابط المعتمدة لذلك، وتكليفه بالمهام المرتبطة بعمليات الأمن والسلامة المدرسية ذات العلاقة.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),4,$q$الرفع بتقارير الأمن والسلامة وإدارة المخاطر واستمرارية الأعمال إلى اللجنة الإدارية خلال الفترة المنصوص عليها في قرار التشكيل.$q$,$q$الرفع بتقارير الأمن والسلامة وإدارة المخاطر واستمرارية الأعمال إلى اللجنة الإدارية خلال الفترة المنصوص عليها في قرار التشكيل.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),5,$q$الرفع الفوري بأي مهددات للأمن والسلامة المدرسية للجنة الإدارية.$q$,$q$الرفع الفوري بأي مهددات للأمن والسلامة المدرسية للجنة الإدارية.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),6,$q$التنسيق والتعاون مع الجهات المختصة لعقد برامج وورش عمل لمنسوبي المدرسة فيما يخص الأمن والسلامة واستمرارية الأعمال، والتواصل مع الشركة المنفذة فيما يخص متطلبات الأمن والسلامة والمرافق.$q$,$q$التنسيق والتعاون مع الجهات المختصة لعقد برامج وورش عمل لمنسوبي المدرسة فيما يخص الأمن والسلامة واستمرارية الأعمال، والتواصل مع الشركة المنفذة فيما يخص متطلبات الأمن والسلامة والمرافق.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),7,$q$التأكد من تطبيق شروط وقواعد السلامة الكفيلة بحماية منسوبي المدرسة خلال تنفيذ الأعمال داخل المدرسة وبما يتفق مع اللوائح والأنظمة والأدلة التفصيلية للأمن والسلامة واستمرارية الأعمال والعمليات المتعلقة بها.$q$,$q$التأكد من تطبيق شروط وقواعد السلامة الكفيلة بحماية منسوبي المدرسة خلال تنفيذ الأعمال داخل المدرسة وبما يتفق مع اللوائح والأنظمة والأدلة التفصيلية للأمن والسلامة واستمرارية الأعمال والعمليات المتعلقة بها.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),8,$q$التأكد من مراعاة احتياجات الأمن والسلامة للطلاب ذوي الإعاقة (في المدارس التي تتضمن برامجاً لذوي الإعاقة).$q$,$q$التأكد من مراعاة احتياجات الأمن والسلامة للطلاب ذوي الإعاقة (في المدارس التي تتضمن برامجاً لذوي الإعاقة).$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),9,$q$إعداد التدريبات لمنسوبي المدرسة على خطة الإخلاء في الحالات الطارئة، والاستعانة بمتخصصين لإقامة دورة إسعافات أولية.$q$,$q$إعداد التدريبات لمنسوبي المدرسة على خطة الإخلاء في الحالات الطارئة، والاستعانة بمتخصصين لإقامة دورة إسعافات أولية.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),10,$q$تحديد احتياجات المدرسة من أجهزة الأمن والسلامة والإيواء والتجهيزات المدرسية والمرافق التعليمية والإدارية، والرفع بها للجنة الإدارية.$q$,$q$تحديد احتياجات المدرسة من أجهزة الأمن والسلامة والإيواء والتجهيزات المدرسية والمرافق التعليمية والإدارية، والرفع بها للجنة الإدارية.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),11,$q$رفع البلاغات الخاصة بالخدمات التشغيلية عبر النظام.$q$,$q$رفع البلاغات الخاصة بالخدمات التشغيلية عبر النظام.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),12,$q$متابعة عمل الحارس/ حراس الأمن في المدرسة.$q$,$q$متابعة عمل الحارس/ حراس الأمن في المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),13,$q$إقرار سجل التنظيم الخاص بدخول زوار المدرسة أثناء اليوم الدراسي.$q$,$q$إقرار سجل التنظيم الخاص بدخول زوار المدرسة أثناء اليوم الدراسي.$q$),
  (null,(select id from public.guide_assignments where code=$q$safety_security_facilities_team$q$),14,$q$إقرار ومراجعة سجلات الأمن والسلامة.$q$,$q$إقرار ومراجعة سجلات الأمن والسلامة.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  (null,(select id from public.guide_assignments where code=$q$disability_team$q$),1,$q$المشاركة في إجراء عمليات القياس والتشخيص للطلاب ذوي الإعاقة.$q$,$q$المشاركة في إجراء عمليات القياس والتشخيص للطلاب ذوي الإعاقة.$q$),
  (null,(select id from public.guide_assignments where code=$q$disability_team$q$),2,$q$تحديد أهلية الطلاب ذوي الإعاقة بناء على نتائج القياس والتشخيص.$q$,$q$تحديد أهلية الطلاب ذوي الإعاقة بناء على نتائج القياس والتشخيص.$q$),
  (null,(select id from public.guide_assignments where code=$q$disability_team$q$),3,$q$تقويم الخدمات ومن ضمنها غرف المصادر (طلاب ذوي الإعاقة) المقدمة للطلاب ومدى استفادتهم منها.$q$,$q$تقويم الخدمات ومن ضمنها غرف المصادر (طلاب ذوي الإعاقة) المقدمة للطلاب ومدى استفادتهم منها.$q$),
  (null,(select id from public.guide_assignments where code=$q$disability_team$q$),4,$q$تحويل الطلاب ذوي الإعاقة إلى مراكز الخدمات المساندة المعتمدة لدى وزارة التعليم لإجراء عمليات القياس والتشخيص وتقديم الجلسات المساندة.$q$,$q$تحويل الطلاب ذوي الإعاقة إلى مراكز الخدمات المساندة المعتمدة لدى وزارة التعليم لإجراء عمليات القياس والتشخيص وتقديم الجلسات المساندة.$q$),
  (null,(select id from public.guide_assignments where code=$q$disability_team$q$),5,$q$تقويم البرنامج التربوي الفردي للطالب ذوي الإعاقة بشكل دوري.$q$,$q$تقويم البرنامج التربوي الفردي للطالب ذوي الإعاقة بشكل دوري.$q$),
  (null,(select id from public.guide_assignments where code=$q$disability_team$q$),6,$q$متابعة مستوى التقدم لدى الطلاب اللذين يواجهون صعوبات في التعلم والطلاب ذوي الإعاقة في المدرسة ولدى الطلاب المستهدفين منهم خاصة.$q$,$q$متابعة مستوى التقدم لدى الطلاب اللذين يواجهون صعوبات في التعلم والطلاب ذوي الإعاقة في المدرسة ولدى الطلاب المستهدفين منهم خاصة.$q$),
  (null,(select id from public.guide_assignments where code=$q$disability_team$q$),7,$q$إعداد التدريبات لمنسوبي المدرسة لتعريفهم ببرامج ذوي الإعاقة وكيفية التعامل معهم.$q$,$q$إعداد التدريبات لمنسوبي المدرسة لتعريفهم ببرامج ذوي الإعاقة وكيفية التعامل معهم.$q$);
insert into public.guide_duties(job_id,assignment_id,seq,body,original_body) values
  (null,(select id from public.guide_assignments where code=$q$school$q$),1,$q$تربية النشء تربية صحيحة تهدف إلى رعاية نموه دينيًا وخلقيًا وفكريًا واجتماعيًا ونفسيًا وجسديًا، ومساعدته على تكوين شخصيته.$q$,$q$تربية النشء تربية صحيحة تهدف إلى رعاية نموه دينيًا وخلقيًا وفكريًا واجتماعيًا ونفسيًا وجسديًا، ومساعدته على تكوين شخصيته.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),2,$q$تزويد الطالب بما يحتاج إليه من العلوم والآداب والتدريبات العملية حتى يكون مواطنًا صالحًا مدركًا لواجباته وحقوقه ومعتزاً بإسلامه ووطنه ووفيًا لعروبته.$q$,$q$تزويد الطالب بما يحتاج إليه من العلوم والآداب والتدريبات العملية حتى يكون مواطنًا صالحًا مدركًا لواجباته وحقوقه ومعتزاً بإسلامه ووطنه ووفيًا لعروبته.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),3,$q$إعداد الطالب للحياة العامة وإكسابه مهارات تؤهله للمراحل القادمة والحياة خارج المدرسة.$q$,$q$إعداد الطالب للحياة العامة وإكسابه مهارات تؤهله للمراحل القادمة والحياة خارج المدرسة.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),4,$q$تنمية مهارات الطالب العلمية والسلوكية، والتغلّب على المشكلات لدى الطلاب (التحصيلية والسلوكية) والعمل على معالجتها.$q$,$q$تنمية مهارات الطالب العلمية والسلوكية، والتغلّب على المشكلات لدى الطلاب (التحصيلية والسلوكية) والعمل على معالجتها.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),5,$q$تحسين مستوى التحصيل الدراسي للطالب بشكل مستمر.$q$,$q$تحسين مستوى التحصيل الدراسي للطالب بشكل مستمر.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),6,$q$تنمية انتماء الطالب لدينه ووطنه والاعتزاز بهما والولاء لقيادة وطنه وأهمية المحافظة على هذه الثوابت لديه.$q$,$q$تنمية انتماء الطالب لدينه ووطنه والاعتزاز بهما والولاء لقيادة وطنه وأهمية المحافظة على هذه الثوابت لديه.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),7,$q$تعزيز الاتجاهات الإيجابية بين منسوبي المدرسة وأولياء الأمور.$q$,$q$تعزيز الاتجاهات الإيجابية بين منسوبي المدرسة وأولياء الأمور.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),8,$q$المساهمة في التصدي للمشكلات التي تضر بالمجتمع.$q$,$q$المساهمة في التصدي للمشكلات التي تضر بالمجتمع.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),9,$q$تفعيل التعليم الإلكتروني وتشجيعه بقنواته المختلفة ومنصاته المعتمدة، وتطبيق الممارسات الإدارية والتعليمية المتعارف عليها بما يتناسب مع احتياجات العملية التعليمية ويرفع جودتها.$q$,$q$تفعيل التعليم الإلكتروني وتشجيعه بقنواته المختلفة ومنصاته المعتمدة، وتطبيق الممارسات الإدارية والتعليمية المتعارف عليها بما يتناسب مع احتياجات العملية التعليمية ويرفع جودتها.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),10,$q$تزويد الطالب بما يحتاج إليه من المعارف والمهارات لدعم النمو العقلي والجسدي والانفعالي والاجتماعي لديه.$q$,$q$تزويد الطالب بما يحتاج إليه من المعارف والمهارات لدعم النمو العقلي والجسدي والانفعالي والاجتماعي لديه.$q$),
  (null,(select id from public.guide_assignments where code=$q$school$q$),11,$q$تنمية الوعي الصحي للطلاب والمجتمع المدرسي بهدف توفير بيئة صحية تحقق أهداف المدرسة.$q$,$q$تنمية الوعي الصحي للطلاب والمجتمع المدرسي بهدف توفير بيئة صحية تحقق أهداف المدرسة.$q$),
