-- 0030 · دليل الوظائف والتكليفات المدرسية (مرجع الدليل التنظيمي: دليل الأهداف والمهام)
-- جداول مستقلة بالبادئة guide_ لا تمس وحدة التكليفات (0029). القراءة لكل مستخدم موثّق؛ الكتابة عبر دوال تتحقق من الصلاحية assignments:manage.


-- 1) المسميات الوظيفية
create table if not exists public.guide_jobs (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  title text not null,
  subtitle text,
  org_link text[] not null default '{}',
  objective text,
  min_qualifications text[] not null default '{}',
  competencies text,
  notes text[] not null default '{}',
  sort_order int not null default 0,
  is_original boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- 2) التكليفات (لجان / فرق عمل / وحدة تنظيمية)
create table if not exists public.guide_assignments (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  kind text not null check (kind in ('committee','team','org_unit')),
  title text not null,
  full_title text,
  org_link text[] not null default '{}',
  objective text,
  formation_rules text[] not null default '{}',
  meeting_rules text[] not null default '{}',
  notes text[] not null default '{}',
  sort_order int not null default 0,
  is_original boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- 3) المهام والمسؤوليات: كل مهمة سجل مستقل مرتبط بوظيفة أو بتكليف
create table if not exists public.guide_duties (
  id uuid primary key default gen_random_uuid(),
  job_id uuid references public.guide_jobs(id) on delete cascade,
  assignment_id uuid references public.guide_assignments(id) on delete cascade,
  seq int not null,
  body text not null,
  original_body text,            -- النص الأصلي من الدليل (لا يُعدَّل)
  is_original boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint guide_duties_one_owner check ((job_id is null) <> (assignment_id is null))
);
create index if not exists guide_duties_job_idx on public.guide_duties(job_id, seq);
create index if not exists guide_duties_assignment_idx on public.guide_duties(assignment_id, seq);

-- 4) العلاقات بين الوظائف والتكليفات (عضوية اللجان وفرق العمل)
create table if not exists public.guide_assignment_links (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.guide_assignments(id) on delete cascade,
  job_id uuid references public.guide_jobs(id) on delete set null,
  seq int not null,
  member_text text not null,     -- كما ورد في الدليل
  role_text text,                -- الصفة داخل اللجنة/الفريق
  created_at timestamptz not null default now()
);
create index if not exists guide_links_assignment_idx on public.guide_assignment_links(assignment_id, seq);
create index if not exists guide_links_job_idx on public.guide_assignment_links(job_id);

alter table public.guide_jobs enable row level security;
alter table public.guide_assignments enable row level security;
alter table public.guide_duties enable row level security;
alter table public.guide_assignment_links enable row level security;

drop policy if exists guide_jobs_read on public.guide_jobs;
create policy guide_jobs_read on public.guide_jobs for select to authenticated using (true);
drop policy if exists guide_assignments_read on public.guide_assignments;
create policy guide_assignments_read on public.guide_assignments for select to authenticated using (true);
drop policy if exists guide_duties_read on public.guide_duties;
create policy guide_duties_read on public.guide_duties for select to authenticated using (true);
drop policy if exists guide_links_read on public.guide_assignment_links;
create policy guide_links_read on public.guide_assignment_links for select to authenticated using (true);

-- التدقيق
drop trigger if exists a_guide_jobs on public.guide_jobs;
create trigger a_guide_jobs after insert or delete or update on public.guide_jobs for each row execute function public.audit_generic();
drop trigger if exists a_guide_assignments on public.guide_assignments;
create trigger a_guide_assignments after insert or delete or update on public.guide_assignments for each row execute function public.audit_generic();
drop trigger if exists a_guide_duties on public.guide_duties;
create trigger a_guide_duties after insert or delete or update on public.guide_duties for each row execute function public.audit_generic();
drop trigger if exists a_guide_links on public.guide_assignment_links;
create trigger a_guide_links after insert or delete or update on public.guide_assignment_links for each row execute function public.audit_generic();

-- دوال الكتابة (للإدارة فقط). النص الأصلي للمهمة original_body لا يُعدَّل أبدًا.
create or replace function public.guide_job_save(p_id uuid, p jsonb) returns uuid language plpgsql security definer set search_path = '' as $$
declare v uuid;
begin
  if not public.core_can('assignments:manage') then raise exception 'غير مصرح'; end if;
  if nullif(btrim(p->>'title'),'') is null then raise exception 'المسمى الوظيفي مطلوب'; end if;
  if p_id is null then
    values ('custom-'||substr(gen_random_uuid()::text,1,8), btrim(p->>'title'), nullif(btrim(p->>'subtitle'),''), nullif(btrim(p->>'objective'),''),
      coalesce(array(select jsonb_array_elements_text(p->'org_link')),'{}'), coalesce(array(select jsonb_array_elements_text(p->'notes')),'{}'),
      coalesce((select max(sort_order) from public.guide_jobs),0)+1, false) returning id into v;
  else
    update public.guide_jobs set title=btrim(p->>'title'), subtitle=nullif(btrim(p->>'subtitle'),''), objective=nullif(btrim(p->>'objective'),''),
      org_link=coalesce(array(select jsonb_array_elements_text(p->'org_link')),'{}'), notes=coalesce(array(select jsonb_array_elements_text(p->'notes')),'{}'), updated_at=now()
    where id=p_id returning id into v;
    if v is null then raise exception 'المسمى غير موجود'; end if;
  end if;
  return v;
end $$;

create or replace function public.guide_assignment_save(p_id uuid, p jsonb) returns uuid language plpgsql security definer set search_path = '' as $$
declare v uuid; j text; n int;
begin
  if not public.core_can('assignments:manage') then raise exception 'غير مصرح'; end if;
  if nullif(btrim(p->>'title'),'') is null then raise exception 'عنوان التكليف مطلوب'; end if;
  if (p->>'kind') not in ('committee','team','org_unit') then raise exception 'نوع التكليف غير صحيح'; end if;
  if p_id is null then
    values ('custom-'||substr(gen_random_uuid()::text,1,8), p->>'kind', btrim(p->>'title'), nullif(btrim(p->>'full_title'),''), nullif(btrim(p->>'objective'),''),
      coalesce(array(select jsonb_array_elements_text(p->'org_link')),'{}'), coalesce(array(select jsonb_array_elements_text(p->'notes')),'{}'),
      coalesce((select max(sort_order) from public.guide_assignments),0)+1, false) returning id into v;
  else
    update public.guide_assignments set kind=p->>'kind', title=btrim(p->>'title'), full_title=nullif(btrim(p->>'full_title'),''), objective=nullif(btrim(p->>'objective'),''),
      org_link=coalesce(array(select jsonb_array_elements_text(p->'org_link')),'{}'), notes=coalesce(array(select jsonb_array_elements_text(p->'notes')),'{}'), updated_at=now()
    where id=p_id returning id into v;
    if v is null then raise exception 'التكليف غير موجود'; end if;
  end if;
  -- ربط التكليف بوظيفة أو أكثر (يُضاف فقط ما لم يكن مرتبطًا)
  if p ? 'job_ids' then
    for j in select jsonb_array_elements_text(p->'job_ids') loop
      if not exists (select 1 from public.guide_assignment_links where assignment_id=v and job_id=j::uuid) then
        select coalesce(max(seq),0)+1 into n from public.guide_assignment_links where assignment_id=v;
      end if;
    end loop;
  end if;
  return v;
end $$;

create or replace function public.guide_link_remove(p_id uuid) returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.core_can('assignments:manage') then raise exception 'غير مصرح'; end if;
  delete from public.guide_assignment_links where id=p_id;
end $$;

create or replace function public.guide_assignment_delete(p_id uuid) returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.core_can('assignments:manage') then raise exception 'غير مصرح'; end if;
  delete from public.guide_assignments where id=p_id and is_original=false;
  if not found then raise exception 'تُحذف التكليفات المضافة يدويًا فقط؛ تكليفات الدليل الأصلية محفوظة'; end if;
end $$;

create or replace function public.guide_duty_save(p_id uuid, p_job uuid, p_assignment uuid, p_body text) returns uuid language plpgsql security definer set search_path = '' as $$
declare v uuid;
begin
  if not public.core_can('assignments:manage') then raise exception 'غير مصرح'; end if;
  if nullif(btrim(p_body),'') is null then raise exception 'نص المهمة مطلوب'; end if;
  if p_id is null then
    if (p_job is null) = (p_assignment is null) then raise exception 'حدد وظيفة أو تكليفًا واحدًا'; end if;
    values (p_job, p_assignment, coalesce((select max(seq) from public.guide_duties where job_id is not distinct from p_job and assignment_id is not distinct from p_assignment),0)+1, btrim(p_body), null, false)
    returning id into v;
  else
    update public.guide_duties set body=btrim(p_body), is_original=(original_body is not null and btrim(p_body)=original_body), updated_at=now() where id=p_id returning id into v;
    if v is null then raise exception 'المهمة غير موجودة'; end if;
  end if;
  return v;
end $$;

create or replace function public.guide_duty_delete(p_id uuid) returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.core_can('assignments:manage') then raise exception 'غير مصرح'; end if;
  delete from public.guide_duties where id=p_id;
end $$;

revoke all on function public.guide_job_save(uuid,jsonb), public.guide_assignment_save(uuid,jsonb), public.guide_link_remove(uuid), public.guide_assignment_delete(uuid), public.guide_duty_save(uuid,uuid,uuid,text), public.guide_duty_delete(uuid) from public, anon;
grant execute on function public.guide_job_save(uuid,jsonb), public.guide_assignment_save(uuid,jsonb), public.guide_link_remove(uuid), public.guide_assignment_delete(uuid), public.guide_duty_save(uuid,uuid,uuid,text), public.guide_duty_delete(uuid) to authenticated;


-- صلاحية القراءة على الجداول (تُقيَّد بسياسات RLS أعلاه)
grant select on public.guide_jobs, public.guide_assignments, public.guide_duties, public.guide_assignment_links to authenticated;
